INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507be5e5-55e0-4a91-838f-60b67a5f5e4b', '題惠山泉（二首） 二', '題惠山泉（二首） 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["馬卿消瘦年纔有，陸羽茶門近始閒。","時借僧爐拾寒葉，自來林下煮潺湲。","（元《無錫縣志》卷四上辭章詠歌。","又明《弘治無錫縣志》二八《詞章》）。"]', '["马卿消瘦年纔有，陸羽茶门近始閒。","时借僧爐拾寒葉，自来林下煮潺湲。","（元《無錫縣志》卷四上辞章詠歌。","又明《弘治無錫縣志》二八《词章》）。"]', '诗', 'shi', '', NULL, '題惠山泉（二首） 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cfdb3f4-8f4a-49ec-92f4-0c87fbdc5798', '泰伯廟', '泰伯廟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蠻荆古服屬南荒，大聖開基闢草堂。","載造文明追二帝，尚餘揖讓補三王。"]', '["蠻荆古服屬南荒，大聖开基闢草堂。","載造文明追二帝，尚餘揖讓補三王。"]', '诗', 'shi', '', NULL, '泰伯廟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b0576e-284a-4005-86db-29d3b32f40ee', '望虞亭', '望虞亭', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["盤迴曲澗數峯青，雲護皇山一古亭。","千里月明回首望，飛烟冲起海虞濱。","（以上清初《梅里志》三《詩》）。"]', '["盤迴曲澗數峯青，云護皇山一古亭。","千里月明回首望，飞烟冲起海虞濱。","（以上清初《梅里志》三《诗》）。"]', '诗', 'shi', '', NULL, '望虞亭 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b9b4868-1ef9-4ac5-bb07-de003469d2c9', '松江秋書', '松江秋书', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["張翰深心怕禍機，不緣蓴脆與鱸肥。","如何狗世浮沉去，可要拋官獨自歸？","風度野烟侵醉帽，雨來秋浪濺吟衣。","無人好尚無人責，吟嘯低頭又掩扉。","（《百城烟水》四《吳江》）。"]', '["張翰深心怕禍機，不緣蓴脆與鱸肥。","如何狗世浮沉去，可要拋官独自归？","风度野烟侵醉帽，雨来秋浪濺吟衣。","無人好尚無人責，吟嘯低头又掩扉。","（《百城烟水》四《吳江》）。"]', '诗', 'shi', '', NULL, '松江秋書 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcb5bee-11c4-454b-95e5-5196d8ca9975', '蓬傘', '蓬傘', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["吾江善編蓬，圓者柄爲傘。","所至以自隨，清陰覆一墠。","自吾爲此計，簑笠□□短。","何須詣亭陰，風雨皆足緩。"]', '["吾江善編蓬，圓者柄爲傘。","所至以自隨，清陰覆一墠。","自吾爲此計，簑笠□□短。","何須詣亭陰，风雨皆足緩。"]', '诗', 'shi', '', NULL, '蓬傘 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ae706f-bb86-4a05-9d4e-8436c4b951a5', '謝人詩卷（句）', '謝人诗卷（句）', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["談仙忽似朝金母，說艷渾如見玉兒。","（以上吳聿《觀林詩話》）。"]', '["談仙忽似朝金母，说艷渾如见玉兒。","（以上吳聿《观林诗話》）。"]', '诗', 'shi', '', NULL, '謝人詩卷（句） 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77561997-eb56-4873-9df5-7beca7a1eec6', '{巩/言}光大師草書歌', '{巩/言}光大師草书歌', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["羸病愛師書勁逸，翻作長歌助狂筆。","乘高攂鼓震川原，驚迸驊騮幾千匹。","落筆縱橫不離禪，方知草聖本非顛。","歌成與掃松齋壁，何似曾題《說劍篇》。","（《六藝之一錄》二九○引朱長文《墨池編》十三原書目錄作{巩/言}光詩）（《四庫全書》本《墨池編》卷四錄此詩無作者，附司空圖《書屏記》後。","《宣和書譜》卷九錄司空圖贈{巩/言}光詩云：「看）（師逸說蹟兩相宜，高適歌行李白詩」，此詩中無。","是砧圖作，頗可疑。","）。"]', '["羸病愛師书勁逸，翻作长歌助狂笔。","乘高攂鼓震川原，驚迸驊騮幾千匹。","落笔縱橫不離禪，方知草聖本非顛。","歌成與掃松斋壁，何似曾題《说劍篇》。","（《六藝之一錄》二九○引朱长文《墨池編》十三原书目錄作{巩/言}光诗）（《四庫全书》本《墨池編》卷四錄此诗無作者，附司空圖《书屏記》後。","《宣和书譜》卷九錄司空圖贈{巩/言}光诗云：「看）（師逸说蹟兩相宜，高適歌行李白诗」，此诗中無。","是砧圖作，頗可疑。","）。"]', '诗', 'shi', '', NULL, '{巩/言}光大師草書歌 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f456597-e3ca-44eb-90c5-03a466420996', '恭州界（舊《圖經》及《寰宇記》、《九域志》皆日渝州，《輿地廣記》曰恭州。）', '恭州界（旧《圖經》及《寰宇記》、《九域志》皆日渝州，《輿地廣記》曰恭州。）', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["山容地脈本清涼，不解爲霖卻作湯。","草木龜魚困薰煮，漫贏塵垢涴僧坊。","（《輿地紀勝》一七五《重慶府》）。"]', '["山容地脈本清涼，不解爲霖卻作湯。","草木龟鱼困薰煮，漫贏塵垢涴僧坊。","（《輿地紀勝》一七五《重慶府》）。"]', '诗', 'shi', '', NULL, '恭州界（舊《圖經》及《寰宇記》、《九域志》皆日渝州，《輿地廣記》曰恭州。） 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e0200d7-52a0-44a4-9d77-b4ac57629351', '春晚（句）', '春晚（句）', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["憑高憐酒韻，引滿未能已。"]', '["憑高怜酒韻，引满未能已。"]', '诗', 'shi', '', NULL, '春晚（句） 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8ef7f3d-0f09-4eb8-9b0e-5267294276d0', '撫事寄同游（句）', '撫事寄同游（句）', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["春添茶韻時過寺。","（以上元李治《敬齋古今黈逸文》二）。"]', '["春添茶韻时過寺。","（以上元李治《敬斋古今黈逸文》二）。"]', '诗', 'shi', '', NULL, '撫事寄同游（句） 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77dcf474-032b-4ced-859e-0490813b5e5a', '過平泉莊（李朱厓〖德裕〗平泉莊，佳景可愛。洛中士人詫於「汪」〖江〗遵，遵有詩曰：）', '過平泉莊（李朱厓〖德裕〗平泉莊，佳景可愛。洛中士人詫於「汪」〖江〗遵，遵有诗曰：）', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["平泉風景好高眠，水色風光滿目前。","剛欲平他不平事，至今惆悵滿南遷。","（今按：此一首與《唐詩紀事》及《全唐詩》字句多不同。","）。"]', '["平泉风景好高眠，水色风光满目前。","剛欲平他不平事，至今惆悵满南遷。","（今按：此一首與《唐诗紀事》及《全唐诗》字句多不同。","）。"]', '诗', 'shi', '', NULL, '過平泉莊（李朱厓〖德裕〗平泉莊，佳景可愛。洛中士人詫於「汪」〖江〗遵，遵有詩曰：） 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1782bedd-b79a-4f65-84a4-60987c36f31e', '又過楊相宅', '又過楊相宅', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["倚伏從來事不遙，無何平地起青霄。","纔到青霄却平地，門對古槐空寂寥。","（以上《詩話總龜》二四《感事門》引《唐賢抒情》）（〖1〗《萬首唐人絕句》卷六九以此詩爲尹璞作，文字稍異。","《全唐詩》卷五一七收尹璞名下，幷注出《抒情錄》作江遵詩之異文。","）。"]', '["倚伏從来事不遙，無何平地起青霄。","纔到青霄却平地，门对古槐空寂寥。","（以上《诗話總龟》二四《感事门》引《唐賢抒情》）（〖1〗《万首唐人絕句》卷六九以此诗爲尹璞作，文字稍異。","《全唐诗》卷五一七收尹璞名下，幷注出《抒情錄》作江遵诗之異文。","）。"]', '诗', 'shi', '', NULL, '又過楊相宅 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d457994a-b968-47f2-8316-594d0bf1b31a', '句', '句', 'd285fe3a-99d9-47c4-b6d5-c0eea2b02754', '唐', '["願假中流便，滋茲發棹歌。","（《古今圖書集成·友誼典·請託部》選句。","此二句疑非童詩。","但應爲誰作，尚俟考詳。","）。"]', '["願假中流便，滋茲發棹歌。","（《古今圖书集成·友誼典·請託部》選句。","此二句疑非童诗。","但應爲誰作，尚俟考詳。","）。"]', '诗', 'shi', '', NULL, '句 童漢卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4e3829-10fd-46f6-ab43-7ff548f4fb8d', '詠柳', '詠柳', 'd285fe3a-99d9-47c4-b6d5-c0eea2b02754', '唐', '["灞橋晴來送別頻，相偎相依不勝春。","自家飛絮猶無定，爭把長條絆得人。","（《詩話總龜》二一《詠物門》引羅隱《績本事詩》。","按此處注出處引錄有誤。","《詩話總龜》此條原注云：「《唐宋詩》云羅隱作。","《續本事詩》。","」《唐宋詩》指宋初人編《唐宋類詩》。","《續本事詩》則爲吳處常子作，非羅隱作。","《全唐詩》卷六五七收作羅隱《柳》詩，另《甲乙集》卷三、《才調集》卷八、《文苑英華》卷三二四亦作羅詩。","因《續本事詩》成書之時較早，姑仍兩存之。","）。"]', '["灞橋晴来送別頻，相偎相依不勝春。","自家飞絮猶無定，爭把长條絆得人。","（《诗話總龟》二一《詠物门》引羅隐《績本事诗》。","按此处注出处引錄有誤。","《诗話總龟》此條原注云：「《唐宋诗》云羅隐作。","《續本事诗》。","」《唐宋诗》指宋初人編《唐宋類诗》。","《續本事诗》則爲吳处常子作，非羅隐作。","《全唐诗》卷六五七收作羅隐《柳》诗，另《甲乙集》卷三、《才調集》卷八、《文苑英华》卷三二四亦作羅诗。","因《續本事诗》成书之时較早，姑仍兩存之。","）。"]', '诗', 'shi', '', NULL, '詠柳 童漢卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5066b72b-1708-409b-9e64-7e5320c648a1', '代張孜幻夢李白歌', '代張孜幻梦李白歌', '26db398d-83ab-4071-9fce-c38ac49e34f7', '唐', '["天使翰林生我前，相去歿（一作「後」）來二百年。","英神傑（一作「絕」）氣歸玄天，日月星辰空蹙然。","我識翰林文，不識翰林面。","上天知我憶其人，使向人間夢中見。","瑞光閃爍天關（一作「門」）開，五雲著地長裾來，華山秀作英雄骨，黃河瀉作縱橫才。","巍峨宛似神仙客，一段風雷扶氣魄。","低頭語了却擡頭，指點胸前稱李白。","夢中一面何殷勤，高吟大語喧青雲。","自言天府偶閑暇，與我握手論高文。","一論耳目清，再論心骨驚，豁如混沌初鑿破，天地海岳何分明。","利若劍戟堅，健如虬龍爭，神機聖法說略盡，造化與我新精靈。","不問塵埃人，不語塵埃事，罇前酒半（一作「半日」）空，歸雲掃筵起。","自言天上作先生，許向人間爲弟子。","夢破青霄春，煙霞無去塵。","若誇郭璞五色筆，江淹却是尋常人（《全唐詩》卷六○七收「華山」二句及末四句，卷八六八收「上天」二句，均誤繫於張孜名下。","）（《鑑誡錄》九《夢太白》）。"]', '["天使翰林生我前，相去歿（一作「後」）来二百年。","英神傑（一作「絕」）氣归玄天，日月星辰空蹙然。","我識翰林文，不識翰林面。","上天知我憶其人，使向人间梦中见。","瑞光閃爍天关（一作「门」）开，五云著地长裾来，华山秀作英雄骨，黄河瀉作縱橫才。","巍峨宛似神仙客，一段风雷扶氣魄。","低头語了却擡头，指点胸前稱李白。","梦中一面何殷勤，高吟大語喧青云。","自言天府偶闲暇，與我握手論高文。","一論耳目清，再論心骨驚，豁如混沌初鑿破，天地海岳何分明。","利若劍戟堅，健如虬龙爭，神機聖法说略尽，造化與我新精靈。","不问塵埃人，不語塵埃事，罇前酒半（一作「半日」）空，归云掃筵起。","自言天上作先生，許向人间爲弟子。","梦破青霄春，煙霞無去塵。","若誇郭璞五色笔，江淹却是尋常人（《全唐诗》卷六○七收「华山」二句及末四句，卷八六八收「上天」二句，均誤繫於張孜名下。","）（《鑑誡錄》九《梦太白》）。"]', '诗', 'shi', '', NULL, '代張孜幻夢李白歌 李山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c665fb-30c0-4d70-9864-7528ec46fc70', '', '', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c589d3b-57f4-457d-9291-c704832c2989', '緱山', '緱山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["緱山崗翠孕仙靈，古柏新松滿洞馨。","借問吹笙王子晉，定從何處上□冥。","（《四部業刊三編》影宋鈔本《胡曾詠史詩》三）。"]', '["緱山崗翠孕仙靈，古柏新松满洞馨。","借问吹笙王子晉，定從何处上□冥。","（《四部業刊三編》影宋鈔本《胡曾詠史诗》三）。"]', '诗', 'shi', '', NULL, '緱山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08453a3-3b32-469d-809c-f34628e8beee', '懷桐江舊居', '懷桐江旧居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["長向新郊話故園，四時清峭似山源。","春潮撼動鶯花郭，秋雨閒藏砧杵邨。","市井多通諸國貨，鄉音自是一方言。","此中別有無歸計，唯把歸心付酒尊。"]', '["长向新郊話故园，四时清峭似山源。","春潮撼动鶯花郭，秋雨閒藏砧杵邨。","市井多通諸国貨，乡音自是一方言。","此中別有無归計，唯把归心付酒尊。"]', '诗', 'shi', '', NULL, '懷桐江舊居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4b2aba-faee-4f83-9d88-2f1a4f79deab', '贈桐溪主人', '贈桐溪主人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["嶺猿沙鶴似同遊，竹汊荷灣可漾舟。","更入深溪見溪主，蒼苔石上臥垂鈎。","（《嚴陵集》二）。"]', '["嶺猿沙鹤似同游，竹汊荷灣可漾舟。","更入深溪见溪主，蒼苔石上臥垂鈎。","（《嚴陵集》二）。"]', '诗', 'shi', '', NULL, '贈桐溪主人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cd08d76-e707-462f-9272-a9adea43c075', '題惠山寺詩（幷序） 讀惠山若冰師詩集因題古院（一作「故園」）五首（前三首《全唐詩》已收） 一', '題惠山寺诗（幷序） 读惠山若冰師诗集因題古院（一作「故园」）五首（前三首《全唐诗》已收） 一', 'c1adf915-9df6-48e1-bea7-1fee8fc4c499', '唐', '["陰陰垂露跡，苔壁幾年書。","種樹青松老，傳衣白髮居。","字工窮八體，詩律繼三閭。","豈是多年學，真空任性理餘。"]', '["陰陰垂露跡，苔壁幾年书。","種樹青松老，傳衣白髮居。","字工窮八體，诗律繼三閭。","豈是多年学，真空任性理餘。"]', '诗', 'shi', '', NULL, '題惠山寺詩（幷序） 讀惠山若冰師詩集因題古院（一作「故園」）五首（前三首《全唐詩》已收） 一 李隲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5723a8a-9493-4d97-9cdf-e61f91b43c47', '題惠山寺詩（幷序） 讀惠山若冰師詩集因題古院（一作「故園」）五首（前三首《全唐詩》已收） 二', '題惠山寺诗（幷序） 读惠山若冰師诗集因題古院（一作「故园」）五首（前三首《全唐诗》已收） 二', 'c1adf915-9df6-48e1-bea7-1fee8fc4c499', '唐', '["常聞鑿洞碑，此立爲冰師。","意刻山泉解，功深造化疑。","碧雲終一謝，飛錫久無期。","惆悵人間世，空傳樂府詞。","（元《無錫縣志》卷四上《辭章詠歌》、又明《弘治無錫縣志》二八《詞章》）。"]', '["常闻鑿洞碑，此立爲冰師。","意刻山泉解，功深造化疑。","碧云終一謝，飞錫久無期。","惆悵人间世，空傳乐府词。","（元《無錫縣志》卷四上《辞章詠歌》、又明《弘治無錫縣志》二八《词章》）。"]', '诗', 'shi', '', NULL, '題惠山寺詩（幷序） 讀惠山若冰師詩集因題古院（一作「故園」）五首（前三首《全唐詩》已收） 二 李隲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb9c3f0-75eb-4b28-8913-bdef5f8f85ed', '晨過昌師院（〖1〗《全唐詩》二七一作竇羣詩。《縣志》第八句「滿」作「漏」○同前〗〖《竇氏聯珠集》不收此詩，作竇詩疑誤。）', '晨過昌師院（〖1〗《全唐诗》二七一作竇羣诗。《縣志》第八句「满」作「漏」○同前〗〖《竇氏聯珠集》不收此诗，作竇诗疑誤。）', 'c1adf915-9df6-48e1-bea7-1fee8fc4c499', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '晨過昌師院（〖1〗《全唐詩》二七一作竇羣詩。《縣志》第八句「滿」作「漏」○同前〗〖《竇氏聯珠集》不收此詩，作竇詩疑誤。） 李隲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c75291e3-b678-4af0-b4a3-e08e728b7f3a', '九華山協濟祠', '九华山協濟祠', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["靈廟門依山半開，松庭瀟洒絕塵埃。","時聞樵者經過說，數有神仙變化來。","龍起陰雲生畫壁，鳥歸寒粟落蒼苔。","自從鼓吹喧闐日，千里封疆不復災。","（《嘉靖池州府志》五。","又《圖書集成·職方典》八一○《池州府部》）。"]', '["靈廟门依山半开，松庭瀟洒絕塵埃。","时闻樵者經過说，數有神仙变化来。","龙起陰云生畫壁，鸟归寒粟落蒼苔。","自從鼓吹喧闐日，千里封疆不复災。","（《嘉靖池州府志》五。","又《圖书集成·職方典》八一○《池州府部》）。"]', '诗', 'shi', '', NULL, '九華山協濟祠 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('889b143f-eca5-4deb-a353-10eb40eceaa3', '化城寺', '化城寺', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["慶雲生處梵王宮，躡磴攀蘿一徑通。","金殿忽開青嶂裏，天人疑在白雲中。","秋霄爽朗空潭月，暑氣蕭寥古柏風。","況是慈悲清淨地，香煙像設固無窮。","（《九華山志》八）。"]', '["慶云生处梵王宮，躡磴攀蘿一徑通。","金殿忽开青嶂裏，天人疑在白云中。","秋霄爽朗空潭月，暑氣蕭寥古柏风。","況是慈悲清淨地，香煙像設固無窮。","（《九华山志》八）。"]', '诗', 'shi', '', NULL, '化城寺 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57585f9b-c061-4790-aae6-54d52f6aa7bf', '謝友人惠箋紙幷筆', '謝友人惠箋紙幷笔', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["范陽從事獨相憐，見惠霜毫與彩箋。","三副緊纏秋月兔，五般方翦蜀江煙。","宵徵覺有文通夢，日習慚無子諒篇。","欲着不將兩處用，歸山閑向墨池前。","（蘇易簡《文房四譜》四《紙譜》）。"]', '["范陽從事独相怜，见惠霜毫與彩箋。","三副緊纏秋月兔，五般方翦蜀江煙。","宵徵覺有文通梦，日習慚無子諒篇。","欲着不將兩处用，归山闲向墨池前。","（蘇易簡《文房四譜》四《紙譜》）。"]', '诗', 'shi', '', NULL, '謝友人惠箋紙幷筆 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655e4998-5575-47e5-b386-655ace27fc36', '梨花', '梨花', '13e10ef4-6baa-4696-abb6-da00612a9d91', '唐', '["綠陰寒食晚，猶自滿空園。","兩歇芳菲白，蜂稀寂寞繁。","一枝橫野路，數樹出江村。","悵望頻回首，何人共酒尊。","（《古今圖書集成·草木典·梨部》（見宋陳景沂《全芳備祖前集》卷九《梨花》。","「蜂稀」，《全芳備祖》作「蜂聲」。","）。"]', '["綠陰寒食晚，猶自满空园。","兩歇芳菲白，蜂稀寂寞繁。","一枝橫野路，數樹出江村。","悵望頻回首，何人共酒尊。","（《古今圖书集成·草木典·梨部》（见宋陳景沂《全芳備祖前集》卷九《梨花》。","「蜂稀」，《全芳備祖》作「蜂声」。","）。"]', '诗', 'shi', '', NULL, '梨花 溫憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45dceae6-0b72-438f-b768-5498026e746d', '留贈司空圖（盧相攜還朝，過陜虢，訪圖，深愛重，留詩曰：）', '留贈司空圖（盧相携還朝，過陜虢，訪圖，深愛重，留诗曰：）', '454dc637-1421-4704-a021-dc91cd2a6062', '唐', '["氏族司空貴，官班御史雄。","老夫如且在，未可歎途窮。","（《北夢鎖言》三及《唐才子傳》司空圖下。","《全唐詩》有此詩，與《紀事》同依據《南部新書》甲，多異文，故重錄。","）。"]', '["氏族司空貴，官班御史雄。","老夫如且在，未可歎途窮。","（《北梦鎖言》三及《唐才子傳》司空圖下。","《全唐诗》有此诗，與《紀事》同依據《南部新书》甲，多異文，故重錄。","）。"]', '诗', 'shi', '', NULL, '留贈司空圖（盧相攜還朝，過陜虢，訪圖，深愛重，留詩曰：） 盧攜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da170227-ceaf-455e-9d3f-8a80df88b969', '贈妓行雲等感恩多詞（句）（路侍中具有，風貌之美，爲世所聞。鎮成都日，委執政于孔目吏邊咸，以官妓行雲等十人侍宴。移鎮渚宮日，于合江亭離筵，贈行雲等《口恩多》詞。有「離魂」云云。至今播于倡樓也。）', '贈妓行云等感恩多词（句）（路侍中具有，风貌之美，爲世所闻。鎮成都日，委執政于孔目吏邊咸，以官妓行云等十人侍宴。移鎮渚宮日，于合江亭離筵，贈行云等《口恩多》词。有「離魂」云云。至今播于倡楼也。）', '2abb04e5-66be-47ba-8c98-5cab57005339', '唐', '["離魂何處斷？","烟雨江南岸。","（《唐語林》四《容止》、《北夢瑣言》三）（〖1〗《全唐詩》無路巖詩，茲據《舊唐書》卷一七七補傳如次：路巖，字魯瞻，陽平冠氏人。","幼聰敏過人，方鎮交辟，數年間出入禁署，累遷中書舍人、戶部侍郎。","咸心目三年以本官同平章事，在相位八年。","後出鎮劍南、荆南。","）。"]', '["離魂何处斷？","烟雨江南岸。","（《唐語林》四《容止》、《北梦瑣言》三）（〖1〗《全唐诗》無路巖诗，茲據《旧唐书》卷一七七補傳如次：路巖，字魯瞻，陽平冠氏人。","幼聰敏過人，方鎮交辟，數年间出入禁署，累遷中书舍人、戶部侍郎。","咸心目三年以本官同平章事，在相位八年。","後出鎮劍南、荆南。","）。"]', '诗', 'shi', '', NULL, '贈妓行雲等感恩多詞（句）（路侍中具有，風貌之美，爲世所聞。鎮成都日，委執政于孔目吏邊咸，以官妓行雲等十人侍宴。移鎮渚宮日，于合江亭離筵，贈行雲等《口恩多》詞。有「離魂」云云。至今播于倡樓也。） 路巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0021f887-dbca-4f6a-85bb-afbdd3e25ade', '', '', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dce7fbe-0eab-4701-b1b8-519a311448a3', '西昌新亭（句）', '西昌新亭（句）', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["暖漾魚遺子，晴遊鹿引麛。","（《唐詩紀事》五八《李洞》（出《唐摭言》卷十《海敍不遇》。","）。"]', '["暖漾鱼遺子，晴游鹿引麛。","（《唐诗紀事》五八《李洞》（出《唐摭言》卷十《海敍不遇》。","）。"]', '诗', 'shi', '', NULL, '西昌新亭（句） 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331671b5-0e06-4d4f-938a-fda8474a1684', '永和縣上巳', '永和縣上巳', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["記得蘭亭祓禊辰，今朝兼是永和春。","一觴一詠無詩侶，病倚山窗憶故人。","（桑世昌《蘭亭考》十二（陸心源《宋詩紀事補遺》卷八八收此詩於事蹟無考作者內。","）。"]', '["記得蘭亭祓禊辰，今朝兼是永和春。","一觴一詠無诗侶，病倚山窗憶故人。","（桑世昌《蘭亭考》十二（陸心源《宋诗紀事補遺》卷八八收此诗於事蹟無考作者內。","）。"]', '诗', 'shi', '', NULL, '永和縣上巳 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17142a54-9792-4c05-8a4b-1ac577750288', '冬日書黎少府山齋', '冬日书黎少府山斋', '8be7f890-fbea-42b2-b09f-f25e8234894d', '唐', '["愛此林亭絕，重遊亦似新。","山秋同鶴過，水落見鳥頻。","映沼荷全綠，侵簷柳尚春。","惜哉無別墅，共作白雲人。"]', '["愛此林亭絕，重游亦似新。","山秋同鹤過，水落见鸟頻。","映沼荷全綠，侵簷柳尚春。","惜哉無別墅，共作白云人。"]', '诗', 'shi', '', NULL, '冬日書黎少府山齋 唐廩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca33b9fb-730f-4f2f-aaf2-0bdade8cfd21', '雲蓋山泉', '云蓋山泉', '8be7f890-fbea-42b2-b09f-f25e8234894d', '唐', '["危嶠高高幾十層，梵王宮裏一泉澄。","引來石竇明如玉，瀉落山厨冷似冰。","淨影不關秋賦客，清音時警夜禪僧。","從茲渡口潺湲去，勢入滄溟豈可仍。","。"]', '["危嶠高高幾十層，梵王宮裏一泉澄。","引来石竇明如玉，瀉落山厨冷似冰。","淨影不关秋賦客，清音时警夜禪僧。","從茲渡口潺湲去，勢入滄溟豈可仍。","。"]', '诗', 'shi', '', NULL, '雲蓋山泉 唐廩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('229da854-d5b2-4347-8a5b-1c64ca03438d', '題蔡處士居', '題蔡处士居', '8be7f890-fbea-42b2-b09f-f25e8234894d', '唐', '["一畝周旋幾十家，舂輪相次好生涯。","鷓鴣近晚啼深竹，鸂𪆟新晴立淺沙。","沃衍共知多黍稷，寬平仍覺富桑麻。","當年何事拋耕釣，木笏藍衫兩鬢華。","（以上《純常子枝語》四十引《萍鄉縣志》（均見同治《萍鄉縣志》卷六。","）。"]', '["一畝周旋幾十家，舂輪相次好生涯。","鷓鴣近晚啼深竹，鸂𪆟新晴立淺沙。","沃衍共知多黍稷，寬平仍覺富桑麻。","當年何事拋耕釣，木笏藍衫兩鬢华。","（以上《純常子枝語》四十引《萍乡縣志》（均见同治《萍乡縣志》卷六。","）。"]', '诗', 'shi', '', NULL, '題蔡處士居 唐廩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f65bab-fdb8-4f28-b8fc-edda2cfb17d5', '別家（句）', '別家（句）', 'd288504d-f971-4d34-b815-5877ba6dfb34', '唐', '["兄弟惜分離，揀日皆言惡。","（《唐才子傳》九）。"]', '["兄弟惜分離，揀日皆言惡。","（《唐才子傳》九）。"]', '诗', 'shi', '', NULL, '別家（句） 唐備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('547d241f-b244-4fad-89b6-8cc90a506ba5', '送友人南中訪舊知', '送友人南中訪旧知', '3034fc80-5463-46d3-96f1-32d02e5ba228', '唐', '["送友人南中訪舊知（《全唐詩》五四三作喻鳧詩。","第五句「急」《文苑英華》作「接」○《文苑英華》二八二《送行》（席刻本《喻鳧詩集》不收此詩。","《全唐詩》收作喻鳧詩恐誤。","）。"]', '["送友人南中訪旧知（《全唐诗》五四三作喻鳧诗。","第五句「急」《文苑英华》作「接」○《文苑英华》二八二《送行》（席刻本《喻鳧诗集》不收此诗。","《全唐诗》收作喻鳧诗恐誤。","）。"]', '诗', 'shi', '', NULL, '送友人南中訪舊知 喻坦之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95e73ca7-e898-4cf3-aeda-96618ff14f8d', '', '', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c27d2c-9355-43b5-8ff5-ffd0a95f55cf', '上岳守', '上岳守', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["入郭寬萬里，岳陽堪畫圖。","及窺賢太守，不見洞庭湖。","（《輿地紀勝》六九《岳州》）。"]', '["入郭寬万里，岳陽堪畫圖。","及窺賢太守，不见洞庭湖。","（《輿地紀勝》六九《岳州》）。"]', '诗', 'shi', '', NULL, '上岳守 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e0049c-d5d9-4c33-aefc-8d773afd4381', '句', '句', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["自己情雖切，他人未肯忙。","（《老學庵筆記》四）。"]', '["自己情雖切，他人未肯忙。","（《老学庵笔記》四）。"]', '诗', 'shi', '', NULL, '句 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff5ef30-61e7-4ea9-9f90-287e80ba2af7', '題建造寺', '題建造寺', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["疊嶂橫空向郡西，迥然高峭衆山低。","樹梢缺處見城郭，日影落時聞鼓鼙。","（《輿地紀勝》卷一三○《福建路·泉州》）。"]', '["叠嶂橫空向郡西，迥然高峭衆山低。","樹梢缺处见城郭，日影落时闻鼓鼙。","（《輿地紀勝》卷一三○《福建路·泉州》）。"]', '诗', 'shi', '', NULL, '題建造寺 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262f6174-75b5-468b-9af9-3cb67840aa17', '宿江館（句）', '宿江館（句）', 'd482da05-63a3-40a5-b2f7-918501a6ae86', '唐', '["吟登晚驛亭，醉罷紅燈落。","（《詩學指南》四（《吟窗雜錄》卷十四正字王玄《詩中旨格》，「醉罷」作「醮罷」，幷云「此比君子欲仕于明時也」。","）。"]', '["吟登晚驛亭，醉罷紅灯落。","（《诗学指南》四（《吟窗杂錄》卷十四正字王玄《诗中旨格》，「醉罷」作「醮罷」，幷云「此比君子欲仕于明时也」。","）。"]', '诗', 'shi', '', NULL, '宿江館（句） 張爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60bd412-a6d1-4788-9da5-cffaf1d81979', '', '', '1ca21e03-ecc0-4402-b10a-3157425920bb', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 韓氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3350db77-87e1-4b43-8be8-39cfef9c131f', '于祐題紅葉二句', '于祐題紅葉二句', '1ca21e03-ecc0-4402-b10a-3157425920bb', '唐', '[]', '[]', '诗', 'shi', '', NULL, '于祐題紅葉二句 韓氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23667d13-06d2-4331-9e92-8e534f984f07', '得于祐題詩後又作詩', '得于祐題诗後又作诗', '1ca21e03-ecc0-4402-b10a-3157425920bb', '唐', '["獨步天溝岸，臨流得葉時。","此情誰會得？腸斷一聯詩。"]', '["独步天溝岸，臨流得葉时。","此情誰會得？腸斷一聯诗。"]', '诗', 'shi', '', NULL, '得于祐題詩後又作詩 韓氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fdb6be0-0a71-447d-8c3c-0ecb271acf77', '婚宴席上索筆爲詩', '婚宴席上索笔爲诗', '1ca21e03-ecc0-4402-b10a-3157425920bb', '唐', '["一聯佳句題流水，十載幽思滿素懷。","今日却成鸞鳳友，方知紅葉是良媒。","（《青瑣高議前集》（均見《青瑣高議前集》卷五引張實《流紅記》。","按紅葉題詩故事，唐詩已有數傳，《雲溪友議》卷下記顧況與天寶宮人、盧渥與宣宗宮人事，《本事詩》亦載顧況事，《北夢瑣言》卷九作李茵與雲芳子事，《全唐詩》卷七九九又有賈全虛與鳳兒事。","《流紅記》即張實據以上故事敷衍而成的小說。","《苕溪漁隱業話後集》卷十六云：「《青瑣》乃互竄二事，合爲一傳，曰《流紅記》，仍託他人姓名。","嗚呼，孰謂小說可盡信乎！」龐元英《談藪》亦謂此篇「最爲鄙妄」。","宋人對小說的鄙夷雖不足取，但此篇爲宋人依說，當可據以論定。","）。"]', '["一聯佳句題流水，十載幽思满素懷。","今日却成鸾鳳友，方知紅葉是良媒。","（《青瑣高議前集》（均见《青瑣高議前集》卷五引張實《流紅記》。","按紅葉題诗故事，唐诗已有數傳，《云溪友議》卷下記顧況與天寶宮人、盧渥與宣宗宮人事，《本事诗》亦載顧況事，《北梦瑣言》卷九作李茵與云芳子事，《全唐诗》卷七九九又有賈全虛與鳳兒事。","《流紅記》即張實據以上故事敷衍而成的小说。","《苕溪漁隐業話後集》卷十六云：「《青瑣》乃互竄二事，合爲一傳，曰《流紅記》，仍託他人姓名。","嗚呼，孰謂小说可尽信乎！」龐元英《談藪》亦謂此篇「最爲鄙妄」。","宋人对小说的鄙夷雖不足取，但此篇爲宋人依说，當可據以論定。","）。"]', '诗', 'shi', '', NULL, '婚宴席上索筆爲詩 韓氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb8ff95-ee73-4a41-b816-21b45b34e398', '觀夢龜草書', '观梦龟草书', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["欲盡金鍾數斗餘，從容攘臂立踟躕。","先教侍者濃磨墨，不揖傍人欻便書。","畫狀倒松橫洞壑，點麄飛石落空虛。","興來抹亦成字，祇恐張顛顛不如。","（《六藝之一錄》二九四引陳思《書苑菁華》）。"]', '["欲尽金鍾數斗餘，從容攘臂立踟躕。","先教侍者濃磨墨，不揖傍人欻便书。","畫狀倒松橫洞壑，点麄飞石落空虛。","兴来抹亦成字，祇恐張顛顛不如。","（《六藝之一錄》二九四引陳思《书苑菁华》）。"]', '诗', 'shi', '', NULL, '觀夢龜草書 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be794d8-72f0-42da-bf24-9b38783ab63c', '岳陽悼賈島（《全唐詩》七六八作安錡《題賈島墓》，末一字「忡」，《鑑誡錄》作「㤏」）（崔錡評事倅岳陽日，爲詩悼賈島。岳是，普州地名。今因創墓在岳陽山上，山下有岳陽池。○《鑑誡錄》八《賈忤旨》）', '岳陽悼賈島（《全唐诗》七六八作安錡《題賈島墓》，末一字「忡」，《鑑誡錄》作「㤏」）（崔錡評事倅岳陽日，爲诗悼賈島。岳是，普州地名。今因創墓在岳陽山上，山下有岳陽池。○《鑑誡錄》八《賈忤旨》）', 'cc8012b4-6aad-4252-a8ec-9c9b9ff056e5', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '岳陽悼賈島（《全唐詩》七六八作安錡《題賈島墓》，末一字「忡」，《鑑誡錄》作「㤏」）（崔錡評事倅岳陽日，爲詩悼賈島。岳是，普州地名。今因創墓在岳陽山上，山下有岳陽池。○《鑑誡錄》八《賈忤旨》） 崔錡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7decc698-68b9-4765-aa4b-aeaec2008508', '水（《文苑英華》又有《柳》、《松》二首，《全唐詩》均作韓溉，應別出互見。）', '水（《文苑英华》又有《柳》、《松》二首，《全唐诗》均作韓溉，應別出互见。）', '546abb6a-8170-49d3-8685-de3a921457db', '唐', '["方圓不定性空求（柔），東注滄溟早晚休。","高截碧塘長耿耿，遠飛青嶂更悠悠。","瀟湘月浸千年色，夢澤煙含萬古愁。","別有嶺頭鳴咽處，爲君分（更）作斷腸流。","（《文苑英華》一六三《地部》。","又《詩話總龜》二一《詠物門》引《續末流事詩》）（〖1〗《全唐詩》卷六七一唐彥謙有《逢韓喜》詩，知韓喜爲唐末人。","原列入「無世次」作者，今移此。","）。"]', '["方圓不定性空求（柔），东注滄溟早晚休。","高截碧塘长耿耿，远飞青嶂更悠悠。","瀟湘月浸千年色，梦澤煙含万古愁。","別有嶺头鳴咽处，爲君分（更）作斷腸流。","（《文苑英华》一六三《地部》。","又《诗話總龟》二一《詠物门》引《續末流事诗》）（〖1〗《全唐诗》卷六七一唐彥謙有《逢韓喜》诗，知韓喜爲唐末人。","原列入「無世次」作者，今移此。","）。"]', '诗', 'shi', '', NULL, '水（《文苑英華》又有《柳》、《松》二首，《全唐詩》均作韓溉，應別出互見。） 韓喜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c44187-cfe9-45f2-bf69-8ee65f2f33fc', '見人衣鮮華作詩', '见人衣鲜华作诗', 'ef410547-a3e6-41da-bc8f-7f2bf80e780a', '唐', '["昂藏騎馬出朱門，服色鮮華不可論。","盡是殺人方始得，一絲絲上有冤魂。"]', '["昂藏騎马出朱门，服色鲜华不可論。","尽是殺人方始得，一絲絲上有冤魂。"]', '诗', 'shi', '', NULL, '見人衣鮮華作詩 歸處訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a05fd0-cc0a-433c-b5d6-e00f79ebb2f4', '詠虺漢（黃巢犯京後，守亮、守信等悉爲楊軍容復恭義兒，勢奪諸侯，亦一時之威也。歸有不平之色詠虺漢以刺之曰：）', '詠虺漢（黄巢犯京後，守亮、守信等悉爲楊軍容复恭義兒，勢奪諸侯，亦一时之威也。归有不平之色詠虺漢以刺之曰：）', 'ef410547-a3e6-41da-bc8f-7f2bf80e780a', '唐', '["草頭灰面惡形儀，盡是軍容表裏兒。","昔日水牛攀角上，而今細馬劈腰騎。","錢多內藏猶嫌少，位等三公尚厭卑。","更有一般堪笑處，鍍金牙齒咬銀匙。"]', '["草头灰面惡形儀，尽是軍容表裏兒。","昔日水牛攀角上，而今細马劈腰騎。","錢多內藏猶嫌少，位等三公尚厭卑。","更有一般堪笑处，鍍金牙齒咬銀匙。"]', '诗', 'shi', '', NULL, '詠虺漢（黃巢犯京後，守亮、守信等悉爲楊軍容復恭義兒，勢奪諸侯，亦一時之威也。歸有不平之色詠虺漢以刺之曰：） 歸處訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c96f9a8-c8a5-4f78-b27e-41b01c57735f', '詠奸漢', '詠奸漢', 'ef410547-a3e6-41da-bc8f-7f2bf80e780a', '唐', '["輕脣利舌傍侯門，送諂承顏日月新。","愛與大官添弟子，能將小藥獻夫人。","秤頭不放分毫過，對面常如割骨貧。","更有一般奸太曬，聚錢唯趁買金銀。"]', '["轻脣利舌傍侯门，送諂承顏日月新。","愛與大官添弟子，能將小藥獻夫人。","秤头不放分毫過，对面常如割骨貧。","更有一般奸太曬，聚錢唯趁買金銀。"]', '诗', 'shi', '', NULL, '詠奸漢 歸處訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58238acf-eb20-4745-93e5-3b5980b40b8b', '代村婦詠邊將', '代村婦詠邊將', 'ef410547-a3e6-41da-bc8f-7f2bf80e780a', '唐', '["紫袍金帶不須誇，動便經年鎮海涯。","爭似我家田舍壻，朝驅牛去暮還家。"]', '["紫袍金带不須誇，动便經年鎮海涯。","爭似我家田舍壻，朝驱牛去暮還家。"]', '诗', 'shi', '', NULL, '代村婦詠邊將 歸處訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2519b296-a88e-4ac8-ba24-24d45692c977', '詠石校書（欽若）（石校書，本東川人。文章四六，與王超齊名。天復初應舉，值大駕東遷，蜀路不心目，干戈繼起，遂客寄天水，荏苒一紀有餘。後知父亡，方乃舉慟，廣於寺院追薦懺罪而已。歸與石遽因小隟，荼毒詠之。石氏聲名，因茲減價。詩曰：）', '詠石校书（欽若）（石校书，本东川人。文章四六，與王超齊名。天复初應舉，值大駕东遷，蜀路不心目，干戈繼起，遂客寄天水，荏苒一紀有餘。後知父亡，方乃舉慟，廣於寺院追薦懺罪而已。归與石遽因小隟，荼毒詠之。石氏声名，因茲減價。诗曰：）', 'ef410547-a3e6-41da-bc8f-7f2bf80e780a', '唐', '["十二年來匿父喪，三年之罪遣誰當。","如今追薦應無益，已被牛頭煮幾場。","（以上《鑑誡錄》十《歸生刺》）。"]', '["十二年来匿父喪，三年之罪遣誰當。","如今追薦應無益，已被牛头煮幾場。","（以上《鑑誡錄》十《归生刺》）。"]', '诗', 'shi', '', NULL, '詠石校書（欽若）（石校書，本東川人。文章四六，與王超齊名。天復初應舉，值大駕東遷，蜀路不心目，干戈繼起，遂客寄天水，荏苒一紀有餘。後知父亡，方乃舉慟，廣於寺院追薦懺罪而已。歸與石遽因小隟，荼毒詠之。石氏聲名，因茲減價。詩曰：） 歸處訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf99ca3-cfab-4da5-86ee-b126bf7b270d', '游四頂山（《方輿勝覽》：四頂用在合肥縣東南。《寰宇記》作四鼎，《郡國志》云：魏伯陽煉丹之所。）', '游四頂山（《方輿勝覽》：四頂用在合肥縣东南。《寰宇記》作四鼎，《郡国志》云：魏伯陽煉丹之所。）', '633ca15b-735c-4976-9aac-86c647b26ac1', '唐', '["翠巒齊聳壓平湖，晚綠朝紅畫不如。","寄詩紀商山閑四皓，好來各占一峰居。","（《光緒重修廬州府志》六《山川志》上〖2〗）（〖1〗《新唐書》卷七二下《宰相世系表》二下河東張氏有彥修，爲憲宗朝宰相已經弘靖之孫，河南少尹張嗣慶之子。","據張忱石考證，彥修當爲文宗至僖宗時人。","〖2〗見《輿地紀勝》卷四五《廬州》。","）。"]', '["翠巒齊聳壓平湖，晚綠朝紅畫不如。","寄诗紀商山闲四皓，好来各占一峰居。","（《光緒重修廬州府志》六《山川志》上〖2〗）（〖1〗《新唐书》卷七二下《宰相世系表》二下河东張氏有彥修，爲憲宗朝宰相已經弘靖之孫，河南少尹張嗣慶之子。","據張忱石考證，彥修當爲文宗至僖宗时人。","〖2〗见《輿地紀勝》卷四五《廬州》。","）。"]', '诗', 'shi', '', NULL, '游四頂山（《方輿勝覽》：四頂用在合肥縣東南。《寰宇記》作四鼎，《郡國志》云：魏伯陽煉丹之所。） 張彥修〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ba3730-7b24-4f01-a713-5a7b8d2b3fa5', '羅浮', '羅浮', '9862db95-420a-4c9a-a474-ddc8d76fdcc4', '唐', '["危閣閒登思渺漫，九天如在掌中看。","遊人莫著單衣去，六月飛雲帶雪寒。"]', '["危閣閒登思渺漫，九天如在掌中看。","游人莫著單衣去，六月飞云带雪寒。"]', '诗', 'shi', '', NULL, '羅浮 小白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c65bbae-8811-4f1f-af61-165a16b248a4', '中閣', '中閣', '9862db95-420a-4c9a-a474-ddc8d76fdcc4', '唐', '["棱層高閣倚巖扃，俯瞰塵仰摘星。","晝夜泉聲混天樂，遊人好向靜中聽。","（以上《羅浮志》十《詩》）。"]', '["棱層高閣倚巖扃，俯瞰塵仰摘星。","晝夜泉声混天乐，游人好向静中听。","（以上《羅浮志》十《诗》）。"]', '诗', 'shi', '', NULL, '中閣 小白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c698d32b-5ca3-47d0-92c5-db1c530b0e0a', '宿金庭觀（在嵊縣東南七十二里）', '宿金庭观（在嵊縣东南七十二里）', '9862db95-420a-4c9a-a474-ddc8d76fdcc4', '唐', '["羽客相留宿上方，金庭風月冷如霜。","直饒人世三千歲，未抵仙家一夜長。","（《嘉慶浙江通志》二三一《寺觀》〖2〗）（〖1〗《增廣聖宋高僧詩選後集》卷上收秀登《送小白上人歸華頂》、《送貫微歸天台》等詩，齊己《白蓮集》中有寄贈貫微詩多首，因知小白亦應爲齊己同時人。","〖參《全唐詩續拾》卷四一〗原列入時代未詳僧，今移此。","〖2〗見宋高似孫《剡錄》卷八，參前張說條。","）。"]', '["羽客相留宿上方，金庭风月冷如霜。","直饒人世三千歲，未抵仙家一夜长。","（《嘉慶浙江通志》二三一《寺观》〖2〗）（〖1〗《增廣聖宋高僧诗選後集》卷上收秀登《送小白上人归华頂》、《送貫微归天台》等诗，齊己《白蓮集》中有寄贈貫微诗多首，因知小白亦應爲齊己同时人。","〖參《全唐诗續拾》卷四一〗原列入时代未詳僧，今移此。","〖2〗见宋高似孫《剡錄》卷八，參前張说條。","）。"]', '诗', 'shi', '', NULL, '宿金庭觀（在嵊縣東南七十二里） 小白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2a7e0d-31cf-4407-8678-2bceaf7e1930', '贈樊川長老', '贈樊川长老', '56d489cf-8274-414a-bf60-0597102247b9', '唐', '["贈樊川長老（《全唐詩》八二五作可止詩○《瀛奎律髓》四七《釋梵類》〖2〗）（原列無世次作者。","今檢齊己《白蓮集》卷三有《覽清尚卷》，知爲唐末人，故移此。","〖2〗另《唐詩紀事》卷七七作可止詩，《唐僧弘秀集》卷十作清尚詩。","）。"]', '["贈樊川长老（《全唐诗》八二五作可止诗○《瀛奎律髓》四七《釋梵類》〖2〗）（原列無世次作者。","今檢齊己《白蓮集》卷三有《覽清尚卷》，知爲唐末人，故移此。","〖2〗另《唐诗紀事》卷七七作可止诗，《唐僧弘秀集》卷十作清尚诗。","）。"]', '诗', 'shi', '', NULL, '贈樊川長老 清尚〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c49aec-7a40-4cd8-a4d8-fb90f1abc406', '詠石硯', '詠石硯', '794c1338-f47f-40a6-b0a5-73c9be374dd9', '唐', '["遠來柯嶺外，近到玉堂間。","乍琢文猶澀，新磨墨尚慳。","不能濡大筆，何要別秋山。","（《文房四譜》三《硯譜》）。"]', '["远来柯嶺外，近到玉堂间。","乍琢文猶澀，新磨墨尚慳。","不能濡大笔，何要別秋山。","（《文房四譜》三《硯譜》）。"]', '诗', 'shi', '', NULL, '詠石硯 李琪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f525451-3a15-4d7c-b4d9-75df41f09bdb', '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」）', '梁宗廟乐舞辞（《旧五代史·乐志》曰：「梁开平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《来儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌乐章各一首。」《五代會要》七《廟乐》曰：「太常少卿楊煥撰。」）', '06e40a1d-fb00-4c65-817c-75fd8e14a2cb', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 楊煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d90904-f630-4898-8b88-7f0545d0b1a1', '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 大合舞（獻肅祖）', '梁宗廟乐舞辞（《旧五代史·乐志》曰：「梁开平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《来儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌乐章各一首。」《五代會要》七《廟乐》曰：「太常少卿楊煥撰。」） 大合舞（獻肅祖）', '06e40a1d-fb00-4c65-817c-75fd8e14a2cb', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 大合舞（獻肅祖） 楊煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1b6549-2ecd-4f35-85fe-fd4ef8fb088b', '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 象功舞（獻敬〖恭〗祖）', '梁宗廟乐舞辞（《旧五代史·乐志》曰：「梁开平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《来儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌乐章各一首。」《五代會要》七《廟乐》曰：「太常少卿楊煥撰。」） 象功舞（獻敬〖恭〗祖）', '06e40a1d-fb00-4c65-817c-75fd8e14a2cb', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 象功舞（獻敬〖恭〗祖） 楊煥 shi');
