INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea441db-70dc-45ed-8cd5-2416b9089393', '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 昭德舞（獻烈祖○《樂府詩集》十二。詩見《全唐詩》十六《郊廟歌辭》）', '梁宗廟乐舞辞（《旧五代史·乐志》曰：「梁开平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《来儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌乐章各一首。」《五代會要》七《廟乐》曰：「太常少卿楊煥撰。」） 昭德舞（獻烈祖○《乐府诗集》十二。诗见《全唐诗》十六《郊廟歌辞》）', '06e40a1d-fb00-4c65-817c-75fd8e14a2cb', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '梁宗廟樂舞辭（《舊五代史·樂志》曰：「梁開平初，太祖受禪，始建宗廟，凡四室，每室有登歌、酌獻之舞：肅祖宣元皇帝室曰《大合之舞》，敬祖光獻皇帝室曰《象功之舞》，憲祖昭武皇帝室曰《來儀之舞》，烈祖文穆皇帝室曰《昭德之舞》，登歌樂章各一首。」《五代會要》七《廟樂》曰：「太常少卿楊煥撰。」） 昭德舞（獻烈祖○《樂府詩集》十二。詩見《全唐詩》十六《郊廟歌辭》） 楊煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183250ef-f7b0-476a-953d-4f8ccee11a88', '致李深之（鄭舉舉，巧談諧，常有名賢醵宴。乾符中，狀元孫偓頗惑之，與同年數人，多在其舍。一日，同年宴，而舉舉有疾不來，遂令同年李深之邀爲酒糾。坐久，狀元乃吟一篇曰：）', '致李深之（鄭舉舉，巧談諧，常有名賢醵宴。乾符中，狀元孫偓頗惑之，與同年數人，多在其舍。一日，同年宴，而舉舉有疾不来，遂令同年李深之邀爲酒糾。坐久，狀元乃吟一篇曰：）', '5252d903-5837-4ded-843f-2b12f5c7ea3b', '唐', '["南行忽見李深之，手舞如蜚令不疑。","任爾風流兼蘊藉，天生不似鄭都知。","（曲內妓之頭角者都知。","《北里志》（陶敏云此詩《全唐詩》卷七一五收作劉崇魯《席上吟》。","並謂《北里志》云：「今左史劉郊文崇及第年亦惑於舉舉，同年宴而舉舉有疾不來，其年酒糾多非舉舉，遂令同年李深之邀爲酒糾，坐久，覺狀元微哂，良久乃詠一篇曰……」文中之新的郊文崇即劉崇魯，字郊文，文中脫一「魯」字。","文云「覺狀元微哂，良久乃詠一篇」，則「覺」與「詠」者均劉崇魯。","謂詩乃狀元孫偓作，似于理未安。","陶說可參。","）。"]', '["南行忽见李深之，手舞如蜚令不疑。","任爾风流兼蘊藉，天生不似鄭都知。","（曲內妓之头角者都知。","《北里志》（陶敏云此诗《全唐诗》卷七一五收作劉崇魯《席上吟》。","並謂《北里志》云：「今左史劉郊文崇及第年亦惑於舉舉，同年宴而舉舉有疾不来，其年酒糾多非舉舉，遂令同年李深之邀爲酒糾，坐久，覺狀元微哂，良久乃詠一篇曰……」文中之新的郊文崇即劉崇魯，字郊文，文中脫一「魯」字。","文云「覺狀元微哂，良久乃詠一篇」，則「覺」與「詠」者均劉崇魯。","謂诗乃狀元孫偓作，似于理未安。","陶说可參。","）。"]', '诗', 'shi', '', NULL, '致李深之（鄭舉舉，巧談諧，常有名賢醵宴。乾符中，狀元孫偓頗惑之，與同年數人，多在其舍。一日，同年宴，而舉舉有疾不來，遂令同年李深之邀爲酒糾。坐久，狀元乃吟一篇曰：） 孫偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07117985-0603-4fbf-a1dc-5d452dc15a82', '答崔素娥（《全唐詩》名媛有崔素娥《別韋洵美詩》，韋詩以小字附後。）', '答崔素娥（《全唐诗》名媛有崔素娥《別韋洵美诗》，韋诗以小字附後。）', 'd67d8950-ef98-434b-9573-46407131c0bb', '唐', '["別恨商羣離羣自古聞，此心難捨意難論。","承恩必若頒時服，莫使霑濡有淚痕。","（《全五代詩》八詳引《侍兒小名錄》（韋洵美二詩，皆出自《燈下閑談》卷下《行者雪怨》。","「離羣」，《燈下閑談》作「離情」。","）。"]', '["別恨商羣離羣自古闻，此心难捨意难論。","承恩必若頒时服，莫使霑濡有泪痕。","（《全五代诗》八詳引《侍兒小名錄》（韋洵美二诗，皆出自《灯下闲談》卷下《行者雪怨》。","「離羣」，《灯下闲談》作「離情」。","）。"]', '诗', 'shi', '', NULL, '答崔素娥（《全唐詩》名媛有崔素娥《別韋洵美詩》，韋詩以小字附後。） 韋洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b9ffbf-b4a7-4bfb-9b30-5c2f1c37c421', '假僧榻悶吟', '假僧榻悶吟', 'd67d8950-ef98-434b-9573-46407131c0bb', '唐', '["門壁紛紛蟋蟀聲，背燈欹枕夢難成。","人間有此不平事，何處人能報不平。","（《萬首唐人絕句》四十《鬼詩》）（「紛紛」，《燈下閑談》作「忙忙」。","）。"]', '["门壁紛紛蟋蟀声，背灯欹枕梦难成。","人间有此不平事，何处人能報不平。","（《万首唐人絕句》四十《鬼诗》）（「紛紛」，《灯下闲談》作「忙忙」。","）。"]', '诗', 'shi', '', NULL, '假僧榻悶吟 韋洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('243b14e4-6e0d-4478-8ec1-889e6c1e439b', '答杜荀鶴（句）（杜荀鶴贈詩云：「祇恐爲僧心不了，爲僧心了總輪僧。」瀾答詩云：）', '答杜荀鹤（句）（杜荀鹤贈诗云：「祇恐爲僧心不了，爲僧心了總輪僧。」瀾答诗云：）', '3aab8aab-19a3-4449-90d0-29d5a77f26c2', '唐', '["如何即是僧心了，了得何心是了僧？","（《輿地紀勝》二十《徽州·仙釋》。","又見弘治《徽州府志》十。","又康熙《志》十八）。"]', '["如何即是僧心了，了得何心是了僧？","（《輿地紀勝》二十《徽州·仙釋》。","又见弘治《徽州府志》十。","又康熙《志》十八）。"]', '诗', 'shi', '', NULL, '答杜荀鶴（句）（杜荀鶴贈詩云：「祇恐爲僧心不了，爲僧心了總輪僧。」瀾答詩云：） 清瀾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fafd067-db3b-4965-8620-2ed9f8b523ad', '上張相（石晉時，張相從恩自南院宣徽使官才檢校司徒權西京留守。到洛陽後未久，少師自東京得假，往洛陽數日，寄上張相云云。張公知世其貧，贈遺甚厚。）', '上張相（石晉时，張相從恩自南院宣徽使官才檢校司徒權西京留守。到洛陽後未久，少師自东京得假，往洛陽數日，寄上張相云云。張公知世其貧，贈遺甚厚。）', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["南院司徒鎮洛京，未經三月政聲成。","四方羣后皆如此，端坐庸夫見太平。","（《全五代詩·補遺》引《洛陽縉紳舊聞記》）（見《洛陽縉紳舊聞記》卷一《少師佯狂》。","）。"]', '["南院司徒鎮洛京，未經三月政声成。","四方羣后皆如此，端坐庸夫见太平。","（《全五代诗·補遺》引《洛陽縉紳旧闻記》）（见《洛陽縉紳旧闻記》卷一《少師佯狂》。","）。"]', '诗', 'shi', '', NULL, '上張相（石晉時，張相從恩自南院宣徽使官才檢校司徒權西京留守。到洛陽後未久，少師自東京得假，往洛陽數日，寄上張相云云。張公知世其貧，贈遺甚厚。） 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6257f8a2-1520-4525-b5c9-52a46d66f403', '詠橘（莊宗小酌，進新橘，命諸伶詠之。唐朝美詩先成云云。帝大笑，賜所御軟金杯。）', '詠橘（莊宗小酌，進新橘，命諸伶詠之。唐朝美诗先成云云。帝大笑，賜所御軟金杯。）', '8ae4a61b-f182-4de3-8289-6bd21d5c5ff0', '唐', '["金香大丞相，兄弟八九人。","剝皮去滓子，若箇是汝身。","（《全五代詩》九引《清異錄》二）。"]', '["金香大丞相，兄弟八九人。","剝皮去滓子，若箇是汝身。","（《全五代诗》九引《清異錄》二）。"]', '诗', 'shi', '', NULL, '詠橘（莊宗小酌，進新橘，命諸伶詠之。唐朝美詩先成云云。帝大笑，賜所御軟金杯。） 唐朝美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de65e344-0b40-4043-bff5-bcddd0e6dede', '洋川', '洋川', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["自陪台斾到洋川，兩載優遊漢水邊。","官閒最好遊僧舍，江近應須買釣船。","更待浹旬無事後，遍題清景作詩仙。","（此處拼合未妥，另詳《全唐詩續拾》卷四二。","）。"]', '["自陪台斾到洋川，兩載優游漢水邊。","官閒最好游僧舍，江近應須買釣船。","更待浹旬無事後，遍題清景作诗仙。","（此处拼合未妥，另詳《全唐诗續拾》卷四二。","）。"]', '诗', 'shi', '', NULL, '洋川 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924e4ea2-53cf-416d-8302-5b9cc5bbb009', '題真符縣（句）', '題真符縣（句）', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["雖有黃金額，其如赤子貧。","（以上《輿地紀勝》一九○《洋州》）。"]', '["雖有黄金額，其如赤子貧。","（以上《輿地紀勝》一九○《洋州》）。"]', '诗', 'shi', '', NULL, '題真符縣（句） 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03850290-0ad6-4343-acd1-b2f9bed1bf79', '', '', '62fd5087-1a7a-47dc-a9dd-194039e9d836', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陶晟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace51e9a-adf6-42fd-a16d-4d39dc238549', '句', '句', '62fd5087-1a7a-47dc-a9dd-194039e9d836', '唐', '["河經蕃地濁，山到漢家青。"]', '["河經蕃地濁，山到漢家青。"]', '诗', 'shi', '', NULL, '句 陶晟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202d15fc-1a1a-471e-99ca-603e9696cf20', '句', '句', '62fd5087-1a7a-47dc-a9dd-194039e9d836', '唐', '["擬拋丹禁去，試著白衣看。","（以上《全五代詩補遺》引《洛陽縉紳舊聞記》）（見《洛陽縉紳舊聞記》卷一《陶副車求薦見忌》，後二句爲「在環衛時詩」。","）。"]', '["擬拋丹禁去，試著白衣看。","（以上《全五代诗補遺》引《洛陽縉紳旧闻記》）（见《洛陽縉紳旧闻記》卷一《陶副车求薦见忌》，後二句爲「在环衛时诗」。","）。"]', '诗', 'shi', '', NULL, '句 陶晟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527e515b-c0de-4781-8ee0-8f466d10f573', '舌', '舌', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["口是禍之門，舌是斬身刀。","閉口深藏舌，安身處處牢。","（《古今圖書集成·人事典》一四《口部》）（見宋胡穉《增廣箋注簡齋詩集》卷四《寄新息家叔》注引。","《群書通要丙集》卷一引前二句。","《喻世明言》卷三十八引此詩，不云作者。","）。"]', '["口是禍之门，舌是斬身刀。","閉口深藏舌，安身处处牢。","（《古今圖书集成·人事典》一四《口部》）（见宋胡穉《增廣箋注簡斋诗集》卷四《寄新息家叔》注引。","《群书通要丙集》卷一引前二句。","《喻世明言》卷三十八引此诗，不云作者。","）。"]', '诗', 'shi', '', NULL, '舌 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1231e1da-fa00-4591-a034-dce138c6c7d9', '透明巖（亦名棲真巖，在大蓬山，前視空曠，俯瞰縣郭。天氣清明，渠、達諸山，隱隱可數。縣令李九齡詩云云。〖李九齡爲宋初乾德間進士，其任縣令，當在登第後。〗）', '透明巖（亦名棲真巖，在大蓬山，前視空曠，俯瞰縣郭。天氣清明，渠、達諸山，隐隐可數。縣令李九齡诗云云。〖李九齡爲宋初乾德间進士，其任縣令，當在登第後。〗）', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["乍脫塵埃夢寐安，透明巖上一開顏。","晚霞收處似聞雁，遠目盡時猶有山。","仙跡不隨巖桂花，禪心長共嶺雲閑。","（《輿地紀勝》一八八《蓬州·景物》）。"]', '["乍脫塵埃梦寐安，透明巖上一开顏。","晚霞收处似闻雁，远目尽时猶有山。","仙跡不隨巖桂花，禪心长共嶺云闲。","（《輿地紀勝》一八八《蓬州·景物》）。"]', '诗', 'shi', '', NULL, '透明巖（亦名棲真巖，在大蓬山，前視空曠，俯瞰縣郭。天氣清明，渠、達諸山，隱隱可數。縣令李九齡詩云云。〖李九齡爲宋初乾德間進士，其任縣令，當在登第後。〗） 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22c54cd-5e59-4df5-953e-7b318f5ded3b', '句（度，工詩，有句云云，人多誦之。王朴爲樞密，止以此一聯薦於申文炳知舉，遂擢爲第三。人嘲曰：「主司只誦一聯詩。」）', '句（度，工诗，有句云云，人多誦之。王朴爲樞密，止以此一聯薦於申文炳知舉，遂擢爲第三。人嘲曰：「主司只誦一聯诗。」）', 'cd1002b9-0f42-48b9-8a10-8fda0c76da1d', '唐', '["醉輕浮世事，老重故鄉人。","（《玉壺清話》七）。"]', '["醉轻浮世事，老重故乡人。","（《玉壺清話》七）。"]', '诗', 'shi', '', NULL, '句（度，工詩，有句云云，人多誦之。王朴爲樞密，止以此一聯薦於申文炳知舉，遂擢爲第三。人嘲曰：「主司只誦一聯詩。」） 李度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6db25ea-ccab-4e82-acc5-899ddf453900', '', '', '2755233c-4e94-4466-a0a6-93fd6d1b0adf', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 田敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8860747-dd75-4cc0-8bdd-0ef6f38cbf2a', '明德舞（後周宗廟樂舞辭。太祖廟堂）', '明德舞（後周宗廟乐舞辞。太祖廟堂）', '2755233c-4e94-4466-a0a6-93fd6d1b0adf', '唐', '["《五代會要》七《廟樂》曰：「太祖聖神齒數肅文武孝皇帝廟室酌獻舞《明德之舞》，登歌樂章一首，太常卿田敏撰。","（參《舊五代史》一四四《樂志》）」惟彼岐陽，德大流光。","載造周室，澤及遐荒。","於鑠聖祖，上帝是皇。","迺聖迺神，知微知章。","新廟弈弈，豐年穰穰。","取彼血膋，以往烝嘗。","黍稷惟聲，籩豆大房。","工祝致告，受福無疆。","（《樂府詩集》十二《郊廟歌辭》）（《全唐詩》卷十六《郊廟歌辭》收入，不署作者。","）。"]', '["《五代會要》七《廟乐》曰：「太祖聖神齒數肅文武孝皇帝廟室酌獻舞《明德之舞》，登歌乐章一首，太常卿田敏撰。","（參《旧五代史》一四四《乐志》）」惟彼岐陽，德大流光。","載造周室，澤及遐荒。","於鑠聖祖，上帝是皇。","迺聖迺神，知微知章。","新廟弈弈，豐年穰穰。","取彼血膋，以往烝嘗。","黍稷惟声，籩豆大房。","工祝致告，受福無疆。","（《乐府诗集》十二《郊廟歌辞》）（《全唐诗》卷十六《郊廟歌辞》收入，不署作者。","）。"]', '诗', 'shi', '', NULL, '明德舞（後周宗廟樂舞辭。太祖廟堂） 田敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8791ae3b-5795-4408-8336-207938f91270', '瘞筆磚文（趙光逢薄遊襄漢，濯足溪上，見一方磚碑，上題字云云。獨孤貞節立。磚後積土如盎，微有苔蘚，蓋好事者瘞筆所在。）', '瘞笔磚文（趙光逢薄游襄漢，濯足溪上，见一方磚碑，上題字云云。独孤貞節立。磚後積土如盎，微有苔蘚，蓋好事者瘞笔所在。）', '4bdbdd18-669c-4094-b6e4-77126ecb914a', '唐', '["禿友退鋒郎，功成鬢髮傷。","冢頭封馬鬣，不敢負恩光。","（《清異錄》四）。"]', '["禿友退鋒郎，功成鬢髮傷。","冢头封马鬣，不敢負恩光。","（《清異錄》四）。"]', '诗', 'shi', '', NULL, '瘞筆磚文（趙光逢薄遊襄漢，濯足溪上，見一方磚碑，上題字云云。獨孤貞節立。磚後積土如盎，微有苔蘚，蓋好事者瘞筆所在。） 獨孤貞節 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35f67bf-56c1-420c-b94a-14d3f277ecc2', '', '', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ee4606-5219-4573-9b79-ada4b2e5acc1', '春（一作「風」）光好（今按：《全宋詞》亦未收，故補之）（穀爲學士，奉使。恃上國勢，下視江左，辭色毅然不可犯。韓熙載命歌妓秦弱蘭詐爲驛卒女，每日敝衣持帚灑掃，陶悅之，與狎，因贈一詞，名《春光好》云云。明日，後〖一作中〗主設宴于澄心堂，陶辭色如前。乃命弱蘭歌前闋勸酒，陶大醉，爲主禮所薄，即日還朝，止遣數小吏餞于郊亭。迨歸京，鸞膠之曲已喧，陶因是竟不大用。）', '春（一作「风」）光好（今按：《全宋词》亦未收，故補之）（穀爲学士，奉使。恃上国勢，下視江左，辞色毅然不可犯。韓熙載命歌妓秦弱蘭詐爲驛卒女，每日敝衣持帚灑掃，陶悅之，與狎，因贈一词，名《春光好》云云。明日，後〖一作中〗主設宴于澄心堂，陶辞色如前。乃命弱蘭歌前闋勸酒，陶大醉，爲主禮所薄，即日還朝，止遣數小吏餞于郊亭。迨归京，鸾膠之曲已喧，陶因是竟不大用。）', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["好因緣，惡因緣，奈何天，只得郵亭一夜眠，別神仙。","琵琶撥盡相思調，知音少。","待（一作「安」）得鸞膠續斷絃，是何年？","（《玉壺清話》四，參《南唐近事》二）（〖1〗此詞異說較多，舉其要者有五說：一、陶穀於周世宗時使江南贈韓熙載歌妓秦弱蘭之作，見《南唐近事》卷二。","《苕溪漁隱業話後集》卷四十引《靖康緗素雜記》事同，但不云作詞。","二、時在入宋後，事同，見《冷齋夜話》及《玉壺清話》。","三、陶穀乾興中何吳越時贈任社娘之作，見沈遼《雲巢編》卷八《任社娘傳》，《研北雜志》引其說。","四、陶穀使錢唐日贈驛女詞，見《苕溪漁隱業話前集》卷二四引《本事曲》。","五、曹翰使江南娼妓詞，見前書引《江南野錄》。","以孰爲是，尚俟考詳。","）。"]', '["好因緣，惡因緣，奈何天，只得郵亭一夜眠，別神仙。","琵琶撥尽相思調，知音少。","待（一作「安」）得鸾膠續斷絃，是何年？","（《玉壺清話》四，參《南唐近事》二）（〖1〗此词異说較多，舉其要者有五说：一、陶穀於周世宗时使江南贈韓熙載歌妓秦弱蘭之作，见《南唐近事》卷二。","《苕溪漁隐業話後集》卷四十引《靖康緗素杂記》事同，但不云作词。","二、时在入宋後，事同，见《冷斋夜話》及《玉壺清話》。","三、陶穀乾兴中何吳越时贈任社娘之作，见沈遼《云巢編》卷八《任社娘傳》，《研北杂志》引其说。","四、陶穀使錢唐日贈驛女词，见《苕溪漁隐業話前集》卷二四引《本事曲》。","五、曹翰使江南娼妓词，见前书引《江南野錄》。","以孰爲是，尚俟考詳。","）。"]', '诗', 'shi', '', NULL, '春（一作「風」）光好（今按：《全宋詞》亦未收，故補之）（穀爲學士，奉使。恃上國勢，下視江左，辭色毅然不可犯。韓熙載命歌妓秦弱蘭詐爲驛卒女，每日敝衣持帚灑掃，陶悅之，與狎，因贈一詞，名《春光好》云云。明日，後〖一作中〗主設宴于澄心堂，陶辭色如前。乃命弱蘭歌前闋勸酒，陶大醉，爲主禮所薄，即日還朝，止遣數小吏餞于郊亭。迨歸京，鸞膠之曲已喧，陶因是竟不大用。） 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98113bdb-7c2e-40e5-93ed-7245eeb7f918', '獻詩吳越王（句）', '獻诗吳越王（句）', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["陶穀又嘗奉使兩浙，獻詩二十韻於錢俶，其末云云。","時穀官是丞郎，職爲學士，奉命小邦，獻詩已是失體，復有掃門之句，何辱命之甚也。","此生頭已白，無路掃王門。","（《國老談苑》一）。"]', '["陶穀又嘗奉使兩浙，獻诗二十韻於錢俶，其末云云。","时穀官是丞郎，職爲学士，奉命小邦，獻诗已是失體，复有掃门之句，何辱命之甚也。","此生头已白，無路掃王门。","（《国老談苑》一）。"]', '诗', 'shi', '', NULL, '獻詩吳越王（句） 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1688f7d-589f-40e0-872d-156be2bf236c', '', '', '435cbfc7-dd69-4955-a710-56ccde255032', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張振祖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acab50ca-daef-442b-aa67-ae9337669c40', '句（沙門愛英，住池陽村，示人之語曰：「萬論千經，不如無念無營。」因郡娼滿瑩娘，多姿而富情，真妓女中麟鳳。進士張振祖以無念無營，有情有色，製一聯云：）', '句（沙门愛英，住池陽村，示人之語曰：「万論千經，不如無念無營。」因郡娼满瑩娘，多姿而富情，真妓女中麟鳳。進士張振祖以無念無營，有情有色，製一聯云：）', '435cbfc7-dd69-4955-a710-56ccde255032', '唐', '["門前草滿無無老，牀底錢多有有娘。","（「錢多」，上引二本作「花多」。","）（《清異錄》一）（〖1〗張振祖，《惜陰軒業書》本《清異錄》卷上、原本《說郛》卷六一引《清異錄》，皆作「湯振祖」。","）。"]', '["门前草满無無老，牀底錢多有有娘。","（「錢多」，上引二本作「花多」。","）（《清異錄》一）（〖1〗張振祖，《惜陰軒業书》本《清異錄》卷上、原本《说郛》卷六一引《清異錄》，皆作「湯振祖」。","）。"]', '诗', 'shi', '', NULL, '句（沙門愛英，住池陽村，示人之語曰：「萬論千經，不如無念無營。」因郡娼滿瑩娘，多姿而富情，真妓女中麟鳳。進士張振祖以無念無營，有情有色，製一聯云：） 張振祖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4bae63d-af38-406b-9b12-afc37bfb38a0', '飛龍磵飲茶（句）', '飞龙磵饮茶（句）', '7754a32e-5145-4419-a1c3-9e888c866296', '唐', '["沾牙舊姓餘甘氏，破睡當封不夜侯。","（《清異錄》四）。"]', '["沾牙旧姓餘甘氏，破睡當封不夜侯。","（《清異錄》四）。"]', '诗', 'shi', '', NULL, '飛龍磵飲茶（句） 胡嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('333d1f25-fa37-4f06-af88-8dd20aa5d3e0', '朗吟（河陽釋法常，性英爽，酷嗜酒，無寒暑陰雨常醉，醉即熟睡，覺即朗吟曰：）', '朗吟（河陽釋法常，性英爽，酷嗜酒，無寒暑陰雨常醉，醉即熟睡，覺即朗吟曰：）', 'd92d49fc-cf33-4867-89e2-bfb7195b6b71', '唐', '["優遊麯世界，爛熳枕神仙。","（《清異錄》四）。"]', '["優游麯世界，爛熳枕神仙。","（《清異錄》四）。"]', '诗', 'shi', '', NULL, '朗吟（河陽釋法常，性英爽，酷嗜酒，無寒暑陰雨常醉，醉即熟睡，覺即朗吟曰：） 法常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace640ee-a412-4be3-a7c7-9ef65441393d', '湯戲（注湯幻茶）（饌茶而幻出物象于湯面者，茶匠通神之藝也。沙門福全生于金鄉，長于茶海，能注湯幻茶成一句詩，並點四甌。共一絕句，泛乎湯表，小小物類，唾手辦耳。檀越日造門求觀湯戲，全自詠曰：）', '湯戲（注湯幻茶）（饌茶而幻出物象于湯面者，茶匠通神之藝也。沙门福全生于金乡，长于茶海，能注湯幻茶成一句诗，並点四甌。共一絕句，泛乎湯表，小小物類，唾手辦耳。檀越日造门求观湯戲，全自詠曰：）', 'faba78e0-b9eb-4b2b-a9bc-2131d2cb2b66', '唐', '["生成盞裏水丹青，巧畫工夫學不成。","却笑當時陸鴻漸，煎茶贏得好名聲。","（《清異錄》四）。"]', '["生成盞裏水丹青，巧畫工夫学不成。","却笑當时陸鴻漸，煎茶贏得好名声。","（《清異錄》四）。"]', '诗', 'shi', '', NULL, '湯戲（注湯幻茶）（饌茶而幻出物象于湯面者，茶匠通神之藝也。沙門福全生于金鄉，長于茶海，能注湯幻茶成一句詩，並點四甌。共一絕句，泛乎湯表，小小物類，唾手辦耳。檀越日造門求觀湯戲，全自詠曰：） 福全 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ba0956-2918-456b-9e40-08263d6f0f3a', '詩（句）（《類說》卷十二引《紀異錄》云：龔林有卷投和凝，《登太行山詩》云：「『但得路可上，更高人也行。』」可據以補題。《紀異錄》，全名《洛中紀異錄》，宋秦再思撰。）', '诗（句）（《類说》卷十二引《紀異錄》云：龔林有卷投和凝，《登太行山诗》云：「『但得路可上，更高人也行。』」可據以補題。《紀異錄》，全名《洛中紀異錄》，宋秦再思撰。）', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["但有路可上，更高人也行。","（《老學庵筆記》四）。"]', '["但有路可上，更高人也行。","（《老学庵笔記》四）。"]', '诗', 'shi', '', NULL, '詩（句）（《類說》卷十二引《紀異錄》云：龔林有卷投和凝，《登太行山詩》云：「『但得路可上，更高人也行。』」可據以補題。《紀異錄》，全名《洛中紀異錄》，宋秦再思撰。） 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3127c30f-65da-41e1-8a3a-3c784d6e50fb', '', '', '8ce03e0e-0b03-4a28-a3b5-0397d67bd213', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張文伏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a489108-57ab-4a10-a0a5-f3b584980caa', '蒼嶺', '蒼嶺', '8ce03e0e-0b03-4a28-a3b5-0397d67bd213', '唐', '["絕壁不可攀，懸崖不可下。","路險心自平，由來無取舍。","穩穩須教著步行，前途荆棘胡從生？","（《古今圖書集成·山川典》一二○《括蒼山部》）。"]', '["絕壁不可攀，懸崖不可下。","路險心自平，由来無取舍。","穩穩須教著步行，前途荆棘胡從生？","（《古今圖书集成·山川典》一二○《括蒼山部》）。"]', '诗', 'shi', '', NULL, '蒼嶺 張文伏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55b9a79-77f0-413e-a05d-3e8bdb729d57', '渡江（〖1〗《十國春秋》三。前四句引《江表志》，後四句引《五國故事》。吳任臣按：《南唐書》此李後主詩也，後人誤以爲吳睿帝作。〖2〗《全唐詩》八作南唐後主李煜詩，題下注云：《江表志》作吳讓皇楊溥詩，題作《泰州永寧宮》。第四句「殿」，《十國春秋》作「榭」，第五、六二句爲「煙凝楚岫愁千點，雨滴吳江淚萬行。」末句「閒坐」作「端坐」。〖3〗此詩，鄭文寶《江表志》卷上、佚名《江南餘載》卷下、佚名《五國故事》卷上作吳讓皇楊溥作，三書皆宋初人著，鄭文寶先仕南唐後入宋；龍衮《江南野錄》卷三、馬令《南唐書》卷五作李', '渡江（〖1〗《十国春秋》三。前四句引《江表志》，後四句引《五国故事》。吳任臣按：《南唐书》此李後主诗也，後人誤以爲吳睿帝作。〖2〗《全唐诗》八作南唐後主李煜诗，題下注云：《江表志》作吳讓皇楊溥诗，題作《泰州永寧宮》。第四句「殿」，《十国春秋》作「榭」，第五、六二句爲「煙凝楚岫愁千点，雨滴吳江泪万行。」末句「閒坐」作「端坐」。〖3〗此诗，鄭文寶《江表志》卷上、佚名《江南餘載》卷下、佚名《五国故事》卷上作吳讓皇楊溥作，三书皆宋初人著，鄭文寶先仕南唐後入宋；龙衮《江南野錄》卷三、马令《南唐书》卷五作李', '88d43d71-eae0-4a5a-869c-47cc87987454', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '渡江（〖1〗《十國春秋》三。前四句引《江表志》，後四句引《五國故事》。吳任臣按：《南唐書》此李後主詩也，後人誤以爲吳睿帝作。〖2〗《全唐詩》八作南唐後主李煜詩，題下注云：《江表志》作吳讓皇楊溥詩，題作《泰州永寧宮》。第四句「殿」，《十國春秋》作「榭」，第五、六二句爲「煙凝楚岫愁千點，雨滴吳江淚萬行。」末句「閒坐」作「端坐」。〖3〗此詩，鄭文寶《江表志》卷上、佚名《江南餘載》卷下、佚名《五國故事》卷上作吳讓皇楊溥作，三書皆宋初人著，鄭文寶先仕南唐後入宋；龍衮《江南野錄》卷三、馬令《南唐書》卷五作李 楊溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02ba19c8-5e5f-4649-81f4-19273a252197', '樓上看九華（三首） 一', '楼上看九华（三首） 一', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["九朵連雲勢欲騰，鳥飛難到最高層。","誰家寫在屏風上，巖下松間盡九僧。","。"]', '["九朵連云勢欲腾，鸟飞难到最高層。","誰家寫在屏风上，巖下松间尽九僧。","。"]', '诗', 'shi', '', NULL, '樓上看九華（三首） 一 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1d2703-736a-4bbb-8016-cf6bc0675e94', '樓上看九華（三首） 二', '楼上看九华（三首） 二', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["九條寒玉罩雲中，雨外霞分海日紅。","疑是巧人新畫出，與他天柱作屏風。"]', '["九條寒玉罩云中，雨外霞分海日紅。","疑是巧人新畫出，與他天柱作屏风。"]', '诗', 'shi', '', NULL, '樓上看九華（三首） 二 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030a2cfc-f1bf-4c48-bba7-511d60550f6b', '樓上看九華（三首） 三', '楼上看九华（三首） 三', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["四顧巒峯峭莫羣，翠峯長與曉光分。","盡分明處要清白，獨倚青天絕片雲。","（《嘉靖池州府志》八。","又《九華山志》八有一三兩首）。"]', '["四顧巒峯峭莫羣，翠峯长與晓光分。","尽分明处要清白，独倚青天絕片云。","（《嘉靖池州府志》八。","又《九华山志》八有一三兩首）。"]', '诗', 'shi', '', NULL, '樓上看九華（三首） 三 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dbad26-1e83-4daa-a2df-1acfa619eba2', '歌（二章）（高祖行密改元開國時，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿頭懸一木，刻爲鯉魚形，行歌於市云云。其類此意者，凡數十章，時人莫能曉。後徐知誥禪代，復姓李氏，其言始應。） 一', '歌（二章）（高祖行密改元开国时，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿头懸一木，刻爲鯉鱼形，行歌於市云云。其類此意者，凡數十章，时人莫能晓。後徐知誥禪代，复姓李氏，其言始應。） 一', 'dc0262d1-ab7d-404b-97e8-c1f00ab73b4c', '唐', '["盟澤鯉魚肉爲角，濠梁鯉魚金刻鱗。","盟津鯉魚死欲盡，濠梁鯉魚始驚人。"]', '["盟澤鯉鱼肉爲角，濠梁鯉鱼金刻鱗。","盟津鯉鱼死欲尽，濠梁鯉鱼始驚人。"]', '诗', 'shi', '', NULL, '歌（二章）（高祖行密改元開國時，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿頭懸一木，刻爲鯉魚形，行歌於市云云。其類此意者，凡數十章，時人莫能曉。後徐知誥禪代，復姓李氏，其言始應。） 一 黃冠道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80261c65-cd1a-4309-a61e-686f2af4f24e', '歌（二章）（高祖行密改元開國時，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿頭懸一木，刻爲鯉魚形，行歌於市云云。其類此意者，凡數十章，時人莫能曉。後徐知誥禪代，復姓李氏，其言始應。） 二', '歌（二章）（高祖行密改元开国时，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿头懸一木，刻爲鯉鱼形，行歌於市云云。其類此意者，凡數十章，时人莫能晓。後徐知誥禪代，复姓李氏，其言始應。） 二', 'dc0262d1-ab7d-404b-97e8-c1f00ab73b4c', '唐', '["橫排三十六條鱗，個個圓如紫磨真。","爲甚竿頭挑着定，世間難遇識魚人。","（《十國春秋·吳》十二。","又《全五代詩》二十三轉引）（〖1〗見《釣磯立談》）。"]', '["橫排三十六條鱗，個個圓如紫磨真。","爲甚竿头挑着定，世间难遇識鱼人。","（《十国春秋·吳》十二。","又《全五代诗》二十三轉引）（〖1〗见《釣磯立談》）。"]', '诗', 'shi', '', NULL, '歌（二章）（高祖行密改元開國時，廣陵殷盛，士庶駢闐。道人狀如病狂，手持一竿，竿頭懸一木，刻爲鯉魚形，行歌於市云云。其類此意者，凡數十章，時人莫能曉。後徐知誥禪代，復姓李氏，其言始應。） 二 黃冠道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96484dbf-da5f-48aa-99fb-1a22523191cc', '應天長（〖1〗後主云：「先皇御製歌詞。」墨蹟在晁公留家○王國維輯《南唐二主詞》。今按：《全唐詩》八八九作李煜詞。）', '應天长（〖1〗後主云：「先皇御製歌词。」墨蹟在晁公留家○王国維輯《南唐二主词》。今按：《全唐诗》八八九作李煜词。）', '0f3c89c8-5be9-4680-b68b-d75e5f89afea', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '應天長（〖1〗後主云：「先皇御製歌詞。」墨蹟在晁公留家○王國維輯《南唐二主詞》。今按：《全唐詩》八八九作李煜詞。） 李璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f5f9e4-fe6a-469e-b9e3-1248e19d1669', '金銅蟾蜍硯滴銘', '金銅蟾蜍硯滴銘', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["捨月窟，伏棐几，爲我用，貯清泚。","端溪石，澄心紙，陳玄氏，毛錐子。","微我潤澤烏用汝，同列無譁聽驅使。","（《五代詩話》一）（〖1〗此則見鄭方坤《五代詩話》卷十，原出元陸友《研北雜志》卷下，云「李仲芳家有南唐金銅蟾蜍硯滴，重厚奇古，磨滅處金色愈明，非近世塗金比也。","腹下有篆銘」云云。","銘文末二句原書互乙，似失韻。","此歸李煜名下，無確據。","）。"]', '["捨月窟，伏棐几，爲我用，貯清泚。","端溪石，澄心紙，陳玄氏，毛錐子。","微我潤澤烏用汝，同列無譁听驱使。","（《五代诗話》一）（〖1〗此則见鄭方坤《五代诗話》卷十，原出元陸友《研北杂志》卷下，云「李仲芳家有南唐金銅蟾蜍硯滴，重厚奇古，磨滅处金色愈明，非近世塗金比也。","腹下有篆銘」云云。","銘文末二句原书互乙，似失韻。","此归李煜名下，無確據。","）。"]', '诗', 'shi', '', NULL, '金銅蟾蜍硯滴銘 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f14aae7-6e14-408b-82c1-b7d0c75c8f7b', '子夜歌（《全唐詩》八九九詞句只存首二句，題作《菩薩蠻》）', '子夜歌（《全唐诗》八九九词句只存首二句，題作《菩薩蠻》）', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["尋春須是先春早，看花莫待花枝老。","縹色玉柔擎，醅浮盞面清。","何妨頻笑粲，禁苑春歸晚。","同醉與閒平（一作「評」），詩隨羯鼓成。","（南詞本注。","參《歷代詩餘》）（〖1〗《歷代詩餘》卷九收此詞，調屬《菩薩蠻》，「羯鼓」作「疊鼓」。","）。"]', '["尋春須是先春早，看花莫待花枝老。","縹色玉柔擎，醅浮盞面清。","何妨頻笑粲，禁苑春归晚。","同醉與閒平（一作「評」），诗隨羯鼓成。","（南词本注。","參《歷代诗餘》）（〖1〗《歷代诗餘》卷九收此词，調屬《菩薩蠻》，「羯鼓」作「叠鼓」。","）。"]', '诗', 'shi', '', NULL, '子夜歌（《全唐詩》八九九詞句只存首二句，題作《菩薩蠻》） 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c37df8-fb65-47cd-bf24-54e53b6b5b25', '謝新恩（六首） 一', '謝新恩（六首） 一', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["秦樓不見吹簫女，空餘上苑風光。","粉英含蕊自低昂。","東風惱我，纔發一襟香。","瓊窗夢□留殘日，當年得恨何長。","碧闌干外映垂楊。","暫時相見，如夢懶思量。"]', '["秦楼不见吹簫女，空餘上苑风光。","粉英含蕊自低昂。","东风惱我，纔發一襟香。","瓊窗梦□留殘日，當年得恨何长。","碧闌干外映垂楊。","暫时相见，如梦懶思量。"]', '诗', 'shi', '', NULL, '謝新恩（六首） 一 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d17be52e-bcd6-4c06-9ddc-85fefc62a6ee', '謝新恩（六首） 二', '謝新恩（六首） 二', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["櫻花落盡階前月，象牀愁倚薰籠。","遠似去年今日恨還同。","雙鬟不整雲憔悴，淚沾紅抹胸。","何處相思苦？","紗窗醉夢中。"]', '["櫻花落尽階前月，象牀愁倚薰籠。","远似去年今日恨還同。","雙鬟不整云憔悴，泪沾紅抹胸。","何处相思苦？","紗窗醉梦中。"]', '诗', 'shi', '', NULL, '謝新恩（六首） 二 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19078e3-94dd-4f66-a1c1-888ca22e171e', '謝新恩（六首） 五', '謝新恩（六首） 五', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["櫻花落盡春將困，秋千架下歸時。","漏暗（疑作「滿階」）斜月遲遲，花在枝。","（缺二十字）徹曉紗窗下，待來君不知。"]', '["櫻花落尽春將困，秋千架下归时。","漏暗（疑作「满階」）斜月遲遲，花在枝。","（缺二十字）徹晓紗窗下，待来君不知。"]', '诗', 'shi', '', NULL, '謝新恩（六首） 五 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54890b82-cf00-4c9f-8d96-6635b3f5b8f7', '謝新恩（六首） 六', '謝新恩（六首） 六', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["冉冉秋[光]（色）留不住，滿階紅葉暮。","又是過重陽，臺榭登臨處。","茱萸花墜，紫菊氣，飄庭戶，[晚]烟籠細[雨]（細）。","嗈嗈新雁咽寒聲，愁恨年年長相似。","（以上南詞本注）（〖1〗據詹安泰《李璟李煜詞》校改。","）。"]', '["冉冉秋[光]（色）留不住，满階紅葉暮。","又是過重陽，台榭登臨处。","茱萸花墜，紫菊氣，飄庭戶，[晚]烟籠細[雨]（細）。","嗈嗈新雁咽寒声，愁恨年年长相似。","（以上南词本注）（〖1〗據詹安泰《李璟李煜词》校改。","）。"]', '诗', 'shi', '', NULL, '謝新恩（六首） 六 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637eefcb-d15c-4959-9651-27090271b1bd', '娼樓行（句）', '娼楼行（句）', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["龍腦香調水，教人染退紅。","（《老學庵續筆記》）。"]', '["龙腦香調水，教人染退紅。","（《老学庵續笔記》）。"]', '诗', 'shi', '', NULL, '娼樓行（句） 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e445b3be-12db-44f7-9132-9480e0046fe5', '莫思歸（即《拋球樂》）', '莫思归（即《拋球乐》）', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["花滿名園酒滿觴，且開笑口對穠芳。","秋千風暖鸞釵嚲，綺陌春深翠袖香。","莫惜黃金貴，日日須教貰酒嘗。","（《花草粹編》一）。"]', '["花满名园酒满觴，且开笑口对穠芳。","秋千风暖鸾釵嚲，綺陌春深翠袖香。","莫惜黄金貴，日日須教貰酒嘗。","（《花草粹編》一）。"]', '诗', 'shi', '', NULL, '莫思歸（即《拋球樂》） 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fefbe4-af8e-46b4-95f4-68c4b6be63b4', '采春子', '采春子', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["櫻桃謝了梨花發，紅白相催。","燕子歸來，幾處香風綠戶開。","人生樂事知多少，且酌金杯。","管咽弦哀，慢引蕭娘舞袖迴。","（《萬代詩餘》）（〖1〗見《歷代詩餘》卷十，調屬《采桑子》。","）。"]', '["櫻桃謝了梨花發，紅白相催。","燕子归来，幾处香风綠戶开。","人生乐事知多少，且酌金杯。","管咽弦哀，慢引蕭娘舞袖迴。","（《万代诗餘》）（〖1〗见《歷代诗餘》卷十，調屬《采桑子》。","）。"]', '诗', 'shi', '', NULL, '采春子 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befd8155-bdef-4d9c-9777-14f18eff22b0', '玉樓春', '玉楼春', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["雪雲乍變春雲簇，漸覺年華堪縱目。","北枝梅蕊犯寒開，南浦波紋如酒綠。","芳菲次第長相續，自是情多何處足。","尊前百計得春歸，莫爲傷春眉黛蹙。","（《尊前集》）（〖1〗此詞又見《歐陽文忠公近體樂府》卷二。","）。"]', '["雪云乍变春云簇，漸覺年华堪縱目。","北枝梅蕊犯寒开，南浦波紋如酒綠。","芳菲次第长相續，自是情多何处足。","尊前百計得春归，莫爲傷春眉黛蹙。","（《尊前集》）（〖1〗此词又见《歐陽文忠公近體乐府》卷二。","）。"]', '诗', 'shi', '', NULL, '玉樓春 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('878c403d-a570-430f-a554-c4e74b04ff6c', '感懷', '感懷', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["幽禽喚杜宇，宿蝶夢莊周。","席地一尊酒，思與元化浮。","但莫孤明月，何必秉燭游。","（〖1〗見《法藏碎金錄》卷六。","）。"]', '["幽禽喚杜宇，宿蝶梦莊周。","席地一尊酒，思與元化浮。","但莫孤明月，何必秉燭游。","（〖1〗见《法藏碎金錄》卷六。","）。"]', '诗', 'shi', '', NULL, '感懷 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e619f1-1f50-4f84-b78a-0c7ab42a62fc', '獨坐（句）', '独坐（句）', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["凝神入混茫，萬象成空虛（一作「萬有成虛空」。","）（《詩話總龜後集》四三《釋氏門》引《法藏碎金》。","又《全五代詩》三一引）（〖1〗《法藏碎金錄》卷七收二句，作「凝神入混沌，萬法成虛空」。","同書卷六錄前一句。","）。"]', '["凝神入混茫，万象成空虛（一作「万有成虛空」。","）（《诗話總龟後集》四三《釋氏门》引《法藏碎金》。","又《全五代诗》三一引）（〖1〗《法藏碎金錄》卷七收二句，作「凝神入混沌，万法成虛空」。","同书卷六錄前一句。","）。"]', '诗', 'shi', '', NULL, '獨坐（句） 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6cf8f52-91bf-473d-9bdf-34a64df18692', '愛敬寺（句）', '愛敬寺（句）', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["雲散經窗濕，山晴石路香。","（《六朝事迹編類》卷下《寺院門·大愛敬寺》）。"]', '["云散經窗濕，山晴石路香。","（《六朝事迹編類》卷下《寺院门·大愛敬寺》）。"]', '诗', 'shi', '', NULL, '愛敬寺（句） 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6634b107-d426-4829-a2c9-e929aa78b006', '句', '句', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["牆陰沙岸靜，島色海山孤。","（《輿地紀勝》七《鎮江府》）。"]', '["牆陰沙岸静，島色海山孤。","（《輿地紀勝》七《鎮江府》）。"]', '诗', 'shi', '', NULL, '句 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a552d241-e431-4534-9fe8-6089ec3dcba6', '觀山水障歌', '观山水障歌', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["適來一觀山水障，萬里江山在其上。","遠近猶如二月春，咫尺分成百般像。","一巖嵯峨入雲際，七賢鎮在青松裏。","潭水澄泓不見波，孤帆滉漾張風勢。","釣魚老翁無伴侶，孑然此地輕寒暑。","灘頭坐久髩絲垂，手把魚竿不曾舉。","樹婀娜，山崔嵬，片雲似去又不去，雙鶴如飛又不飛。","良工巧匠多分布，筆頭寫出江山[路]（頭）。","垂柳風吹不動條，樵人負重難移步。","（《全五代詩》三九）（〖1〗見宋孫紹遠《聲畫集》卷四。","）。"]', '["適来一观山水障，万里江山在其上。","远近猶如二月春，咫尺分成百般像。","一巖嵯峨入云際，七賢鎮在青松裏。","潭水澄泓不见波，孤帆滉漾張风勢。","釣鱼老翁無伴侶，孑然此地轻寒暑。","灘头坐久髩絲垂，手把鱼竿不曾舉。","樹婀娜，山崔嵬，片云似去又不去，雙鹤如飞又不飞。","良工巧匠多分布，笔头寫出江山[路]（头）。","垂柳风吹不动條，樵人負重难移步。","（《全五代诗》三九）（〖1〗见宋孫紹远《声畫集》卷四。","）。"]', '诗', 'shi', '', NULL, '觀山水障歌 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c39b918-ad90-4174-b18f-1b11faac330b', '句', '句', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["竹影橫斜水清淺，桂香浮動月黃昏。","（《紫桃軒雜綴》）（〖1〗明李日華《紫桃軒雜綴》謂林逋名句「疎影橫斜水清淺，暗香浮動月黃昏」二句爲改江爲二句而成。","所據不詳。","）。"]', '["竹影橫斜水清淺，桂香浮动月黄昏。","（《紫桃軒杂綴》）（〖1〗明李日华《紫桃軒杂綴》謂林逋名句「疎影橫斜水清淺，暗香浮动月黄昏」二句爲改江爲二句而成。","所據不詳。","）。"]', '诗', 'shi', '', NULL, '句 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5feafc-6d3d-409c-9d90-28389ddc72ff', '岳陽樓（句）', '岳陽楼（句）', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["檻外有天皆在照，望中無物敢潛行。","（《輿地紀勝》六九《岳州》）。"]', '["檻外有天皆在照，望中無物敢潛行。","（《輿地紀勝》六九《岳州》）。"]', '诗', 'shi', '', NULL, '岳陽樓（句） 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f9c99d-f8f2-4a91-92bc-6f8042e25ea1', '浣溪沙（〖1〗詞《全唐詩》八九一作張曙詞，第二句「苦」，《花間集》作「兩」。○《花間集》〖2〗《北夢瑣言》卷八作張曙詞，《全唐詩》沿之。或疑張曙、張泌爲同一人。）', '浣溪沙（〖1〗词《全唐诗》八九一作張曙词，第二句「苦」，《花间集》作「兩」。○《花间集》〖2〗《北梦瑣言》卷八作張曙词，《全唐诗》沿之。或疑張曙、張泌爲同一人。）', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '浣溪沙（〖1〗詞《全唐詩》八九一作張曙詞，第二句「苦」，《花間集》作「兩」。○《花間集》〖2〗《北夢瑣言》卷八作張曙詞，《全唐詩》沿之。或疑張曙、張泌爲同一人。） 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a578467-0a03-4856-af04-22f75c8d08fe', '送人遊南海', '送人游南海', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["白煙和月藏巒洞，明月隨潮入瘴村。","更想臨高見佳景，越王臺上酒盈罇。","（《輿地紀勝》八九《廣州》）。"]', '["白煙和月藏巒洞，明月隨潮入瘴村。","更想臨高见佳景，越王台上酒盈罇。","（《輿地紀勝》八九《廣州》）。"]', '诗', 'shi', '', NULL, '送人遊南海 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c523b3b6-33cf-4903-8eeb-b35ef79c1ba7', '句', '句', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["龍約海船行有氣，象隈銅柱臥成痕。","（同上一○六《邕州》）。"]', '["龙約海船行有氣，象隈銅柱臥成痕。","（同上一○六《邕州》）。"]', '诗', 'shi', '', NULL, '句 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7c0063-b78c-4dac-9b91-9e973b97a9ab', '金陵覽古（〖1〗《全五代詩》三二引《十國春秋》：保大時，存嘗取吳大帝及六國興亡成敗之迹，作《覽古詩》二百章，章四句，地志家多援以爲證。又《金陵詩徵》引《建康志》略同。）', '金陵覽古（〖1〗《全五代诗》三二引《十国春秋》：保大时，存嘗取吳大帝及六国兴亡成敗之迹，作《覽古诗》二百章，章四句，地志家多援以爲證。又《金陵诗徵》引《建康志》略同。）', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '金陵覽古（〖1〗《全五代詩》三二引《十國春秋》：保大時，存嘗取吳大帝及六國興亡成敗之迹，作《覽古詩》二百章，章四句，地志家多援以爲證。又《金陵詩徵》引《建康志》略同。） 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e0d8d0-bb96-47fb-a8ce-4975ecb3ae8e', '北渠（歷代宮苑殿閣制度）', '北渠（歷代宮苑殿閣制度）', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["金殿分來玉砌流，黑龍湖徹鳳池頭。","後庭花落恩波斷，翻與南唐作御溝。","（〖1〗「南唐」，張敦頤《六朝事迹編類》卷上〖作楊修詩〗引作「南塘」。","）。"]', '["金殿分来玉砌流，黑龙湖徹鳳池头。","後庭花落恩波斷，翻與南唐作御溝。","（〖1〗「南唐」，張敦頤《六朝事迹編類》卷上〖作楊修诗〗引作「南塘」。","）。"]', '诗', 'shi', '', NULL, '北渠（歷代宮苑殿閣制度） 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f1ecba-dcec-4597-a1a3-d64ca380c08f', '秦淮（以下景物）', '秦淮（以下景物）', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["一氣東南王斗牛，祖龍潛爲子孫憂。","金陵地脈何曾斷，不覺真人已姓劉。"]', '["一氣东南王斗牛，祖龙潛爲子孫憂。","金陵地脈何曾斷，不覺真人已姓劉。"]', '诗', 'shi', '', NULL, '秦淮（以下景物） 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cb906a-c6d2-4239-8bbe-c7c28639109c', '東山', '东山', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["鎮物高情濟世才，欲隨猿鶴老岩隈。","山花處處紅粧面，髣髴如初擁妓來。","（〖1〗以上二首，又見《記纂淵海》卷十。","）。"]', '["鎮物高情濟世才，欲隨猿鹤老岩隈。","山花处处紅粧面，髣髴如初擁妓来。","（〖1〗以上二首，又见《記纂淵海》卷十。","）。"]', '诗', 'shi', '', NULL, '東山 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c7c6d8-4f4a-428b-99f1-d3de6dbfd9f3', '新亭', '新亭', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["滿目江山異洛陽，昔人何必重悲傷。","倘能戮力扶王室，當自新亭復故鄉。","。"]', '["满目江山異洛陽，昔人何必重悲傷。","倘能戮力扶王室，當自新亭复故乡。","。"]', '诗', 'shi', '', NULL, '新亭 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb16d63-1f52-42c0-8faf-0fd97e4d4a46', '天闕山', '天闕山', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["牛頭天際碧凝嵐，王導無稽亦妄談。","若指遠公爲上闕，長安應合指終南。"]', '["牛头天際碧凝嵐，王導無稽亦妄談。","若指远公爲上闕，长安應合指終南。"]', '诗', 'shi', '', NULL, '天闕山 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1e7124c-254b-4ccd-a64b-b6a23911f07c', '石頭城', '石头城', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["五城樓雉各相望，山水英靈宅帝王。","此地定由天造險，古來長恃作金湯。"]', '["五城楼雉各相望，山水英靈宅帝王。","此地定由天造險，古来长恃作金湯。"]', '诗', 'shi', '', NULL, '石頭城 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960372d0-3380-43e4-b7ae-b0b0737e304a', '烏衣巷', '烏衣巷', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["人物風流往往非，空餘陋巷作烏衣。","舊時簾幕無從覓，祇有年年社燕歸。"]', '["人物风流往往非，空餘陋巷作烏衣。","旧时簾幕無從覓，祇有年年社燕归。"]', '诗', 'shi', '', NULL, '烏衣巷 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c8c348-7f33-41de-a8dc-1f3cbfe647fa', '段石崗', '段石崗', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["孫吳紀德舊刊碑，草沒蟠螭與伏龜。","惆悵崗頭三段石，至今猶似鼎分時。"]', '["孫吳紀德旧刊碑，草沒蟠螭與伏龟。","惆悵崗头三段石，至今猶似鼎分时。"]', '诗', 'shi', '', NULL, '段石崗 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7960637d-3110-45cc-aaf3-19e3d194d7a8', '玄武湖（〖1〗《全唐詩》七五七及《全五代詩》三一只存此一首，題作《後湖》，第二句「三翼」《全唐詩》作「三異」，第四句「下多時」《全唐詩》作「不多時」。）', '玄武湖（〖1〗《全唐诗》七五七及《全五代诗》三一只存此一首，題作《後湖》，第二句「三翼」《全唐诗》作「三異」，第四句「下多时」《全唐诗》作「不多时」。）', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '玄武湖（〖1〗《全唐詩》七五七及《全五代詩》三一只存此一首，題作《後湖》，第二句「三翼」《全唐詩》作「三異」，第四句「下多時」《全唐詩》作「不多時」。） 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad26321-cdcd-4d15-9e5a-f6a66c4877f3', '阿育王塔', '阿育王塔', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["窣堵凝然鎮梵宮，舉頭層級在雲中。","金棺舍利藏何處？鐸繞危簷聲撼風。","（以上《輿地紀勝》十七《建康府》。","又《金陵詩徵》四）。"]', '["窣堵凝然鎮梵宮，舉头層級在云中。","金棺舍利藏何处？鐸繞危簷声撼风。","（以上《輿地紀勝》十七《建康府》。","又《金陵诗徵》四）。"]', '诗', 'shi', '', NULL, '阿育王塔 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c40ff4a-e276-405d-8d8e-c6537d6bfc13', '賦山別諸知己', '賦山別諸知己', 'a6fcee11-a4c5-4245-a010-a5d9d47c68e6', '唐', '["暮景江亭上，雲山日望多。","只愁[辭]（解）輦轂，長恨隔嵯峨。","有意圖功業，無心憶薜蘿。","親朋將遠別，且共醉笙歌。","（《徐鉉集》三。","又《全五代詩》二九）。"]', '["暮景江亭上，云山日望多。","只愁[辞]（解）輦轂，长恨隔嵯峨。","有意圖功業，無心憶薜蘿。","親朋將远別，且共醉笙歌。","（《徐鉉集》三。","又《全五代诗》二九）。"]', '诗', 'shi', '', NULL, '賦山別諸知己 鍾蒨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db1fa85-3d2e-4d44-8c9c-16d72a9b6a26', '小梅（句）（徐鉉《和亞元長歌》中有句云：「開緘試讀相思字，乃是多情喬亞元。短韻三篇皆麗絕，小梅寄意情偏切。」自注：「亞元詩云云。此語尤嘉。」）', '小梅（句）（徐鉉《和亞元长歌》中有句云：「开緘試读相思字，乃是多情喬亞元。短韻三篇皆丽絕，小梅寄意情偏切。」自注：「亞元诗云云。此語尤嘉。」）', '64fd6d9a-5dff-4e2c-94eb-487a0376e530', '唐', '["借問小梅應得信，春風新自海邊來。","（《徐鉉集》三）。"]', '["借问小梅應得信，春风新自海邊来。","（《徐鉉集》三）。"]', '诗', 'shi', '', NULL, '小梅（句）（徐鉉《和亞元長歌》中有句云：「開緘試讀相思字，乃是多情喬亞元。短韻三篇皆麗絕，小梅寄意情偏切。」自注：「亞元詩云云。此語尤嘉。」） 喬舜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2125724c-2cde-4385-b8a3-89bf6e20ac05', '送季大夫牧舒州', '送季大夫牧舒州', 'c21e5c6a-4c30-4b4a-ba04-7edc4ca13e0e', '唐', '["却下烏臺建隼旟，侯封歸去襲龍舒。","嚴霜尚滿辭天闕，甘雨看隨入境車。","（《輿地紀勝》四六《安慶府》）。"]', '["却下烏台建隼旟，侯封归去襲龙舒。","嚴霜尚满辞天闕，甘雨看隨入境车。","（《輿地紀勝》四六《安慶府》）。"]', '诗', 'shi', '', NULL, '送季大夫牧舒州 湯悅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ad294f1-6ea3-4b21-9fc6-0a34a62c21fe', '楊柳枝', '楊柳枝', '33d2b6df-87b5-447e-95e3-38e592fe66c7', '唐', '["欲趁寒梅趁得麽，雪中偷眼望陽和。","陽和若不先留意，這箇柔條爭奈何。","（《尊前集》）。"]', '["欲趁寒梅趁得麽，雪中偷眼望陽和。","陽和若不先留意，這箇柔條爭奈何。","（《尊前集》）。"]', '诗', 'shi', '', NULL, '楊柳枝 成文幹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa12798f-be17-4112-9fbd-43d630af0c8d', '東林寺天祚二年聯句', '东林寺天祚二年聯句', 'd9e93f9f-5a5b-4f55-826a-daccfa01fa2f', '唐', '["古殿巍峩鎮碧峯，晉朝靈應顯神蹤。","林間野鳥驚朝梵，嶺上孤猿聽曉鐘。","蝶戀半岩花灼灼，鹿眠深谷草茸茸。","遊僧駐錫心皆佛，老樹擎煙勢似龍。","竹蔭禪扃青靄合，嵐蒸幽逕綠苔封。","老來欲脫塵寰境，閑訪空關不厭重。","（《永樂大典》六六九七江字韻引《九江府志》，又六六九九引《江州志》）（〖1〗《吉石庵叢書》本《廬山記》收此詩，爲徐知證及其僚屬虔修、孟拱辰等七人聯句之作。","又此處所錄亦未完。","另詳《全唐詩續拾》卷四三。","）。"]', '["古殿巍峩鎮碧峯，晉朝靈應显神蹤。","林间野鸟驚朝梵，嶺上孤猿听晓鐘。","蝶戀半岩花灼灼，鹿眠深谷草茸茸。","游僧駐錫心皆佛，老樹擎煙勢似龙。","竹蔭禪扃青靄合，嵐蒸幽逕綠苔封。","老来欲脫塵寰境，闲訪空关不厭重。","（《永乐大典》六六九七江字韻引《九江府志》，又六六九九引《江州志》）（〖1〗《吉石庵叢书》本《廬山記》收此诗，爲徐知證及其僚屬虔修、孟拱辰等七人聯句之作。","又此处所錄亦未完。","另詳《全唐诗續拾》卷四三。","）。"]', '诗', 'shi', '', NULL, '東林寺天祚二年聯句 徐知證 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4634e2a3-62bd-422d-b121-98fd59ea8775', '韻妙空（句）（妙空，名守納。嗣法於雪峯，卯一，齋住嘉祐禪院，江南李氏三召不起，刺史皇甫繼勳贈之詩云：）', '韻妙空（句）（妙空，名守納。嗣法於雪峯，卯一，斋住嘉祐禪院，江南李氏三召不起，刺史皇甫繼勳贈之诗云：）', '254b65d9-3b5f-4aca-aa8e-537e16baa0ef', '唐', '["白面山南靈慶院，卯齋道者雪峯禪。","（《嘉靖池州府志》九）。"]', '["白面山南靈慶院，卯斋道者雪峯禪。","（《嘉靖池州府志》九）。"]', '诗', 'shi', '', NULL, '韻妙空（句）（妙空，名守納。嗣法於雪峯，卯一，齋住嘉祐禪院，江南李氏三召不起，刺史皇甫繼勳贈之詩云：） 皇甫繼勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf63eca5-5200-44e7-b4ef-41226226df15', '喜賊平謁李將軍祠', '喜賊平謁李將軍祠', '8fa9012e-6a9e-4708-8f1d-4b2d27b4cd4e', '唐', '["君向神重謁，天教君亦神。","十年香火主，百物雨暘身。","忠在偏誅賊，恩多每濟人。","高歌震霄壑，朝野遍陽春。","（《上饒縣志》二三）。"]', '["君向神重謁，天教君亦神。","十年香火主，百物雨暘身。","忠在偏誅賊，恩多每濟人。","高歌震霄壑，朝野遍陽春。","（《上饒縣志》二三）。"]', '诗', 'shi', '', NULL, '喜賊平謁李將軍祠 危仔昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a15eb21-56f6-411e-9d34-3c54599eeddc', '黃鶴樓（《宋詩紀事》亦未收）', '黄鹤楼（《宋诗紀事》亦未收）', '01728a42-6b40-4e5e-8878-9156e380ff65', '唐', '["黃鶴何年去杳冥，高城千載倚江城。","碧雲朝捲四山景，流水夜傳三峽聲。","柳暗西州供騁望，草芳南浦徧離情。","登臨一晌須回首，看却鄉心萬感生。","（《古今圖書集成·職方典》一一二五《武昌府部》）（〖1〗見北宋熙寧間刻《鄂州雜詩碑》，參前「賈島」條。","又見《方輿勝覽》卷二八。","）。"]', '["黄鹤何年去杳冥，高城千載倚江城。","碧云朝捲四山景，流水夜傳三峽声。","柳暗西州供騁望，草芳南浦徧離情。","登臨一晌須回首，看却乡心万感生。","（《古今圖书集成·職方典》一一二五《武昌府部》）（〖1〗见北宋熙寧间刻《鄂州杂诗碑》，參前「賈島」條。","又见《方輿勝覽》卷二八。","）。"]', '诗', 'shi', '', NULL, '黃鶴樓（《宋詩紀事》亦未收） 盧郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47b552e-260d-428d-a79d-20065ed8ce16', '', '', 'ff4730e9-824a-4f35-8000-958f57a1c337', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 唐希雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b607ad8-c5d4-4e5c-80dc-66fe72fb1489', '題畫', '題畫', 'ff4730e9-824a-4f35-8000-958f57a1c337', '唐', '["誰潑煙雲六尺綃，寒山秋樹晚蕭蕭。","十年來往吳淞口，錯認溪南舊板橋。","（《全五代詩》三六引《槜李詩繫》）（〖1〗見《槜李詩繫》卷一。","）。"]', '["誰潑煙云六尺綃，寒山秋樹晚蕭蕭。","十年来往吳淞口，錯認溪南旧板橋。","（《全五代诗》三六引《槜李诗繫》）（〖1〗见《槜李诗繫》卷一。","）。"]', '诗', 'shi', '', NULL, '題畫 唐希雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb87e02-9d4f-4010-bb63-912975409175', '小桃源（一題《入黟吟》。《輿地紀勝》二十作李白詩）（未詳其所自來，客遊於黟，樂之，作詩云云，遂家焉。今桃源洞有許氏，蓋其後裔云。或曰：堅即宣平，堅其名，宣平其字，未知是否。〖1〗）', '小桃源（一題《入黟吟》。《輿地紀勝》二十作李白诗）（未詳其所自来，客游於黟，乐之，作诗云云，遂家焉。今桃源洞有許氏，蓋其後裔云。或曰：堅即宣平，堅其名，宣平其字，未知是否。〖1〗）', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["黟邑桃源小，煙霞百里寬。","地多靈草木，人尚古衣冠。","市向晡時散，山經夜後寒。","吏閒民訟簡，秋菊露漙漙。","（康熙《徽州府志》十七《流寓傳》。","又見《黟縣志》十六）（〖1〗此說誤。","《太平廣記》卷二四引《續仙傳》謂許宣平爲景雲中人，許堅則爲南唐人，其間相隔二百餘年。","又本詩前已收李白名下，惟此多末二句。","）。"]', '["黟邑桃源小，煙霞百里寬。","地多靈草木，人尚古衣冠。","市向晡时散，山經夜後寒。","吏閒民訟簡，秋菊露漙漙。","（康熙《徽州府志》十七《流寓傳》。","又见《黟縣志》十六）（〖1〗此说誤。","《太平廣記》卷二四引《續仙傳》謂許宣平爲景云中人，許堅則爲南唐人，其间相隔二百餘年。","又本诗前已收李白名下，惟此多末二句。","）。"]', '诗', 'shi', '', NULL, '小桃源（一題《入黟吟》。《輿地紀勝》二十作李白詩）（未詳其所自來，客遊於黟，樂之，作詩云云，遂家焉。今桃源洞有許氏，蓋其後裔云。或曰：堅即宣平，堅其名，宣平其字，未知是否。〖1〗） 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb067622-99a3-4baa-8e99-218b1e86a418', '戢兵山（舊名石鼓山，在黟縣北十五里，高百仞，周十里，有石鼓、石人、石驢。相傳石鼓鳴即驢鳴，人哭而長官不利。後鑿其鼓破之，遂不復鳴。唐天寶六年改今名。）', '戢兵山（旧名石鼓山，在黟縣北十五里，高百仞，周十里，有石鼓、石人、石驢。相傳石鼓鳴即驢鳴，人哭而长官不利。後鑿其鼓破之，遂不复鳴。唐天寶六年改今名。）', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["石鼓高懸藴大音，白雲峯頂始鋪金。","能來斯地鼓斯鼓，盡達曹溪聖祖心。"]', '["石鼓高懸藴大音，白云峯頂始鋪金。","能来斯地鼓斯鼓，尽達曹溪聖祖心。"]', '诗', 'shi', '', NULL, '戢兵山（舊名石鼓山，在黟縣北十五里，高百仞，周十里，有石鼓、石人、石驢。相傳石鼓鳴即驢鳴，人哭而長官不利。後鑿其鼓破之，遂不復鳴。唐天寶六年改今名。） 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb236b4-9a8e-4f7b-ad1f-36b319e35c7c', '中秋詠月（詠詩後，乘興遂子夜鳴鐘，烈祖聞之，不罪也。召問其所求，唯願鵝生四脚，鼈著兩裙。）', '中秋詠月（詠诗後，乘兴遂子夜鳴鐘，烈祖闻之，不罪也。召问其所求，唯願鵝生四脚，鼈著兩裙。）', '7de5b584-d7f4-47c4-93ec-002b48f02e64', '唐', '["迢迢東海出，漸漸入雲衢。","此夜一輪滿，清光何處無。","（《江南餘載》下）（〖1〗《歲時廣記》三十一《中秋》上《得佳聯》引《漫叟詩話》：「南唐金輪寺有僧曰明光者，先一年中秋翫月，得詩一聯云：『團團離海角，漸漸出雲衢。","』竟思下聯不就。","次年中秋，再得一聯云：『此夜一輪滿，清光何處無？","』遂不勝其喜，徑登寺樓鳴鐘。","時有善聽聲聞之：『此鐘發聲通暢，若非詩人得句，即是禪僧悟道。","』驗之果然。","好事者有詩云：『爲思銀漢中秋月，誤擊金輪半夜鐘。","』」〖2〗《全唐詩》八五一、《全五代詩》三九均作南唐失名僧《月詩》，前二句作「徐徐東海出，漸漸上天衢」。","《全五代詩》引《江南野錄》：「李昪受禪之初，忽半夜寺僧撞鐘，一城皆驚，召將斬之，云夜來偶得月詩，乃云云。","李昪喜而釋之。","」〖3〗原以明光另列一則。","今檢《苕溪漁隱叢話前集》卷二十六引《漫叟詩話》作「南唐僧謙明」詩，知明光之名爲南宋時之別傳，而非另有其人，故以明光一則移附於此。","另《釣磯立談》謂作詩者爲「頭陀范忠嵩」。","《江鄰幾雜識》作「南唐一詩僧」，當即爲《全唐詩》所本。","）。"]', '["迢迢东海出，漸漸入云衢。","此夜一輪满，清光何处無。","（《江南餘載》下）（〖1〗《歲时廣記》三十一《中秋》上《得佳聯》引《漫叟诗話》：「南唐金輪寺有僧曰明光者，先一年中秋翫月，得诗一聯云：『團團離海角，漸漸出云衢。","』竟思下聯不就。","次年中秋，再得一聯云：『此夜一輪满，清光何处無？","』遂不勝其喜，徑登寺楼鳴鐘。","时有善听声闻之：『此鐘發声通暢，若非诗人得句，即是禪僧悟道。","』驗之果然。","好事者有诗云：『爲思銀漢中秋月，誤擊金輪半夜鐘。","』」〖2〗《全唐诗》八五一、《全五代诗》三九均作南唐失名僧《月诗》，前二句作「徐徐东海出，漸漸上天衢」。","《全五代诗》引《江南野錄》：「李昪受禪之初，忽半夜寺僧撞鐘，一城皆驚，召將斬之，云夜来偶得月诗，乃云云。","李昪喜而釋之。","」〖3〗原以明光另列一則。","今檢《苕溪漁隐叢話前集》卷二十六引《漫叟诗話》作「南唐僧謙明」诗，知明光之名爲南宋时之別傳，而非另有其人，故以明光一則移附於此。","另《釣磯立談》謂作诗者爲「头陀范忠嵩」。","《江鄰幾杂識》作「南唐一诗僧」，當即爲《全唐诗》所本。","）。"]', '诗', 'shi', '', NULL, '中秋詠月（詠詩後，乘興遂子夜鳴鐘，烈祖聞之，不罪也。召問其所求，唯願鵝生四脚，鼈著兩裙。） 謙明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbaceb68-ec34-44a8-9775-d015c3986bbc', '青史樓引賓從同登', '青史楼引賓從同登', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["雲閣霞軒別構雄，下窺疆宇壯吳宮。","洪濤日日來滄海，碧嶂聯聯倚太穹。","志仗四征平逆孽，力扶三帝有褒崇。","如今分野無狼孛，青史樓標定亂功。"]', '["云閣霞軒別構雄，下窺疆宇壯吳宮。","洪濤日日来滄海，碧嶂聯聯倚太穹。","志仗四征平逆孽，力扶三帝有褒崇。","如今分野無狼孛，青史楼標定亂功。"]', '诗', 'shi', '', NULL, '青史樓引賓從同登 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccd8337-7689-474a-b435-eb11c29eb2b2', '石鏡山（幷序）', '石镜山（幷序）', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["丱歲遨遊在此山，曾驚一石立山前。","未能顯瑞披榛莽，蓋爲平兇有歲年。","昨返錦門停駟馬，遂開靈岫種青蓮。","三吳百粤興金地，永與軍民作福田。"]', '["丱歲遨游在此山，曾驚一石立山前。","未能显瑞披榛莽，蓋爲平兇有歲年。","昨返錦门停駟马，遂开靈岫種青蓮。","三吳百粤兴金地，永與軍民作福田。"]', '诗', 'shi', '', NULL, '石鏡山（幷序） 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4494c7db-e391-4523-beb9-a367c2be5861', '築塘', '築塘', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["天分浙水應東溟，日夜波濤不暫停。","千尺巨堤衝欲裂，萬人力禦勢須平。","吳都地窄兵師廣，羅剎名高海衆獰。","爲報龍神幷水府，錢塘且借作錢城。","（〖1〗《全唐詩》卷八據《吳越備史》收「傳語龍王並水府，錢塘借與築錢城」二句。","）。"]', '["天分浙水應东溟，日夜波濤不暫停。","千尺巨堤衝欲裂，万人力禦勢須平。","吳都地窄兵師廣，羅剎名高海衆獰。","爲報龙神幷水府，錢塘且借作錢城。","（〖1〗《全唐诗》卷八據《吳越備史》收「傳語龙王並水府，錢塘借與築錢城」二句。","）。"]', '诗', 'shi', '', NULL, '築塘 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec46cbe7-e9d1-4216-89ed-446b55f08115', '九日同羣僚登高（幷序）', '九日同羣僚登高（幷序）', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["淡蕩晴暉雜素光，碧峯遙襯白雲長。","好看塞雁歸南浦，宜聽砧聲搗夕陽。","滿野旌旗皆動色，千株橘柚盡含芳。","錦袍分賜功臣後，因向龍山醉羽觴。"]', '["淡蕩晴暉杂素光，碧峯遙襯白云长。","好看塞雁归南浦，宜听砧声捣夕陽。","满野旌旗皆动色，千株橘柚尽含芳。","錦袍分賜功臣後，因向龙山醉羽觴。"]', '诗', 'shi', '', NULL, '九日同羣僚登高（幷序） 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0527112d-9a30-4c9a-80ac-37806b06e453', '功臣堂（幷序）', '功臣堂（幷序）', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["今夕雖非豐沛酒，醪觥同醉洽吾鄉。","兩邦父老趨旌府，百品肴羞宴桂堂。","寶劍已頒王禮盛，錦衣重帶御爐香。","越王冊後封吳王，大國宣恩達萬方。"]', '["今夕雖非豐沛酒，醪觥同醉洽吾乡。","兩邦父老趨旌府，百品肴羞宴桂堂。","寶劍已頒王禮盛，錦衣重带御爐香。","越王冊後封吳王，大国宣恩達万方。"]', '诗', 'shi', '', NULL, '功臣堂（幷序） 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44120b02-b1fa-4f04-bba4-87957176791a', '上元夜次序平江南', '上元夜次序平江南', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["四朝雙母顯真封，古往今來事一同。"]', '["四朝雙母显真封，古往今来事一同。"]', '诗', 'shi', '', NULL, '上元夜次序平江南 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96cc8aa-23a4-4039-b2ec-d79ed3d45012', '西園產芝', '西园產芝', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["五紀尊天立霸基，八方隣國盡相知。","興吳定越崇王道，殄物平兇建國儀。","忽有靈根彰瑞應，皆由和氣感明祗。","休言漢代芝房異，今日吾邦事更奇。"]', '["五紀尊天立霸基，八方隣国尽相知。","兴吳定越崇王道，殄物平兇建国儀。","忽有靈根彰瑞應，皆由和氣感明祗。","休言漢代芝房異，今日吾邦事更奇。"]', '诗', 'shi', '', NULL, '西園產芝 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928c645e-7d70-4a4c-9463-679e38a130d8', '羅漢寺偶題', '羅漢寺偶題', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["九夏聽蟬吟，已知秋氣臨。","高梧上明月，深巷搗寒砧。","好對吳山秀，宜觀浙水深。","一登靈鷲閣，寶地勝黃金。","。"]', '["九夏听蟬吟，已知秋氣臨。","高梧上明月，深巷捣寒砧。","好对吳山秀，宜观浙水深。","一登靈鷲閣，寶地勝黄金。","。"]', '诗', 'shi', '', NULL, '羅漢寺偶題 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b344cce5-7ad3-4d97-87e9-89a5eeeabef9', '和高僧惠韻', '和高僧惠韻', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["嵐高照目前，山下有蒙泉。","雲閣連天際，銀河傍斗邊。","涼風宜散暑，清景好安禪。","況是江山固，崇墉保萬年。"]', '["嵐高照目前，山下有蒙泉。","云閣連天際，銀河傍斗邊。","涼风宜散暑，清景好安禪。","況是江山固，崇墉保万年。"]', '诗', 'shi', '', NULL, '和高僧惠韻 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0db9501-17b7-40c1-9a27-769596454bdb', '造寺保民', '造寺保民', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["百穀收成屆應鍾，南方景象喜重重。","三秋甘澤烟塵息，四序和風氣色濃。","播種勤耕盈廩庾，兆民興讓洽溫恭。","廣崇至道尊三教，蓋爲生靈奉聖容。"]', '["百穀收成屆應鍾，南方景象喜重重。","三秋甘澤烟塵息，四序和风氣色濃。","播種勤耕盈廩庾，兆民兴讓洽溫恭。","廣崇至道尊三教，蓋爲生靈奉聖容。"]', '诗', 'shi', '', NULL, '造寺保民 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4108e24a-b0c6-41bd-b1f3-f03cb0d22e91', '秋景', '秋景', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["三秋才到退炎光，二曜分暉照四方。","解使金風催物象，能教素節運清涼。","天垂甘澤朝朝降，地秀佳苗處處香。","率土吾民成富庶，虔誠稽顙荷穹蒼。"]', '["三秋才到退炎光，二曜分暉照四方。","解使金风催物象，能教素節運清涼。","天垂甘澤朝朝降，地秀佳苗处处香。","率土吾民成富庶，虔誠稽顙荷穹蒼。"]', '诗', 'shi', '', NULL, '秋景 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650757ea-0f32-46b5-bfb9-0875059ed242', '百花亭題梅二首 一', '百花亭題梅二首 一', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["穠華圍裡萬株梅，含蕊經霜待雪催。","莫訝玉顏無粉態，百花中最我先開。"]', '["穠华圍裡万株梅，含蕊經霜待雪催。","莫訝玉顏無粉態，百花中最我先开。"]', '诗', 'shi', '', NULL, '百花亭題梅二首 一 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdcf9092-5995-4e63-b617-3b1d9a2aae00', '百花亭題梅二首 二', '百花亭題梅二首 二', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["吳山越岫種寒梅，玉律含芳待候催。","爲應陽和呈雪貌，遊蜂難覺我先開。"]', '["吳山越岫種寒梅，玉律含芳待候催。","爲應陽和呈雪貌，游蜂难覺我先开。"]', '诗', 'shi', '', NULL, '百花亭題梅二首 二 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfefc5a-d533-4160-b3fe-fa193c89fcad', '和太師藴讓韻', '和太師藴讓韻', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["羅漢親崇建法臺，龍峯鳳嶺四山隈。","遊人借問禪門路，還道吳王爲佛開。"]', '["羅漢親崇建法台，龙峯鳳嶺四山隈。","游人借问禪门路，還道吳王爲佛开。"]', '诗', 'shi', '', NULL, '和太師藴讓韻 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177cf044-ae61-4880-8146-f5a2be14e321', '題羅隱壁', '題羅隐壁', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["特到儒門謁老萊，老萊相見意徘徊。","黃河信有澄清日，後代應難繼此才。","（以上《吳越錢氏傳芳集》）（〖1〗錢泳案：「《吳越備史》云：『隱寢疾，王親臨撫問。","因題其壁云：「黃河信有澄清日，後代應難繼此才。","」隱起而續末句云：「門外旌旗屯虎豹，壁間章句動風雷。","」由是以紅紗罩覆於其上。","』」）。"]', '["特到儒门謁老萊，老萊相见意徘徊。","黄河信有澄清日，後代應难繼此才。","（以上《吳越錢氏傳芳集》）（〖1〗錢泳案：「《吳越備史》云：『隐寢疾，王親臨撫问。","因題其壁云：「黄河信有澄清日，後代應难繼此才。","」隐起而續末句云：「门外旌旗屯虎豹，壁间章句动风雷。","」由是以紅紗罩覆於其上。","』」）。"]', '诗', 'shi', '', NULL, '題羅隱壁 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e71ea01-2f4b-4ce8-b320-26cdaf96f34d', '隱岳洞（在石城山，五代時有隱岳寺）', '隐岳洞（在石城山，五代时有隐岳寺）', '877437b6-387a-4543-b86a-b3b8c77ee162', '唐', '["百尺金容連翠岳，三層寶閣倚青霄。","手爐香暖申卑願，願降殊祥福帝堯。","（萬曆《新昌縣志》三）。"]', '["百尺金容連翠岳，三層寶閣倚青霄。","手爐香暖申卑願，願降殊祥福帝堯。","（万曆《新昌縣志》三）。"]', '诗', 'shi', '', NULL, '隱岳洞（在石城山，五代時有隱岳寺） 錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f279e1-5013-4d71-8acd-cb90d4193cb3', '送別十七哥', '送別十七哥', 'f1a0b890-faca-4395-805a-12ab3ca6ff08', '唐', '["大伯東陽軫舊思，士民襦袴喜迴時。","登臨若起鴒原念，八詠樓中寄小詩。"]', '["大伯东陽軫旧思，士民襦袴喜迴时。","登臨若起鴒原念，八詠楼中寄小诗。"]', '诗', 'shi', '', NULL, '送別十七哥 錢元瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c614ae1-2864-44f7-ab97-bbb73a67b6cf', '題得銅香爐（幷序）', '題得銅香爐（幷序）', 'f1a0b890-faca-4395-805a-12ab3ca6ff08', '唐', '["莫記年華隱水中，忽於此日覩靈蹤。","三天瑞氣標金相，五色龍光儼聖容。","節屆初秋興典教，時當千載慶遭逢。","仙冠羽服聲清曲，共引金臺入九重。","（以上《吳越錢氏傳芳集》）。"]', '["莫記年华隐水中，忽於此日覩靈蹤。","三天瑞氣標金相，五色龙光儼聖容。","節屆初秋兴典教，时當千載慶遭逢。","仙冠羽服声清曲，共引金台入九重。","（以上《吳越錢氏傳芳集》）。"]', '诗', 'shi', '', NULL, '題得銅香爐（幷序） 錢元瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7463cd5-fb19-4d4f-8bcf-0dd6534ad8a4', '佳辰小讌寄越州七弟湖州八弟', '佳辰小讌寄越州七弟湖州八弟', '888e96b7-a93b-44e0-a92e-25b74e60746e', '唐', '["角黍佳辰社稷寧，靈和開讌樂羣英。","樽前只少鴒原會，百里江城隔二城。"]', '["角黍佳辰社稷寧，靈和开讌乐羣英。","樽前只少鴒原會，百里江城隔二城。"]', '诗', 'shi', '', NULL, '佳辰小讌寄越州七弟湖州八弟 錢弘佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d741e6-0bf1-4ee8-bf42-fb6ceec1a41d', '謁寶塔回賜僧錄', '謁寶塔回賜僧錄', '888e96b7-a93b-44e0-a92e-25b74e60746e', '唐', '["佛日輝光最有靈，真身寶塔鎮吳城。","千尋獨拔乾坤聳，八面齊含日月明。","幾曲朱欄瞻海浪，長時金鐸振風聲。","禱祈祇願蒼生泰，更仗高僧法供精。","（以上《吳越錢氏傳芳集》）。"]', '["佛日輝光最有靈，真身寶塔鎮吳城。","千尋独拔乾坤聳，八面齊含日月明。","幾曲朱欄瞻海浪，长时金鐸振风声。","禱祈祇願蒼生泰，更仗高僧法供精。","（以上《吳越錢氏傳芳集》）。"]', '诗', 'shi', '', NULL, '謁寶塔回賜僧錄 錢弘佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6597ec9-307e-49cb-83a0-909e487216b5', '登臥龍山偶成', '登臥龙山偶成', '2b78879e-206d-4cb4-a019-cc85a27da52b', '唐', '["暮山重疊勢崔嵬，溢目清光入酒杯。","幾處燒殘紅樹短，一帆航盡碧波來。","安民未有移風術，徵句慚非夢錦才。","四望樓臺無限景，檻前贏得且徘徊。"]', '["暮山重叠勢崔嵬，溢目清光入酒杯。","幾处燒殘紅樹短，一帆航尽碧波来。","安民未有移风術，徵句慚非梦錦才。","四望楼台無限景，檻前贏得且徘徊。"]', '诗', 'shi', '', NULL, '登臥龍山偶成 錢弘倧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6545092-da89-4d42-8602-c2cb6ec377a5', '禹廟', '禹廟', '2b78879e-206d-4cb4-a019-cc85a27da52b', '唐', '["千古功勳孰可倫，東來靈宇壓乾坤。","塵埃共鏁梁猶在，星斗俱昏劍獨存。","蟾殿夜寒籠翠幌，麝爐春暖酹瓊樽。","會稽山水秋風裏，長放松聲入廟門。","（〖1〗北宋孔延之《會稽掇英總集》卷八收此詩，署「錢倧」，異文較多，錄如次：「功勳」作「英靈」，「東來」作「西來」，「靈宇」作「神宇」，「梁猶在」作「梅梁在」，「俱昏」作「俱分」，「劍獨存」作「劍韣存」，「籠翠幌」作「搖翠幌」，「山水」作「山下」。","《嘉泰會稽志》卷十二引「塵埃」二句，文字同《會稽掇英總集》。","）。"]', '["千古功勳孰可倫，东来靈宇壓乾坤。","塵埃共鏁梁猶在，星斗俱昏劍独存。","蟾殿夜寒籠翠幌，麝爐春暖酹瓊樽。","會稽山水秋风裏，长放松声入廟门。","（〖1〗北宋孔延之《會稽掇英總集》卷八收此诗，署「錢倧」，異文較多，錄如次：「功勳」作「英靈」，「东来」作「西来」，「靈宇」作「神宇」，「梁猶在」作「梅梁在」，「俱昏」作「俱分」，「劍独存」作「劍韣存」，「籠翠幌」作「搖翠幌」，「山水」作「山下」。","《嘉泰會稽志》卷十二引「塵埃」二句，文字同《會稽掇英總集》。","）。"]', '诗', 'shi', '', NULL, '禹廟 錢弘倧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b668b92d-2f47-442f-a249-3a8a3508b49c', '登蓬萊閣懷武肅王', '登蓬萊閣懷武肅王', '2b78879e-206d-4cb4-a019-cc85a27da52b', '唐', '["黃鶴摧殘漫有名，建時方始殄羅平。","飛㭿疊栱重裝束，刻檻雕甍又葺成。","十載興隆吳與越，二邦安肅弟兼兄。","從茲登賞雲樓上，願祝江南永宴清。"]', '["黄鹤摧殘漫有名，建时方始殄羅平。","飞㭿叠栱重裝束，刻檻雕甍又葺成。","十載兴隆吳與越，二邦安肅弟兼兄。","從茲登賞云楼上，願祝江南永宴清。"]', '诗', 'shi', '', NULL, '登蓬萊閣懷武肅王 錢弘倧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f69135-bc16-41c0-bb62-7d436cf3104b', '再遊聖母閣（《輿地紀勝》十《紹興府》詩摘第二聯題《遊天衣寺》）', '再游聖母閣（《輿地紀勝》十《紹兴府》诗摘第二聯題《游天衣寺》）', '2b78879e-206d-4cb4-a019-cc85a27da52b', '唐', '["越地靈蹤多少處，伽藍難上此樓臺。","有時風掣浪聲到，半夜月排山勢來。","極目烟嵐迷遠近，百般花木雕塵埃。","可憐光景吟無盡，知我登臨更幾迴。","（以上《吳越錢氏傳芳集》）（〖1〗《會稽掇英總集》卷八收此詩，署「錢倧」，題作《再遊應天寺聖母閣》。","第二句「難上」作「難尚」，第四句「山勢」作「山影」。","）。"]', '["越地靈蹤多少处，伽藍难上此楼台。","有时风掣浪声到，半夜月排山勢来。","極目烟嵐迷远近，百般花木雕塵埃。","可怜光景吟無尽，知我登臨更幾迴。","（以上《吳越錢氏傳芳集》）（〖1〗《會稽掇英總集》卷八收此诗，署「錢倧」，題作《再游應天寺聖母閣》。","第二句「难上」作「难尚」，第四句「山勢」作「山影」。","）。"]', '诗', 'shi', '', NULL, '再遊聖母閣（《輿地紀勝》十《紹興府》詩摘第二聯題《遊天衣寺》） 錢弘倧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e02be5-f9b8-4cae-943f-136061e8eadf', '飛英寺（句）', '飞英寺（句）', 'c9bbe4a7-a057-4518-aeab-4659e8484676', '唐', '["兩岸槿花紅障步，一行山色綠屏風。","（《輿地紀勝》四《安吉州·景物》）。"]', '["兩岸槿花紅障步，一行山色綠屏风。","（《輿地紀勝》四《安吉州·景物》）。"]', '诗', 'shi', '', NULL, '飛英寺（句） 錢弘偡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb266278-8c61-4c40-9c5f-e755caa3264f', '過平望', '過平望', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["風靜度長川，清吟倚畫船。","未分山有樹，惟見水連天。","沙嘴牛眠草，波心鳥觸烟。","宵征還有興，皎皎玉輪圓。"]', '["风静度长川，清吟倚畫船。","未分山有樹，惟见水連天。","沙嘴牛眠草，波心鸟觸烟。","宵征還有兴，皎皎玉輪圓。"]', '诗', 'shi', '', NULL, '過平望 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ac185f-a2c0-42a4-900b-4f25c27c3fe1', '讀聖壽詩', '读聖壽诗', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["功格皇天僞國平，八方臣妾盡來庭。","駿奔幸逐朝宗水，雀躍俄逢繞電星。","就日心雖懸紫闕，祝堯身尚處洪溟。","壽山聳峙將何願，泰華千霄萬仞青。"]', '["功格皇天僞国平，八方臣妾尽来庭。","駿奔幸逐朝宗水，雀躍俄逢繞電星。","就日心雖懸紫闕，祝堯身尚处洪溟。","壽山聳峙將何願，泰华千霄万仞青。"]', '诗', 'shi', '', NULL, '讀聖壽詩 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7819be29-d4d6-4f7c-a924-e02df47c0482', '感皇子遠降見迎', '感皇子远降见迎', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["千年遭遇覲真王，敢望青宮賜顯揚。","祇合承華趨令德，豈宜中道拜元良。","深思轉覺乾坤大，力弱難勝雨露滂。","早暮三思恩泰極，飽餐豐饌飽親光。"]', '["千年遭遇覲真王，敢望青宮賜显揚。","祇合承华趨令德，豈宜中道拜元良。","深思轉覺乾坤大，力弱难勝雨露滂。","早暮三思恩泰極，飽餐豐饌飽親光。"]', '诗', 'shi', '', NULL, '感皇子遠降見迎 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abc486a-e728-4043-8134-884836aeb8d9', '感降內夫人賜家室藥物金器', '感降內夫人賜家室藥物金器', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["魚軒相逐拜龍軒，聖主俄推望外恩。","錫寵便籓光石窌，內嬪迢遞下金門。","嵩衡壓地何曾重，雞犬昇仙未足論。","臣憨已平難展報，祇將忠孝訓兒孫。"]', '["鱼軒相逐拜龙軒，聖主俄推望外恩。","錫寵便籓光石窌，內嬪迢遞下金门。","嵩衡壓地何曾重，雞犬昇仙未足論。","臣憨已平难展報，祇將忠孝訓兒孫。"]', '诗', 'shi', '', NULL, '感降內夫人賜家室藥物金器 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28cbabb-e484-48b3-ada9-14c58dbe5446', '金陵', '金陵', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["不用論京口，先須問石頭。","虎山終自伏，帶水漫長遊。","青蓋曾彰讖，黃奴肯識羞。","分明前[鑒]（監）在，剛地弄戈矛。"]', '["不用論京口，先須问石头。","虎山終自伏，带水漫长游。","青蓋曾彰讖，黄奴肯識羞。","分明前[鑒]（監）在，剛地弄戈矛。"]', '诗', 'shi', '', NULL, '金陵 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744086e8-65c9-4eb7-9fa3-974a575fa3fc', '過楚州', '過楚州', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["駐馬楚城南，秋光帶雨寒。","地平無島嶼，淮近足波瀾。","聖德常柔遠，烝民賴此安。","行吟復行酌，朝野正多歡。"]', '["駐马楚城南，秋光带雨寒。","地平無島嶼，淮近足波瀾。","聖德常柔远，烝民賴此安。","行吟复行酌，朝野正多歡。"]', '诗', 'shi', '', NULL, '過楚州 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78049c7-deeb-4e09-8547-42bc923b7284', '陳國', '陳国', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["批破《陳書》後，都無禦敵心。","庭花春易盡，璧月夜難沉。","臣爵妖姬醉，新詩[狎]（狹）客吟。","江神如訪問，教到井中尋。","。"]', '["批破《陳书》後，都無禦敵心。","庭花春易尽，璧月夜难沉。","臣爵妖姬醉，新诗[狎]（狹）客吟。","江神如訪问，教到井中尋。","。"]', '诗', 'shi', '', NULL, '陳國 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4f9b92-5b0a-43ad-8b4a-5402f4279254', '路次再感聖恩', '路次再感聖恩', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["洪濤泛泛雨霏霏，芳草如茵柳裊絲。","貼水碧禽飛一字，隔烟青嶂展雙眉。","南風入隙開襟久，西照臨窗捲箔遲。","慚愧聖恩優渥異，不教炎暑冒長歧。"]', '["洪濤泛泛雨霏霏，芳草如茵柳裊絲。","貼水碧禽飞一字，隔烟青嶂展雙眉。","南风入隙开襟久，西照臨窗捲箔遲。","慚愧聖恩優渥異，不教炎暑冒长歧。"]', '诗', 'shi', '', NULL, '路次再感聖恩 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5003159d-ae63-4ed0-bacf-eb071892c3fa', '小窗', '小窗', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["粉雲牙貼小窗凉，坐見澄波泛夕陽。","更持夜深方有意，半環新月上重牀。"]', '["粉云牙貼小窗凉，坐见澄波泛夕陽。","更持夜深方有意，半环新月上重牀。"]', '诗', 'shi', '', NULL, '小窗 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0215121-c861-405b-a603-f8341fe9a177', '舟中偶書', '舟中偶书', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["輕舟畫舸枕江濱，眼底波濤日日新。","瞑目穩收雙足坐，不勞詢問醉禪人。"]', '["轻舟畫舸枕江濱，眼底波濤日日新。","瞑目穩收雙足坐，不勞詢问醉禪人。"]', '诗', 'shi', '', NULL, '舟中偶書 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f877aa-775b-4aba-9b5f-4ed0e90407a8', '村家', '村家', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["竹樹參差處，危牆獨木橫。","鋤開芳草色，放過遠灘聲。","稚子當門臥，雞雛上屋行。","騎牛帶簑笠。","侵曉雨中耕。"]', '["竹樹參差处，危牆独木橫。","鋤开芳草色，放過远灘声。","稚子當门臥，雞雛上屋行。","騎牛带簑笠。","侵晓雨中耕。"]', '诗', 'shi', '', NULL, '村家 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5b4c1c-d70e-4cd7-9e35-ecf920693055', '漁者', '漁者', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["罟網是生涯，柴扉隔水遮。","不辭粗俗氣，惟取大魚蝦。","貰酒方登陸，憐春亦種花。","等閑乘一葉，放曠入煙霞。","（以上《吳越錢氏傳芳集》）。"]', '["罟網是生涯，柴扉隔水遮。","不辞粗俗氣，惟取大鱼蝦。","貰酒方登陸，怜春亦種花。","等闲乘一葉，放曠入煙霞。","（以上《吳越錢氏傳芳集》）。"]', '诗', 'shi', '', NULL, '漁者 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c996b577-5da1-4f05-9f54-2c87ff9c8214', '追鮑約（侍郎鮑約，頗從臾忠懿王納土。及王歸宋，約竄處海上，王以詩追之曰〖見下〗。迄今有遐追廟焉。）', '追鲍約（侍郎鲍約，頗從臾忠懿王納土。及王归宋，約竄处海上，王以诗追之曰〖见下〗。迄今有遐追廟焉。）', '190b9fab-da50-40bd-a827-a085e38e7ff1', '唐', '["東遐追兮西遐追，鮑約何如罷釣歸。","（《五代詩話》六引《十國春秋》）（〖1〗見《十國春秋》卷八七《崔仁冀傳》附。","）。"]', '["东遐追兮西遐追，鲍約何如罷釣归。","（《五代诗話》六引《十国春秋》）（〖1〗见《十国春秋》卷八七《崔仁冀傳》附。","）。"]', '诗', 'shi', '', NULL, '追鮑約（侍郎鮑約，頗從臾忠懿王納土。及王歸宋，約竄處海上，王以詩追之曰〖見下〗。迄今有遐追廟焉。） 錢弘俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391f563f-599f-4560-8c29-e93e15285a83', '滕王閣', '滕王閣', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["[江神]有意憐才子，歘忽威靈助去程。","一席清風雷電疾，滿碑佳句雪冰清。","煥然麗藻傳千古，赫爾英名動兩京。","若匪幽冥[祐詞]客，至今佳景絕無聲。","（《歲時廣記》三五《重九》）（〖1〗據《醒世恒言》卷四十《馬當神風送滕王閣》補缺文。","《醒世恒言》錄此詩，前四句除「一席」作「一夕」外，餘全同。","後四句改動稍多，錄如次：「直教麗藻傳千古，不但雄名動兩京。","不是明靈祐祠客，洪都佳景絕無聲。","」「祠客」顯爲「詞客」之誤。","）。"]', '["[江神]有意怜才子，歘忽威靈助去程。","一席清风雷電疾，满碑佳句雪冰清。","煥然丽藻傳千古，赫爾英名动兩京。","若匪幽冥[祐词]客，至今佳景絕無声。","（《歲时廣記》三五《重九》）（〖1〗據《醒世恒言》卷四十《马當神风送滕王閣》補缺文。","《醒世恒言》錄此诗，前四句除「一席」作「一夕」外，餘全同。","後四句改动稍多，錄如次：「直教丽藻傳千古，不但雄名动兩京。","不是明靈祐祠客，洪都佳景絕無声。","」「祠客」显爲「词客」之誤。","）。"]', '诗', 'shi', '', NULL, '滕王閣 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc80c591-cb60-498e-bc82-148f69e89a80', '文選閣（在貴池城西五里西廟。貯梁昭明文選。有址）', '文選閣（在貴池城西五里西廟。貯梁昭明文選。有址）', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["間生元子出蕭梁，作選爲書化萬邦。","三代已來成冠絕，六朝餘外更無雙。","今朝集是羣英仰，昨日談非衆耻降。","輔國安民新試閣，滕王空作問臨江。","（《嘉靖池州府志》卷三《建置篇·宮室》）。"]', '["间生元子出蕭梁，作選爲书化万邦。","三代已来成冠絕，六朝餘外更無雙。","今朝集是羣英仰，昨日談非衆耻降。","輔国安民新試閣，滕王空作问臨江。","（《嘉靖池州府志》卷三《建置篇·宮室》）。"]', '诗', 'shi', '', NULL, '文選閣（在貴池城西五里西廟。貯梁昭明文選。有址） 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6867e10a-633d-4a34-b30d-6c5e813b3a03', '昭明太子廟', '昭明太子廟', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["秋浦昭明廟，乾坤一白眉。","神通高學識，天下鬼神師。","（同上卷五《祀典篇·廟祠》）。"]', '["秋浦昭明廟，乾坤一白眉。","神通高学識，天下鬼神師。","（同上卷五《祀典篇·廟祠》）。"]', '诗', 'shi', '', NULL, '昭明太子廟 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53e89a1-2c4e-46bb-954c-af5aae4dbe38', '下山過梅根', '下山過梅根', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["岸葉經秋墜晚枝，裊烟凌鬢促征期。","家從澤國誰能問，路在侯門自不知。","但恐老侵多病日，每憂忙過少年時。","可憐江上人堪笑，獨倚殘陽弄釣絲。","（同上卷八《雜著篇·藝文》）。"]', '["岸葉經秋墜晚枝，裊烟凌鬢促征期。","家從澤国誰能问，路在侯门自不知。","但恐老侵多病日，每憂忙過少年时。","可怜江上人堪笑，独倚殘陽弄釣絲。","（同上卷八《杂著篇·藝文》）。"]', '诗', 'shi', '', NULL, '下山過梅根 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a781e6c3-d9d7-46c0-a4be-92076b9eac7c', '金雞石（在東流縣南二十五里。相傳羅隱道經其地，題云云，石遂迸裂，鷄飛鳴而去。或曰：隱題後，其石震雷劈焉。）', '金雞石（在东流縣南二十五里。相傳羅隐道經其地，題云云，石遂迸裂，鷄飞鳴而去。或曰：隐題後，其石震雷劈焉。）', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["青山隱隱望長溪，獨墩無伴只孤棲。","草堂不見婁羅漢，金雞不向五更啼。","（同上卷一）。"]', '["青山隐隐望长溪，独墩無伴只孤棲。","草堂不见婁羅漢，金雞不向五更啼。","（同上卷一）。"]', '诗', 'shi', '', NULL, '金雞石（在東流縣南二十五里。相傳羅隱道經其地，題云云，石遂迸裂，鷄飛鳴而去。或曰：隱題後，其石震雷劈焉。） 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d6b716-6334-4f94-bfb6-6d04e523e0f4', '掛劍處', '掛劍处', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["忠貞者必信，所信交道深。","賢哉吳季子，可稱莫逆心。","（《梅里志》三）。"]', '["忠貞者必信，所信交道深。","賢哉吳季子，可稱莫逆心。","（《梅里志》三）。"]', '诗', 'shi', '', NULL, '掛劍處 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2de76c6-1319-4af4-b463-285c15204e08', '題延和閣（《全唐詩》八七五作讖記，詩題、小序、詩多有不同，故重錄）（時高駢欲繼淮南王求仙方爲妖亂，後爲畢將軍所害。隱作《妖亂誌》以譏之，故有《題延和閣》云。）', '題延和閣（《全唐诗》八七五作讖記，诗題、小序、诗多有不同，故重錄）（时高駢欲繼淮南王求仙方爲妖亂，後爲畢將軍所害。隐作《妖亂誌》以譏之，故有《題延和閣》云。）', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["延和高閣勢凌雲，輕語猶疑太一聞。","燒盡餘香無一事，開門迎得畢將軍。","（《詩話總龜》三五《譏誚門》引《鑑誡錄》）。"]', '["延和高閣勢凌云，轻語猶疑太一闻。","燒尽餘香無一事，开门迎得畢將軍。","（《诗話總龟》三五《譏誚门》引《鑑誡錄》）。"]', '诗', 'shi', '', NULL, '題延和閣（《全唐詩》八七五作讖記，詩題、小序、詩多有不同，故重錄）（時高駢欲繼淮南王求仙方爲妖亂，後爲畢將軍所害。隱作《妖亂誌》以譏之，故有《題延和閣》云。） 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9690d6-ba05-45ef-b695-e8de3e429ed9', '上亭驛（在梓潼武連二縣之界。唐明皇幸蜀。聞鈴聲之地。又名琅璫驛）', '上亭驛（在梓潼武連二縣之界。唐明皇幸蜀。闻鈴声之地。又名琅璫驛）', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["山雨霏微宿上亭，雨中因想雨淋鈴。","貴爲天子猶魂斷，窮著荷衣好涕零。","（《輿地紀勝》一八六《隆慶府》。","《全唐詩》六六五引《天中記》只存前二句）（〖1〗《碧雞漫志》卷五收此詩全篇，爲七律，詳《全唐詩續拾》卷四五。","）。"]', '["山雨霏微宿上亭，雨中因想雨淋鈴。","貴爲天子猶魂斷，窮著荷衣好涕零。","（《輿地紀勝》一八六《隆慶府》。","《全唐诗》六六五引《天中記》只存前二句）（〖1〗《碧雞漫志》卷五收此诗全篇，爲七律，詳《全唐诗續拾》卷四五。","）。"]', '诗', 'shi', '', NULL, '上亭驛（在梓潼武連二縣之界。唐明皇幸蜀。聞鈴聲之地。又名琅璫驛） 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeed1ae1-7960-4307-b40e-bf2e5799f3d7', '', '', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2516a2d1-22a8-4aea-a2df-fa03ae26913b', '賦台州早春（句）', '賦台州早春（句）', 'e6053b0b-9357-46ac-916f-8882db143ad0', '唐', '["豈堪滄海畔，爲客十年來。","（《輿地紀勝》十二《台州》）（〖1〗《天台前集》存此詩全篇，詳《全唐詩續拾》卷三十五。","）。"]', '["豈堪滄海畔，爲客十年来。","（《輿地紀勝》十二《台州》）（〖1〗《天台前集》存此诗全篇，詳《全唐诗續拾》卷三十五。","）。"]', '诗', 'shi', '', NULL, '賦台州早春（句） 任翻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77eedb79-5fc0-4971-a6bc-3adb5ad4712c', '詠志（《全唐詩》七九五只存前二句）', '詠志（《全唐诗》七九五只存前二句）', '5cba999f-4509-47a7-84c9-11578c2eb96c', '唐', '["輕身都是義，殉主始爲忠。","一夜西陵路，朱旗走大風。","（《全五代詩》七三引《槜李詩繫》）（〖1〗此說未允。","《全唐文》卷八九八收皮光業《屠將軍墓誌銘》、《十國春秋》卷八四皆作屠瓌智。","〖2〗見《槜李詩繫》卷一，作者作屠瓌智。","）。"]', '["轻身都是義，殉主始爲忠。","一夜西陵路，朱旗走大风。","（《全五代诗》七三引《槜李诗繫》）（〖1〗此说未允。","《全唐文》卷八九八收皮光業《屠將軍墓誌銘》、《十国春秋》卷八四皆作屠瓌智。","〖2〗见《槜李诗繫》卷一，作者作屠瓌智。","）。"]', '诗', 'shi', '', NULL, '詠志（《全唐詩》七九五只存前二句） 屠環智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ac821d-d48f-4b81-aac3-b1d9b0f17c0a', '題常樂菴五雲堂（常樂菴在崇德縣西八十步。梁步監二年建。俗呼西寺。後入宋改悟空院。吳越時韋謙詩云云。）', '題常乐菴五云堂（常乐菴在崇德縣西八十步。梁步監二年建。俗呼西寺。後入宋改悟空院。吳越时韋謙诗云云。）', 'ad98bf5c-7618-4e8b-b21c-80a6abf4191a', '唐', '["吾匠慕先哲，至理皆融通。","一法果有至，五雲疑在空。","講香浸棐几，夜月鎖簾櫳。","弋者何由預，冥冥出塞鴻。","（同上）（〖1〗《至元嘉禾志》卷三二收此詩，署「節度韋謙」。","又見《槜李詩繫》卷三七。","）。"]', '["吾匠慕先哲，至理皆融通。","一法果有至，五云疑在空。","講香浸棐几，夜月鎖簾櫳。","弋者何由預，冥冥出塞鴻。","（同上）（〖1〗《至元嘉禾志》卷三二收此诗，署「節度韋謙」。","又见《槜李诗繫》卷三七。","）。"]', '诗', 'shi', '', NULL, '題常樂菴五雲堂（常樂菴在崇德縣西八十步。梁步監二年建。俗呼西寺。後入宋改悟空院。吳越時韋謙詩云云。） 韋謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f36615-f1d9-4cf7-b26b-3c85bf245a20', '下獄有作', '下獄有作', '3003dba5-543e-4010-a9ed-a18ae69e5b0d', '唐', '["按則增科不自由，未曾舉筆淚先流。","高田沙瘦常憂旱，沿海塗鹹少有秋。","要使繭絲殫地力，願將骨肉伴枷頭。","一時種了黃連種，萬代令人苦不休。","（《古今圖書集成·食貨典》一五三《賦役部》）（〖1〗《十國春秋》卷八五：「陳長官，事武肅王爲寧海縣令。","會王命增州縣賦稅，長官上書極諫，王大怒，逮之獄。","長官以死爭之，得免。","寧海故稱劇縣，租稅視諸邑爲獨輕者，皆其力也，至今猶廟祀焉。","」與其詩相合。","原收「無世次」卷，今移入本卷。","）。"]', '["按則增科不自由，未曾舉笔泪先流。","高田沙瘦常憂旱，沿海塗鹹少有秋。","要使繭絲殫地力，願將骨肉伴枷头。","一时種了黄連種，万代令人苦不休。","（《古今圖书集成·食貨典》一五三《賦役部》）（〖1〗《十国春秋》卷八五：「陳长官，事武肅王爲寧海縣令。","會王命增州縣賦稅，长官上书極諫，王大怒，逮之獄。","长官以死爭之，得免。","寧海故稱劇縣，租稅視諸邑爲独轻者，皆其力也，至今猶廟祀焉。","」與其诗相合。","原收「無世次」卷，今移入本卷。","）。"]', '诗', 'shi', '', NULL, '下獄有作 陳長官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e639d2-fae5-42c1-8464-e1ebb2a9123a', '評僧道二門論難', '評僧道二门論难', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["玄門清淨等空門，虔奉天尊與世尊。","金口說經十二部，玉皇留教五千言。","鼇頭宮殿波瀾闊，鷲嶺香花夢相存。","莫向人間爭勝負，須知三教本同源。","（《鑑誡錄》六《旌論衡》）。"]', '["玄门清淨等空门，虔奉天尊與世尊。","金口说經十二部，玉皇留教五千言。","鼇头宮殿波瀾闊，鷲嶺香花梦相存。","莫向人间爭勝負，須知三教本同源。","（《鑑誡錄》六《旌論衡》）。"]', '诗', 'shi', '', NULL, '評僧道二門論難 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b82d16-1292-44f7-90e9-030cddc25aca', '刺賈島', '刺賈島', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["少年爲理但公清，鴻漸行中是去程。","莫恨長江爲短簿，可能勝得賈先生？","（《鑑誡錄》八《賈忤旨》）（〖1〗《鑑誡錄》云：「後有一少年除長江簿，猶豫不赴，張蠙先輩爲詩刺之。","」此處所擬詩題不允，應作「刺少年」。","）。"]', '["少年爲理但公清，鴻漸行中是去程。","莫恨长江爲短簿，可能勝得賈先生？","（《鑑誡錄》八《賈忤旨》）（〖1〗《鑑誡錄》云：「後有一少年除长江簿，猶豫不赴，張蠙先輩爲诗刺之。","」此处所擬诗題不允，應作「刺少年」。","）。"]', '诗', 'shi', '', NULL, '刺賈島 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402ba9b4-8764-45c6-8ce9-cc89b519a9bd', '弔孟浩然（後二句）', '弔孟浩然（後二句）', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["漢水醉時波尚綠，鹿門吟處草猶生。","（《輿地紀勝》八二《襄陽府》）（今按：《全唐詩》七一五引《海錄碎事》，另有「高據襄陽播盛名，問人人道是詩星」二句，正可合爲一首。","此二聯格律不粘。","疑原詩爲七律，今僅存二聯。","）。"]', '["漢水醉时波尚綠，鹿门吟处草猶生。","（《輿地紀勝》八二《襄陽府》）（今按：《全唐诗》七一五引《海錄碎事》，另有「高據襄陽播盛名，问人人道是诗星」二句，正可合爲一首。","此二聯格律不粘。","疑原诗爲七律，今僅存二聯。","）。"]', '诗', 'shi', '', NULL, '弔孟浩然（後二句） 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f25790-0eb4-41e1-861e-fcf5e124ea89', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 一', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作诗云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 一', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["狐衝官道過，犬刺客門開（一作「狗判店門開」）。","〖3〗。"]', '["狐衝官道過，犬刺客门开（一作「狗判店门开」）。","〖3〗。"]', '诗', 'shi', '', NULL, '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 一 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe5f4d5-0d7b-41c2-a122-7fdcc3cfaabb', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 二', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作诗云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 二', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["餓猫臨鼠穴，饞犬舐魚砧。"]', '["餓猫臨鼠穴，饞犬舐鱼砧。"]', '诗', 'shi', '', NULL, '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 二 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf7588f-bae4-41b5-8349-4d593f4a92ae', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 三', '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作诗云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 三', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["栗爆燒氊破，猫跳觸鼎翻。","（《北夢瑣言》七、《詩話總龜》三九《詼諧門》。","參見同書八《評論門》引《談苑》）（〖1〗《懷江上》之題，僅見《談苑》引，爲「餓猫」二句之題，另二聯題未詳。","〖2〗五舉，《北夢瑣言》作「二十五舉」。","〖3〗「犬刺」，《北夢瑣言》作「狗觸」。","）。"]', '["栗爆燒氊破，猫跳觸鼎翻。","（《北梦瑣言》七、《诗話總龟》三九《詼諧门》。","參见同书八《評論门》引《談苑》）（〖1〗《懷江上》之題，僅见《談苑》引，爲「餓猫」二句之題，另二聯題未詳。","〖2〗五舉，《北梦瑣言》作「二十五舉」。","〖3〗「犬刺」，《北梦瑣言》作「狗觸」。","）。"]', '诗', 'shi', '', NULL, '懷江上（句）（盧延遜五舉方登第。〖2〗嘗作詩云。「狐衝」二句，租庸張相濬每誦之。又「餓猫」二句，成中令汭激賞之。又「栗爆」二句，王中懿建愛之。盧嘗謂人曰：「平生投謁公卿，不意得猫兒狗子之力也。」） 三 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bf3631-41cc-4fb8-8773-4f5f5c30866c', '詠白鹽山（許太尉宗憲鎮寧江日，辟劉隱辭爲節度掌書記。宗憲武人，多爲恣橫，隱辭諫不聽。遂詠《白鹽山》、《灧澦堆》詩刺之云云。宗憲聞而發怒，將殺之。已而舍之，遂遁去。）', '詠白鹽山（許太尉宗憲鎮寧江日，辟劉隐辞爲節度掌书記。宗憲武人，多爲恣橫，隐辞諫不听。遂詠《白鹽山》、《灧澦堆》诗刺之云云。宗憲闻而發怒，將殺之。已而舍之，遂遁去。）', '036d9e37-5cd8-4b23-b77b-76aaedefc8f8', '唐', '["占斷瞿塘一峽煙，危峯迥出衆峯前。","都緣頑梗揎浮世，遮莫崢嶸倚半天。","有樹只知引（一作栖）鳥雀，無雲不易駐神仙。","假饒突兀高千丈，爭及平平數畝田。"]', '["占斷瞿塘一峽煙，危峯迥出衆峯前。","都緣頑梗揎浮世，遮莫崢嶸倚半天。","有樹只知引（一作栖）鸟雀，無云不易駐神仙。","假饒突兀高千丈，爭及平平數畝田。"]', '诗', 'shi', '', NULL, '詠白鹽山（許太尉宗憲鎮寧江日，辟劉隱辭爲節度掌書記。宗憲武人，多爲恣橫，隱辭諫不聽。遂詠《白鹽山》、《灧澦堆》詩刺之云云。宗憲聞而發怒，將殺之。已而舍之，遂遁去。） 劉隱辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd30de89-48ec-4580-b3a5-e6e33b2d58aa', '詠灧澦堆', '詠灧澦堆', '036d9e37-5cd8-4b23-b77b-76aaedefc8f8', '唐', '["灧澦崔嵬百萬秋，年年出沒幾時休。","未容寸土生纖草，能向當江覆巨舟。","無事便騰千尺浪，與人長作一堆愁。","都緣不似蟠溪石，難使漁翁下釣鈎。","（以上《鑑誡錄》五《因詩辱》）。"]', '["灧澦崔嵬百万秋，年年出沒幾时休。","未容寸土生纖草，能向當江覆巨舟。","無事便腾千尺浪，與人长作一堆愁。","都緣不似蟠溪石，难使漁翁下釣鈎。","（以上《鑑誡錄》五《因诗辱》）。"]', '诗', 'shi', '', NULL, '詠灧澦堆 劉隱辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c77182-2e5a-4253-b59e-e202f123702f', '詠僧道二門論難', '詠僧道二门論难', '036d9e37-5cd8-4b23-b77b-76aaedefc8f8', '唐', '["爲僧爲道兩悠悠，若箇能分聖主憂。","各鬬輪蹄朝紫殿，競稱卿監滿皇州。","相嘲相詠何時了，爭利爭名早晚休。","閑想邊庭荷戈將，功成猶自不封侯。","（同上六《旌論衡》）。"]', '["爲僧爲道兩悠悠，若箇能分聖主憂。","各鬬輪蹄朝紫殿，競稱卿監满皇州。","相嘲相詠何时了，爭利爭名早晚休。","闲想邊庭荷戈將，功成猶自不封侯。","（同上六《旌論衡》）。"]', '诗', 'shi', '', NULL, '詠僧道二門論難 劉隱辭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0596b2c-59df-4a45-a331-076726b15dfd', '題九頭鳥', '題九头鸟', '3d17872c-1213-4aa8-90ff-1aa0c4aac566', '唐', '["三百禽中爾最靈，就中惡爾九頭名。","數年雲外藏兇影，此夜天邊發差聲。","好惜羽毛還鬼窟，莫留災害與蒼生。","况當社稷延洪日，不合鳴時莫亂鳴。","（《鑑誡錄》六《怪鳥應》）。"]', '["三百禽中爾最靈，就中惡爾九头名。","數年云外藏兇影，此夜天邊發差声。","好惜羽毛還鬼窟，莫留災害與蒼生。","况當社稷延洪日，不合鳴时莫亂鳴。","（《鑑誡錄》六《怪鸟應》）。"]', '诗', 'shi', '', NULL, '題九頭鳥 楊義方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935c91c1-fc5c-4528-a5c0-73b0741b87e7', '生日歌（略）（太祖爲蜀王時，方搆大業，莫不賦輿〖一作「役」〗增益，轉運煩苛，百姓困窮，無敢言者。因太祖生辰，涓獨獻一歌，先紀王功，後陳生聚〖一作「衆困」〗。太祖曰：「如卿忠讜，寡人王業何憂。」遂賜黃金十斤，以旌禮諷諫，於是徭役稍減矣。議者以君臣道合，黎庶泰來，苟非明王，何以采納。《生日歌》略云：）', '生日歌（略）（太祖爲蜀王时，方搆大業，莫不賦輿〖一作「役」〗增益，轉運煩苛，百姓困窮，無敢言者。因太祖生辰，涓独獻一歌，先紀王功，後陳生聚〖一作「衆困」〗。太祖曰：「如卿忠讜，寡人王業何憂。」遂賜黄金十斤，以旌禮諷諫，於是徭役稍減矣。議者以君臣道合，黎庶泰来，苟非明王，何以采納。《生日歌》略云：）', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["百姓富，軍食足，百姓足，軍民歡。","爭那生靈饑且寒，吾王有術應不難。","但令一斗徵一斗，自然百姓富於官。"]', '["百姓富，軍食足，百姓足，軍民歡。","爭那生靈饑且寒，吾王有術應不难。","但令一斗徵一斗，自然百姓富於官。"]', '诗', 'shi', '', NULL, '生日歌（略）（太祖爲蜀王時，方搆大業，莫不賦輿〖一作「役」〗增益，轉運煩苛，百姓困窮，無敢言者。因太祖生辰，涓獨獻一歌，先紀王功，後陳生聚〖一作「衆困」〗。太祖曰：「如卿忠讜，寡人王業何憂。」遂賜黃金十斤，以旌禮諷諫，於是徭役稍減矣。議者以君臣道合，黎庶泰來，苟非明王，何以采納。《生日歌》略云：） 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8824c24-1230-4620-9356-a2c13dec6b57', '嶮竿歌', '嶮竿歌', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["山嶮驚摧車，水嶮怕覆舟。","奈何平地不肯立，沿上百尺高竿頭。","我不知爾是人耶猿耶復猱耶，教我見爾爲爾長嘆嗟。","我聞孝子不許國，我聞忠臣不憂家。","爾即輕命重黃金，忠孝全虧徒爾誇。","常將嶮藝悅君目，終日貪心媚君祿。","百尺高竿百度沿，一足參差一家哭。","嶮竿兒，聽我語，更有嶮竿嶮於汝。","解從上處失君恩，落向天涯海邊去。","嶮竿兒，爾須知，嶮處欲往宜爾思。","上得欲下下不得，我謂此輩嶮於嶮竿兒。"]', '["山嶮驚摧车，水嶮怕覆舟。","奈何平地不肯立，沿上百尺高竿头。","我不知爾是人耶猿耶复猱耶，教我见爾爲爾长嘆嗟。","我闻孝子不許国，我闻忠臣不憂家。","爾即轻命重黄金，忠孝全虧徒爾誇。","常將嶮藝悅君目，終日貪心媚君祿。","百尺高竿百度沿，一足參差一家哭。","嶮竿兒，听我語，更有嶮竿嶮於汝。","解從上处失君恩，落向天涯海邊去。","嶮竿兒，爾須知，嶮处欲往宜爾思。","上得欲下下不得，我謂此輩嶮於嶮竿兒。"]', '诗', 'shi', '', NULL, '嶮竿歌 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8af2e7d-618b-4d06-907a-b71dbee36706', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：）', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：）', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2861ea4e-d14d-4775-b809-96f652d6bf59', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 一', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 一', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["樂樂樂，冷淘似餺飥。","（涓曰云云，合座大咍，涓獨不笑，但仰視長嘯而已。","）。"]', '["乐乐乐，冷淘似餺飥。","（涓曰云云，合座大咍，涓独不笑，但仰視长嘯而已。","）。"]', '诗', 'shi', '', NULL, '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 一 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8afe28-3633-4b20-b7f4-c0eb82c17898', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 二', '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 二', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["巳巳巳，驢糞似馬屎。","（以上《鑑誡錄》四《輕薄鑑》）。"]', '["巳巳巳，驢糞似马屎。","（以上《鑑誡錄》四《轻薄鑑》）。"]', '诗', 'shi', '', NULL, '酒令（涓與王司空鍇等小酌，巡故字令。鍇舉一字三呼，兩物相似。鍇令曰：） 二 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0913e981-1006-4dda-89bd-1f1aa60037f2', '嘲李珣（賓貢李珣，字德潤，本蜀中土生波斯也。少小苦心，屢稱賓貢，所吟詩句，往往動人。尹校書鶚者，錦城煙月之士，與李生常爲善友。遽因戲遇嘲之，李生文章，掃地而盡。詩曰：）', '嘲李珣（賓貢李珣，字德潤，本蜀中土生波斯也。少小苦心，屢稱賓貢，所吟诗句，往往动人。尹校书鶚者，錦城煙月之士，與李生常爲善友。遽因戲遇嘲之，李生文章，掃地而尽。诗曰：）', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["異域從來不亂常，李波斯強學文章。","假饒折得東堂桂，胡臭薰來也不香。","（《鑑誡錄》四《斥亂常》）。"]', '["異域從来不亂常，李波斯強学文章。","假饒折得东堂桂，胡臭薰来也不香。","（《鑑誡錄》四《斥亂常》）。"]', '诗', 'shi', '', NULL, '嘲李珣（賓貢李珣，字德潤，本蜀中土生波斯也。少小苦心，屢稱賓貢，所吟詩句，往往動人。尹校書鶚者，錦城煙月之士，與李生常爲善友。遽因戲遇嘲之，李生文章，掃地而盡。詩曰：） 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ba6404-ba90-487f-8cf4-9d880cc5ddd0', '詠渾家樂（二首） 一', '詠渾家乐（二首） 一', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["晨起梳頭午不休，一窠精魅鬧啾啾。","阿家解舞《清平樂》，新婦能拋白木毬。","著綠桃牌吹觱篥，賜緋盟器和《梁州》。","天明任你渾家樂，雨下還須滿舍愁。"]', '["晨起梳头午不休，一窠精魅鬧啾啾。","阿家解舞《清平乐》，新婦能拋白木毬。","著綠桃牌吹觱篥，賜緋盟器和《梁州》。","天明任你渾家乐，雨下還須满舍愁。"]', '诗', 'shi', '', NULL, '詠渾家樂（二首） 一 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e89beae-77ea-46b5-a913-3370c3beafaa', '詠渾家樂（二首） 二', '詠渾家乐（二首） 二', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["北郡南州處處過，平生家計一驢獁。","囊中錢物衣裝少，袋裏燕脂胡粉多。","滿子面甜糖餅，蕭娘身瘦鬼常娥。","怪來喚作渾家樂，骨子貓兒盡唱歌。"]', '["北郡南州处处過，平生家計一驢獁。","囊中錢物衣裝少，袋裏燕脂胡粉多。","满子面甜糖餅，蕭娘身瘦鬼常娥。","怪来喚作渾家乐，骨子貓兒尽唱歌。"]', '诗', 'shi', '', NULL, '詠渾家樂（二首） 二 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ed4761-6939-47c6-8ef5-a690e90aec15', '過舊居', '過旧居', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["昔日顏回宅，今爲裹飯家。","不聞吟秀句，只見𫗕（一作餔）油麻。","豉汁鍋中沸，粕餻案上葩（一作爬）。","朝朝唯早起，檐從自排衙。"]', '["昔日顏回宅，今爲裹飯家。","不闻吟秀句，只见𫗕（一作餔）油麻。","豉汁鍋中沸，粕餻案上葩（一作爬）。","朝朝唯早起，檐從自排衙。"]', '诗', 'shi', '', NULL, '過舊居 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffa0995-729e-4758-bd66-09a6d39b8da8', '有一秀才忽贖酒家青衣爲婦（一作活）因嘲之', '有一秀才忽贖酒家青衣爲婦（一作活）因嘲之', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["秀才何事太怱怱，琴瑟無媒便自通。","新婦旋裙纔離體，外姑托布尚當胸。","菜團箇箇皆鉗項，粳米頭頭盡翦鬃。","一自土和逃走後，至今失却親家翁。"]', '["秀才何事太怱怱，琴瑟無媒便自通。","新婦旋裙纔離體，外姑托布尚當胸。","菜團箇箇皆鉗項，粳米头头尽翦鬃。","一自土和逃走後，至今失却親家翁。"]', '诗', 'shi', '', NULL, '有一秀才忽贖酒家青衣爲婦（一作活）因嘲之 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0788381-649d-4d28-814f-f448f3cfef9a', '詠大慈寺齋頭鮮于闍梨', '詠大慈寺斋头鲜于闍梨', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["酒肉終朝沒闕時，高堂大舍養肥屍。","行婆滿院多爲婦，童子成行半是兒。","面折掇齋窮措大，笑迎搽粉阿尼師。","一朝若也無常至，劍樹刀山不放伊。"]', '["酒肉終朝沒闕时，高堂大舍養肥屍。","行婆满院多爲婦，童子成行半是兒。","面折掇斋窮措大，笑迎搽粉阿尼師。","一朝若也無常至，劍樹刀山不放伊。"]', '诗', 'shi', '', NULL, '詠大慈寺齋頭鮮于闍梨 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e360b6-93ac-4aef-9a8d-01444b144191', '放生池（大慈寺東北有池，號曰放生池。蜀人競以三元日，多將鵝鴨放在池中。裕因謁主池僧不遇，當門書一絕句，自此放生稍息矣。）', '放生池（大慈寺东北有池，號曰放生池。蜀人競以三元日，多將鵝鴨放在池中。裕因謁主池僧不遇，當门书一絕句，自此放生稍息矣。）', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["鵝鴨同羣世所知，蜀人競送放生池。","比來養狗圖雞在，不那闍梨是野貍。"]', '["鵝鴨同羣世所知，蜀人競送放生池。","比来養狗圖雞在，不那闍梨是野貍。"]', '诗', 'shi', '', NULL, '放生池（大慈寺東北有池，號曰放生池。蜀人競以三元日，多將鵝鴨放在池中。裕因謁主池僧不遇，當門書一絕句，自此放生稍息矣。） 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0e6666-f0c9-4990-902e-c17f2f4219a2', '詠深沙（裕後詠深沙一絕，因暴疾而終，亦由神折天年，抑又神其靈也。詩曰：）', '詠深沙（裕後詠深沙一絕，因暴疾而終，亦由神折天年，抑又神其靈也。诗曰：）', '7d24b3e7-08cd-4516-b20c-a441d5ec59f5', '唐', '["瞋（一作「橫」）眉努目強乾嗔，便作閻浮有力神。","禍福豈由泥擔漢，燒香供養弄蛇人。","（以上《鑑誡錄》十《攻雜詠》）。"]', '["瞋（一作「橫」）眉努目強乾嗔，便作閻浮有力神。","禍福豈由泥擔漢，燒香供養弄蛇人。","（以上《鑑誡錄》十《攻杂詠》）。"]', '诗', 'shi', '', NULL, '詠深沙（裕後詠深沙一絕，因暴疾而終，亦由神折天年，抑又神其靈也。詩曰：） 陳裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7faa0441-f74a-466c-9fc7-2bba55d975cd', '題驛門（禹卿會後主東遊，上表極諫，及後主被誅，禹卿痛哭，題詩于驛門而遁。雍守捕之，禹卿已還蜀矣。）', '題驛门（禹卿會後主东游，上表極諫，及後主被誅，禹卿痛哭，題诗于驛门而遁。雍守捕之，禹卿已還蜀矣。）', '61a97c1d-f3a9-4b99-b234-71b166d99404', '唐', '["我王銜璧遠稱臣，何事全家幷殺身。","漢捨子嬰名尚在，魏封劉禪事獨新。","非干大國渾無識，都是中原未有人。","獨向長安儘惆悵，力微何路報君親。","（《鑑誡錄》七《陪臣諫》）。"]', '["我王銜璧远稱臣，何事全家幷殺身。","漢捨子嬰名尚在，魏封劉禪事独新。","非干大国渾無識，都是中原未有人。","独向长安儘惆悵，力微何路報君親。","（《鑑誡錄》七《陪臣諫》）。"]', '诗', 'shi', '', NULL, '題驛門（禹卿會後主東遊，上表極諫，及後主被誅，禹卿痛哭，題詩于驛門而遁。雍守捕之，禹卿已還蜀矣。） 蒲禹卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc222fb-8023-4115-8655-3364ea89cd81', '寄弟詩（唐末，盧拾遺議與鄭中舍延休作贅，三年不歸陝下。其兄誥以詩讓之，詩意甚乖昆仲之禮。盧議呈其太山中舍，幷女遣之。誥寄弟詩曰：）', '寄弟诗（唐末，盧拾遺議與鄭中舍延休作贅，三年不归陝下。其兄誥以诗讓之，诗意甚乖昆仲之禮。盧議呈其太山中舍，幷女遣之。誥寄弟诗曰：）', '16823386-c33a-4886-a68a-eee63753a187', '唐', '["三年作贅在京城，著箇緋衫倚勢行。","夜夜貪憐紅粉女，朝朝渾忘白頭兄。","親情別後饑寒死，僕使歸來氣宇生。","世上可能容此事，算來天道不分明。","（《鑑誡錄》八《非告勒》）（〖1〗鄭延休官中書舍人爲咸通末年事，詳岑仲勉《翰林學士壁記注補》十二，因知盧誥即其時人。","）。"]', '["三年作贅在京城，著箇緋衫倚勢行。","夜夜貪怜紅粉女，朝朝渾忘白头兄。","親情別後饑寒死，僕使归来氣宇生。","世上可能容此事，算来天道不分明。","（《鑑誡錄》八《非告勒》）（〖1〗鄭延休官中书舍人爲咸通末年事，詳岑仲勉《翰林学士壁記注補》十二，因知盧誥即其时人。","）。"]', '诗', 'shi', '', NULL, '寄弟詩（唐末，盧拾遺議與鄭中舍延休作贅，三年不歸陝下。其兄誥以詩讓之，詩意甚乖昆仲之禮。盧議呈其太山中舍，幷女遣之。誥寄弟詩曰：） 盧誥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f29bf8e-086f-4e06-bf26-36c43be82918', '因聘女自爲內相醉酬新郎催妝之詩（詩意風豔之甚，親族聞者，莫不笑之。）', '因聘女自爲內相醉酬新郎催妝之诗（诗意风豔之甚，親族闻者，莫不笑之。）', 'cea1118d-377f-40d7-bbd4-878174e80fe7', '唐', '["莫飛篇翰苦相煎，款款容人帖翠鈿。","不是到來梳洗晚，却憂玉體未禁憐。","（同上）。"]', '["莫飞篇翰苦相煎，款款容人帖翠鈿。","不是到来梳洗晚，却憂玉體未禁怜。","（同上）。"]', '诗', 'shi', '', NULL, '因聘女自爲內相醉酬新郎催妝之詩（詩意風豔之甚，親族聞者，莫不笑之。） 馬彥珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46574468-8b98-482a-b8ca-1371611a011d', '和韋莊賀陳詠歸蜀（句）（唐前朝進士陳詠，眉州青神人，有詩名，善弈棊。昭宗劫遷，駐蹕陝郊，是歲策名歸蜀，韋書記莊以詩賀之。又有鄉人拓善者，屬和韋詩，其略云云，譏其比滌器當壚也。謬稱馮副使涓詩，以涓多諧戲故也。或云：蜀之拓善者作此詩，假馮公之名也。）', '和韋莊賀陳詠归蜀（句）（唐前朝進士陳詠，眉州青神人，有诗名，善弈棊。昭宗劫遷，駐蹕陝郊，是歲策名归蜀，韋书記莊以诗賀之。又有乡人拓善者，屬和韋诗，其略云云，譏其比滌器當壚也。謬稱馮副使涓诗，以涓多諧戲故也。或云：蜀之拓善者作此诗，假馮公之名也。）', 'a21e5435-3e5e-4e0e-adef-ea2277c7c775', '唐', '["讓德已聞多士伏，沽名還得世人聞。","〖2〗（《北夢瑣言》七）（〖1〗拓善，《唐詩紀事》卷七十一引作「鄉中有嫉善者」，疑「拓善」並非人名。","〖2〗《全唐詩》卷七九六收二句於無名氏下。","）。"]', '["讓德已闻多士伏，沽名還得世人闻。","〖2〗（《北梦瑣言》七）（〖1〗拓善，《唐诗紀事》卷七十一引作「乡中有嫉善者」，疑「拓善」並非人名。","〖2〗《全唐诗》卷七九六收二句於無名氏下。","）。"]', '诗', 'shi', '', NULL, '和韋莊賀陳詠歸蜀（句）（唐前朝進士陳詠，眉州青神人，有詩名，善弈棊。昭宗劫遷，駐蹕陝郊，是歲策名歸蜀，韋書記莊以詩賀之。又有鄉人拓善者，屬和韋詩，其略云云，譏其比滌器當壚也。謬稱馮副使涓詩，以涓多諧戲故也。或云：蜀之拓善者作此詩，假馮公之名也。） 拓善 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95473367-23fe-413f-b022-e2c9823a0e08', '', '', 'ac44a2b1-caa7-4147-89ec-e2e5b34b9a1a', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 馮銖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409b1373-9ea3-458d-bc68-41263efa41f4', '靈巖秋月', '靈巖秋月', 'ac44a2b1-caa7-4147-89ec-e2e5b34b9a1a', '唐', '["青松崖上紫雲生，崖下仙人約舊盟。","駐馬看碑驚化鶴，暮雲回首萬家城。","（《蜀中名勝記》八《成都府·資縣》）。"]', '["青松崖上紫云生，崖下仙人約旧盟。","駐马看碑驚化鹤，暮云回首万家城。","（《蜀中名勝記》八《成都府·資縣》）。"]', '诗', 'shi', '', NULL, '靈巖秋月 馮銖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66719b81-aa76-4c75-bead-1240beb26a14', '簡州（句） 一', '簡州（句） 一', 'a69c6125-cdfd-4a4a-85b0-83ec23c5d0d3', '唐', '["使君橋柳凝清鏡，玉女山煙展畫屏。"]', '["使君橋柳凝清镜，玉女山煙展畫屏。"]', '诗', 'shi', '', NULL, '簡州（句） 一 范禹偁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e47a48-8bc2-4157-a578-43399fda97b2', '簡州（句） 二', '簡州（句） 二', 'a69c6125-cdfd-4a4a-85b0-83ec23c5d0d3', '唐', '["繞城山雪自粧點，三縣人煙共接連。","（《輿地紀勝》一四五《簡州》）（〖1〗《全唐詩》無范禹偁詩，茲據《十國春秋》卷五三補傳：范禹偁，九隴人。","天成中登第，孟知祥以爲蒙陽令，入侍太子。","後蜀後主孟昶嗣位後，累兼翰林學士，曾兼簡州刺史。","蜀亡，從後主歸宋，授鴻臚卿，開寶三年尚在世。","〖參張忱石考證〗）。"]', '["繞城山雪自粧点，三縣人煙共接連。","（《輿地紀勝》一四五《簡州》）（〖1〗《全唐诗》無范禹偁诗，茲據《十国春秋》卷五三補傳：范禹偁，九隴人。","天成中登第，孟知祥以爲蒙陽令，入侍太子。","後蜀後主孟昶嗣位後，累兼翰林学士，曾兼簡州刺史。","蜀亡，從後主归宋，授鴻臚卿，开寶三年尚在世。","〖參張忱石考證〗）。"]', '诗', 'shi', '', NULL, '簡州（句） 二 范禹偁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a1a92c-37d5-4d00-a105-4292ab24f671', '夏雨登干霄亭上宋使君（二首） 一', '夏雨登干霄亭上宋使君（二首） 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霽色澄鮮壑映紅，干霄亭上望無窮。","蟬驚殘雨疑秋蚤，雷傍嚴城報歲豐。","歸廟片雲銜紫電，立查雙鶴唳仙風。","自憐四郡干戈日，得在文翁教化中。","。"]', '["霽色澄鲜壑映紅，干霄亭上望無窮。","蟬驚殘雨疑秋蚤，雷傍嚴城報歲豐。","归廟片云銜紫電，立查雙鹤唳仙风。","自怜四郡干戈日，得在文翁教化中。","。"]', '诗', 'shi', '', NULL, '夏雨登干霄亭上宋使君（二首） 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3188200-8774-4f17-8dec-4dc6aece7055', '夏雨登干霄亭上宋使君（二首） 二', '夏雨登干霄亭上宋使君（二首） 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鄒魯封疆禾稼濃，清吟孤坐思重重。","新詩幾獻蓬萊客，遠夢仍歸菡萏峯。","野果一枝堪薦茗，落霞數片欲燒松。","如何深得冥搜癖，月磬聲聲歸去慵。"]', '["鄒魯封疆禾稼濃，清吟孤坐思重重。","新诗幾獻蓬萊客，远梦仍归菡萏峯。","野果一枝堪薦茗，落霞數片欲燒松。","如何深得冥搜癖，月磬声声归去慵。"]', '诗', 'shi', '', NULL, '夏雨登干霄亭上宋使君（二首） 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82637e97-88a3-4903-8db6-3c220a5901cc', '宋使君罷新定移出東館（二首） 一', '宋使君罷新定移出东館（二首） 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["無爲政化更何爲，到即生人嫗煦肥。","必似漢高三傑去，且將劉寵一錢歸。","玉階香惹麒麟步，銀漢風驅鸑鷟飛。","爲報蒸民莫惆悵，陶鈞及爾更光輝。"]', '["無爲政化更何爲，到即生人嫗煦肥。","必似漢高三傑去，且將劉寵一錢归。","玉階香惹麒麟步，銀漢风驱鸑鷟飞。","爲報蒸民莫惆悵，陶鈞及爾更光輝。"]', '诗', 'shi', '', NULL, '宋使君罷新定移出東館（二首） 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38d5d25-7d40-4f73-99c6-54d768c7fe6d', '宋使君罷新定移出東館（二首） 二', '宋使君罷新定移出东館（二首） 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["祖筵四面煙花合，江館深冬歸思長。","火斾畫旗風燄燄，橘洲漁舍浪茫茫。","聽歌幾入紅蘭榭，坐隱頻升白玉堂。","今數不如沙磧雁，天邊一一得隨陽。"]', '["祖筵四面煙花合，江館深冬归思长。","火斾畫旗风燄燄，橘洲漁舍浪茫茫。","听歌幾入紅蘭榭，坐隐頻升白玉堂。","今數不如沙磧雁，天邊一一得隨陽。"]', '诗', 'shi', '', NULL, '宋使君罷新定移出東館（二首） 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45da7e45-3e26-462b-91b6-29d7fb63e12c', '寄杭州宋使君（公初罷睦州）', '寄杭州宋使君（公初罷睦州）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一自雙旌下釣臺，望風吟苦凍雲開。","即歸紫闥天非遠，猶憶烏龍首獨回。","高節似僧僧共坐，暮潮如雪雪中來。","應知新定蒼生淚，灑向東風祝上台。"]', '["一自雙旌下釣台，望风吟苦凍云开。","即归紫闥天非远，猶憶烏龙首独回。","高節似僧僧共坐，暮潮如雪雪中来。","應知新定蒼生泪，灑向东风祝上台。"]', '诗', 'shi', '', NULL, '寄杭州宋使君（公初罷睦州） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a9afe9-807f-4a8f-bf75-5eb48fe0f446', '游嚴陵釣臺', '游嚴陵釣台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雪浪皚皚萬古情，岸邊臺占子陵名。","一時大器天將與，數尺漁竿誰不擎。","危榭高碑鐫籀字，滄洲老鶴識先生。","游人到此慵歸去，庭樹孤猿有好聲。"]', '["雪浪皚皚万古情，岸邊台占子陵名。","一时大器天將與，數尺漁竿誰不擎。","危榭高碑鐫籀字，滄洲老鹤識先生。","游人到此慵归去，庭樹孤猿有好声。"]', '诗', 'shi', '', NULL, '游嚴陵釣臺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5fd97d-ec75-4bae-a148-4c67c2bb1770', '新定江邊作', '新定江邊作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["江邊山頂深秋時，身閑瀟灑心無爲。","石頭青草取次坐，松風竹風撩亂吹。","數聲好鳥來依我，一點征帆去是誰。","惆悵古賢何處在，潺潺夕照滿江湄。","（日落山照燿，即此處也。","以上《嚴陵集》二）。"]', '["江邊山頂深秋时，身闲瀟灑心無爲。","石头青草取次坐，松风竹风撩亂吹。","數声好鸟来依我，一点征帆去是誰。","惆悵古賢何处在，潺潺夕照满江湄。","（日落山照燿，即此处也。","以上《嚴陵集》二）。"]', '诗', 'shi', '', NULL, '新定江邊作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ebb3829-3e84-410f-935a-c4c9a40737b7', '送軒轅先生歸羅浮山（初，貫休詩名未振。時南楚才人，競以詩送軒轅先生歸羅浮山，計百餘首矣。後貫休因吟一章，羣公於是息筆。）', '送軒轅先生归羅浮山（初，貫休诗名未振。时南楚才人，競以诗送軒轅先生归羅浮山，計百餘首矣。後貫休因吟一章，羣公於是息笔。）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["玉房花洞接三清，謾指羅浮是去程。","龍馬便攜笻竹杖，山童常使茯苓精。","曾教莊子拋卑吏，却喚軒皇作老兄。","再見先生又何日，只應頻夢紫金城。","（《鑑誡錄》五《禪月吟》）。"]', '["玉房花洞接三清，謾指羅浮是去程。","龙马便携笻竹杖，山童常使茯苓精。","曾教莊子拋卑吏，却喚軒皇作老兄。","再见先生又何日，只應頻梦紫金城。","（《鑑誡錄》五《禪月吟》）。"]', '诗', 'shi', '', NULL, '送軒轅先生歸羅浮山（初，貫休詩名未振。時南楚才人，競以詩送軒轅先生歸羅浮山，計百餘首矣。後貫休因吟一章，羣公於是息筆。） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a254dc-6b00-473d-b17c-ac3ed1d2a059', '題天壇', '題天壇', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["壁立三千仞，壇高接尾箕。","頂藏青玉髓，腰隱紫金芝。","月掛虛皇殿，雲封太乙池。","洞天人跡少，鶴宿萬年枝。","（《古今圖書集成·山川典》四六《王屋山部》）（〖1〗《正統道藏》本杜光庭《天壇王屋山聖迹記》收此詩於通真道人名下。","通真道人生平未詳。","乾隆《濟源縣志》卷十六作姚合詩。","）。"]', '["壁立三千仞，壇高接尾箕。","頂藏青玉髓，腰隐紫金芝。","月掛虛皇殿，云封太乙池。","洞天人跡少，鹤宿万年枝。","（《古今圖书集成·山川典》四六《王屋山部》）（〖1〗《正統道藏》本杜光庭《天壇王屋山聖迹記》收此诗於通真道人名下。","通真道人生平未詳。","乾隆《濟源縣志》卷十六作姚合诗。","）。"]', '诗', 'shi', '', NULL, '題天壇 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d76f03-2e09-4e29-b35c-126121d0b489', '上清宮（句）', '上清宮（句）', '4beb3e8d-f15c-406c-8563-4dc6e74308f8', '唐', '["十年重到上清宮，石磴泉梯屈曲通。","（《輿地紀勝》一五一《永康軍》）。"]', '["十年重到上清宮，石磴泉梯屈曲通。","（《輿地紀勝》一五一《永康軍》）。"]', '诗', 'shi', '', NULL, '上清宮（句） 杜光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17f94fe-fb73-44ab-b302-8e648fb86135', '', '', 'b8460cac-0ff6-4731-9386-90d30787dc4f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbd6a09d-cf43-434a-a9c3-409b8e3b6760', '徵李懷杲（一作果）嘲道門 一', '徵李懷杲（一作果）嘲道门 一', 'b8460cac-0ff6-4731-9386-90d30787dc4f', '唐', '["雲鎖涪江水似天，又聞懷杲已升仙。","強思齊見應催膽，張茂卿聞必聳肩（強與張二玄士）。","三尺霜刀（一作鋒）充絳節，兩條朱棒替香煙。","報伊廣德先生道，社稷威靈不偶然。"]', '["云鎖涪江水似天，又闻懷杲已升仙。","強思齊见應催膽，張茂卿闻必聳肩（強與張二玄士）。","三尺霜刀（一作鋒）充絳節，兩條朱棒替香煙。","報伊廣德先生道，社稷威靈不偶然。"]', '诗', 'shi', '', NULL, '徵李懷杲（一作果）嘲道門 一 光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('395d53e7-dcb2-4163-82ca-609458de9ac2', '徵李懷杲（一作果）嘲道門 二', '徵李懷杲（一作果）嘲道门 二', 'b8460cac-0ff6-4731-9386-90d30787dc4f', '唐', '["山上擒來鎮裏收，天然模樣已成囚。","妄占氣色爲徵兆，更引文章說御樓。","長牓數張懸市內，短刀一隊送江頭。","旋驅旋斬教隨水，只此名爲正道流。","（〖1〗以上二首原作一首，從趙遂之說分爲二首。","）。"]', '["山上擒来鎮裏收，天然模樣已成囚。","妄占氣色爲徵兆，更引文章说御楼。","长牓數張懸市內，短刀一隊送江头。","旋驱旋斬教隨水，只此名爲正道流。","（〖1〗以上二首原作一首，從趙遂之说分爲二首。","）。"]', '诗', 'shi', '', NULL, '徵李懷杲（一作果）嘲道門 二 光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f807e1a4-770b-4e64-b345-468998331689', '嘲道門進《武成混元圖》', '嘲道门進《武成混元圖》', 'b8460cac-0ff6-4731-9386-90d30787dc4f', '唐', '["夜深燈火滿壇舖，拔劍揮空亂叫呼。","黑撒半筐兵甲豆，朱書一道厭人符。","重臣餧飼剛教活，聖主慈悲未忍誅。","佛說毘盧三界了（一作「乃三界」），如何更有《混元圖》。"]', '["夜深灯火满壇舖，拔劍揮空亂叫呼。","黑撒半筐兵甲豆，朱书一道厭人符。","重臣餧飼剛教活，聖主慈悲未忍誅。","佛说毘盧三界了（一作「乃三界」），如何更有《混元圖》。"]', '诗', 'shi', '', NULL, '嘲道門進《武成混元圖》 光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502f98e1-70e9-43af-a8ff-9dc1681ef043', '徵青州長老嘲僧門 一', '徵青州长老嘲僧门 一', 'ed4e9758-3e3b-4e65-bb3c-7de96d1589a1', '唐', '["堪笑青州學坐禪，不供父母不耕田。","口中雖道無諸相，心裏元來有外緣。","行者趁教門裏臥，尼師留在脚頭眠。","高標不使觀音救，徒說三千與大千。"]', '["堪笑青州学坐禪，不供父母不耕田。","口中雖道無諸相，心裏元来有外緣。","行者趁教门裏臥，尼師留在脚头眠。","高標不使观音救，徒说三千與大千。"]', '诗', 'shi', '', NULL, '徵青州長老嘲僧門 一 楊德輝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e900c7-8094-486a-8052-767d194a9f56', '徵青州長老嘲僧門 二', '徵青州长老嘲僧门 二', 'ed4e9758-3e3b-4e65-bb3c-7de96d1589a1', '唐', '["出家比要離生緣，爭是爭名更在先。","說法謾稱獅子吼，魅人多使野狐涎（一作禪）。","行婆餉送新童子，居士抄條施利錢。","蠶食萬民何所用，轉教海內有荒田。","（〖1〗以上二首原作一首，從趙遂之說分爲二首。","）。"]', '["出家比要離生緣，爭是爭名更在先。","说法謾稱獅子吼，魅人多使野狐涎（一作禪）。","行婆餉送新童子，居士抄條施利錢。","蠶食万民何所用，轉教海內有荒田。","（〖1〗以上二首原作一首，從趙遂之说分爲二首。","）。"]', '诗', 'shi', '', NULL, '徵青州長老嘲僧門 二 楊德輝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb49e87-3390-4723-aaba-7eb87f2ced3d', '嘲僧門祝辟支佛牙', '嘲僧门祝辟支佛牙', 'ed4e9758-3e3b-4e65-bb3c-7de96d1589a1', '唐', '["比來降誕爲官家，堪笑羣胡讚佛牙。","手軟阿師持磬鈸，面甜童子執幡花。","縱饒黎庶無知識，不可公王盡信邪。","捧擁一函枯骨立，如何延得壽無涯。","（以上《鑑誡錄》六《旌論衡》）。"]', '["比来降誕爲官家，堪笑羣胡讚佛牙。","手軟阿師持磬鈸，面甜童子執幡花。","縱饒黎庶無知識，不可公王尽信邪。","捧擁一函枯骨立，如何延得壽無涯。","（以上《鑑誡錄》六《旌論衡》）。"]', '诗', 'shi', '', NULL, '嘲僧門祝辟支佛牙 楊德輝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3118f69-7930-4582-9023-1b76c8e7ce7b', '落韻詩（二首） 一', '落韻诗（二首） 一', '0acb27c2-c4bc-45b8-bb2d-8e99eb66777d', '唐', '["路傍傷羸牛，羸牛身已老。","兩眼不能開，四蹄行欲倒。","牛曾少壯時，歲歲耕田早。","耕却春秋田，駕車長安道。","今日領頭穿，無人飼水草。","喘也不能喘，問也沒人問。"]', '["路傍傷羸牛，羸牛身已老。","兩眼不能开，四蹄行欲倒。","牛曾少壯时，歲歲耕田早。","耕却春秋田，駕车长安道。","今日領头穿，無人飼水草。","喘也不能喘，问也沒人问。"]', '诗', 'shi', '', NULL, '落韻詩（二首） 一 李如實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d31359-45e7-4236-9011-efae45bf7b70', '落韻詩（二首） 二', '落韻诗（二首） 二', '0acb27c2-c4bc-45b8-bb2d-8e99eb66777d', '唐', '["炎蒸不可度，執（一作倏，又作賴）爾生涼風。","在物誠非器，於人還有功。","殷勤九夏內，寂寞三秋中。","想君應有語，棄我如秋扇。","（《鑑誡錄》三《落韻貶》）。"]', '["炎蒸不可度，執（一作倏，又作賴）爾生涼风。","在物誠非器，於人還有功。","殷勤九夏內，寂寞三秋中。","想君應有語，棄我如秋扇。","（《鑑誡錄》三《落韻貶》）。"]', '诗', 'shi', '', NULL, '落韻詩（二首） 二 李如實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42404c6-e1f2-461a-8e5f-0b0e8a4ab4dc', '', '', '4baf4cd5-a499-4cc0-b76d-eda88c2fd81b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 令狐嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ed9200-a112-409b-b269-40cdb7086143', '明慶節散後贈左右兩街命服僧玄', '明慶節散後贈左右兩街命服僧玄', '4baf4cd5-a499-4cc0-b76d-eda88c2fd81b', '唐', '["卻羨僧門與道門，元年今日紫衣新。","可憐州縣祁評事，盡向荷衣老卻身。"]', '["卻羨僧门與道门，元年今日紫衣新。","可怜州縣祁評事，尽向荷衣老卻身。"]', '诗', 'shi', '', NULL, '明慶節散後贈左右兩街命服僧玄 令狐嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc6137d-38f3-4e24-8a47-a5a557338f6f', '詠有年官健', '詠有年官健', '4baf4cd5-a499-4cc0-b76d-eda88c2fd81b', '唐', '["六十休論少壯時，尉遲功業擬奚爲。","高聲念佛尋街者，盡是抝（一作拘）停老健兒。","（以上《鑑誡錄》四《蜀門諷》）。"]', '["六十休論少壯时，尉遲功業擬奚爲。","高声念佛尋街者，尽是抝（一作拘）停老健兒。","（以上《鑑誡錄》四《蜀门諷》）。"]', '诗', 'shi', '', NULL, '詠有年官健 令狐嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8c55095-f15b-405c-9a95-5f7816f978b1', '詠人祀聖君詩', '詠人祀聖君诗', '83e71724-dd89-4ca6-af7c-e8ee7bae215d', '唐', '["禍福從來豈自主（一作由），俗情淫祀也堪愁。","拜時何用頻偷眼，未必泥人解點頭。","（同前）。"]', '["禍福從来豈自主（一作由），俗情淫祀也堪愁。","拜时何用頻偷眼，未必泥人解点头。","（同前）。"]', '诗', 'shi', '', NULL, '詠人祀聖君詩 鄭雲從 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e0892dd-2470-48c6-aaa9-00c3985bb4e4', '乘煙觀蔣鍊師（蔣甚偉，非婦人之狀。）', '乘煙观蔣鍊師（蔣甚偉，非婦人之狀。）', '438a3918-48f7-4f08-9c38-91931549e19b', '唐', '["怪得盤跚不上昇，白雲蹋綻紫雲崩。","龍腰鳳背猶嫌軟，須問麻姑借大鵬。","（同前）（〖1〗曹汛謂向瓚爲何瓚之誤。","《全唐詩》卷七六九收何贊，亦應作何瓚。","事迹見《新五代史》卷二八本傳。","今按：《南唐近事》有陳沆諷廬山道士絕句，與此大同小異。","陳詩收）（《全唐詩》卷七五七。","《鑑誡錄》成書早於《南唐近事》，詩以向作爲近是。","）。"]', '["怪得盤跚不上昇，白云蹋綻紫云崩。","龙腰鳳背猶嫌軟，須问麻姑借大鵬。","（同前）（〖1〗曹汛謂向瓚爲何瓚之誤。","《全唐诗》卷七六九收何贊，亦應作何瓚。","事迹见《新五代史》卷二八本傳。","今按：《南唐近事》有陳沆諷廬山道士絕句，與此大同小異。","陳诗收）（《全唐诗》卷七五七。","《鑑誡錄》成书早於《南唐近事》，诗以向作爲近是。","）。"]', '诗', 'shi', '', NULL, '乘煙觀蔣鍊師（蔣甚偉，非婦人之狀。） 向瓚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c58041-2ab2-4be1-916a-4841cfc28bc8', '獻賀捷詩（孟知祥入梓州，舉子勾龍逢獻詩云云，孟知祥嘉納之。）', '獻賀捷诗（孟知祥入梓州，舉子勾龙逢獻诗云云，孟知祥嘉納之。）', '0a84c344-d4e2-48c0-a73b-e086991502e4', '唐', '["唇齒論交歲月長，豈其率意忽顛狂。","元戎統領三軍戰，巨孽奔衝一陣亡。","莫訝潼江剛入寇，都緣錦浦合興王。","武功蓋世光前後，堪向青編萬古揚。","（《全五代詩》五七引《十國春秋》）（〖1〗見《鑑誡錄》卷一《知機對》、《十國春秋》卷四八《後蜀高祖本紀》。","孟知祥入梓州，爲長興三年五月間事。","）。"]', '["唇齒論交歲月长，豈其率意忽顛狂。","元戎統領三軍戰，巨孽奔衝一陣亡。","莫訝潼江剛入寇，都緣錦浦合兴王。","武功蓋世光前後，堪向青編万古揚。","（《全五代诗》五七引《十国春秋》）（〖1〗见《鑑誡錄》卷一《知機对》、《十国春秋》卷四八《後蜀高祖本紀》。","孟知祥入梓州，爲长兴三年五月间事。","）。"]', '诗', 'shi', '', NULL, '獻賀捷詩（孟知祥入梓州，舉子勾龍逢獻詩云云，孟知祥嘉納之。） 勾龍逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b535d286-dd18-4446-862c-f1dcc98551c1', '凌霄花', '凌霄花', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["凌霄多半繞棕櫚，深染梔黃色不如。","滿樹微風吹細葉，一條龍甲颭清虛。","（《古今圖書集成·草木典·苕部》）。"]', '["凌霄多半繞棕櫚，深染梔黄色不如。","满樹微风吹細葉，一條龙甲颭清虛。","（《古今圖书集成·草木典·苕部》）。"]', '诗', 'shi', '', NULL, '凌霄花 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fb05e8-e996-4750-800b-e9fa31507445', '至真觀（三言詩）（仁傑善導氣烹鍊之術。孟知祥鎮西川時。來蜀留詩至真觀壁間。）', '至真观（三言诗）（仁傑善導氣烹鍊之術。孟知祥鎮西川时。来蜀留诗至真观壁间。）', '6a29e924-c019-42f7-95ef-97f4570982d3', '唐', '["坤所載，乾所幬，象與形，孰朕兆？","緯五行，環二曜，流百川，何浩浩。","四海晏，九河導，峙而山，亦多號。","神有嶽，山有嶠，粤廟（一作「天」）壇，稽（一作「極」）道妙。","巉孤崢（一作「撐」），未易到，日出沒，見遺照。","偃東西，絕海徼，倐光怪，來熠耀。","大龍燭，細螢爝，不恆出，赴感召。","笙嘹喨，鶴窈窕，羽人路，屯其要。","青螺堆，玉簪峭。","左參井，右丹竈，揭清虛，不二竅。","昔王人，往昭告，始軒轅，末徽廟。","接柴望，咸親燎，莽刼灰，起天燒。","摧棟宇，失朱縹。","羣鹿逐（一作「豕」），雜蓬藋。","予何爲，一來弔，必勝廢，乃大造。","聖之作，賢者紹，矧玄元，語秘奧。","探愈遠，理益耀，徵是理，萬有耗。","文雖徑（一作「怪」），實非剽，庶今來，永爲詔。","（《全蜀藝文志》二三、《十國春秋》五七）（〖1〗《正統道藏》本杜光庭《天壇王屋山聖迹記》末附錄此詩，署「齊人杜仁傑撰」，末署「至元二十六年五月□日」。","至元爲元代年號。","臺灣學者編《元人傳記資料索引》有杜仁傑小傳云：「杜仁傑，字仲梁，號止軒，原名之元，字善夫，濟南長清人。","金末隱內鄉山中。","至元中屢徵不起。","」爲綜合多種資料編成。","姓名、籍貫、時代皆相符，是詩應即此人所作。","《十國春秋》卷五七云其爲孟知祥時人，不詳所據。","宋前典籍中無此記載。","作五代人恐誤。","詩姑仍存，俟續考定。","）。"]', '["坤所載，乾所幬，象與形，孰朕兆？","緯五行，环二曜，流百川，何浩浩。","四海晏，九河導，峙而山，亦多號。","神有嶽，山有嶠，粤廟（一作「天」）壇，稽（一作「極」）道妙。","巉孤崢（一作「撐」），未易到，日出沒，见遺照。","偃东西，絕海徼，倐光怪，来熠耀。","大龙燭，細螢爝，不恆出，赴感召。","笙嘹喨，鹤窈窕，羽人路，屯其要。","青螺堆，玉簪峭。","左參井，右丹竈，揭清虛，不二竅。","昔王人，往昭告，始軒轅，末徽廟。","接柴望，咸親燎，莽刼灰，起天燒。","摧棟宇，失朱縹。","羣鹿逐（一作「豕」），杂蓬藋。","予何爲，一来弔，必勝廢，乃大造。","聖之作，賢者紹，矧玄元，語秘奧。","探愈远，理益耀，徵是理，万有耗。","文雖徑（一作「怪」），實非剽，庶今来，永爲詔。","（《全蜀藝文志》二三、《十国春秋》五七）（〖1〗《正統道藏》本杜光庭《天壇王屋山聖迹記》末附錄此诗，署「齊人杜仁傑撰」，末署「至元二十六年五月□日」。","至元爲元代年號。","台灣学者編《元人傳記資料索引》有杜仁傑小傳云：「杜仁傑，字仲梁，號止軒，原名之元，字善夫，濟南长清人。","金末隐內乡山中。","至元中屢徵不起。","」爲綜合多種資料編成。","姓名、籍貫、时代皆相符，是诗應即此人所作。","《十国春秋》卷五七云其爲孟知祥时人，不詳所據。","宋前典籍中無此記載。","作五代人恐誤。","诗姑仍存，俟續考定。","）。"]', '诗', 'shi', '', NULL, '至真觀（三言詩）（仁傑善導氣烹鍊之術。孟知祥鎮西川時。來蜀留詩至真觀壁間。） 杜仁傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36313c3-10dd-4540-b7a0-742f39920f6f', '偈詩', '偈诗', '1b17b12d-aad7-4813-90d9-f739288abf40', '唐', '["毳流來問我家風，我道玲瓏處處通。","頃刻萬邦皆徧到，途中曾未一人逢。","。"]', '["毳流来问我家风，我道玲瓏处处通。","頃刻万邦皆徧到，途中曾未一人逢。","。"]', '诗', 'shi', '', NULL, '偈詩 張嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf33f32e-5e4c-4a9d-bfe8-e4f115c20a52', '句 一（有勾居士問：「不拘生死者，願師直指。」嶠答云：）', '句 一（有勾居士问：「不拘生死者，願師直指。」嶠答云：）', '1b17b12d-aad7-4813-90d9-f739288abf40', '唐', '["非干日月照，晝夜自分明。"]', '["非干日月照，晝夜自分明。"]', '诗', 'shi', '', NULL, '句 一（有勾居士問：「不拘生死者，願師直指。」嶠答云：） 張嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96a1a5e5-875b-41e7-98f0-1072a99cda19', '句 二（又問：「百億往來非指的，光明終不礙山河時如何？」嶠答云：）', '句 二（又问：「百億往来非指的，光明終不礙山河时如何？」嶠答云：）', '1b17b12d-aad7-4813-90d9-f739288abf40', '唐', '["紅尾漫搖三尺浪，真龍透石本無踪。","（以上《茅亭客話》三）。"]', '["紅尾漫搖三尺浪，真龙透石本無踪。","（以上《茅亭客話》三）。"]', '诗', 'shi', '', NULL, '句 二（又問：「百億往來非指的，光明終不礙山河時如何？」嶠答云：） 張嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff279c18-e9f5-4564-a167-2fd1529dff97', '敬禮瓦屋和尚塔偈（瓦屋和尚名能光，日本國人。）', '敬禮瓦屋和尚塔偈（瓦屋和尚名能光，日本国人。）', 'c87984d2-47fe-4340-b94e-0a771cc73ef4', '唐', '["大空無盡劫成塵，玄步孤高物外人。","日本國來尋彼岸，洞山林下過迷津。","流流法乳誰無分，了了教知我最親。","一百六十三歲後，方於此塔葬全身。","（同上）（〖1〗勾令玄，原作勾令元，爲清人諱改，從穴研齋影宋本《茅亭客話》改。","）。"]', '["大空無尽劫成塵，玄步孤高物外人。","日本国来尋彼岸，洞山林下過迷津。","流流法乳誰無分，了了教知我最親。","一百六十三歲後，方於此塔葬全身。","（同上）（〖1〗勾令玄，原作勾令元，爲清人諱改，從穴研斋影宋本《茅亭客話》改。","）。"]', '诗', 'shi', '', NULL, '敬禮瓦屋和尚塔偈（瓦屋和尚名能光，日本國人。） 勾令玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c099011-5629-4df9-8c76-8f2a1f45ad66', '', '', 'dec51049-2e18-47fe-9935-e37a31e64350', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 淘沙子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51efdb64-f013-4b25-a016-1dbe5fab2825', '詩', '诗', 'dec51049-2e18-47fe-9935-e37a31e64350', '唐', '["九重城裏人中貴，五等諸侯閫外尊。","爭似布衣雲水客，不將名字掛乾坤。","（同上）（〖1〗《全蜀藝文志》卷二三、《全唐詩》卷七六一收此詩爲丁元和作，《全五代詩》卷六十云丁元和號淘沙子。","《茅亭客話》卷四載丁元和事迹較詳，與卷三所載之淘沙子似非一人。","）。"]', '["九重城裏人中貴，五等諸侯閫外尊。","爭似布衣云水客，不將名字掛乾坤。","（同上）（〖1〗《全蜀藝文志》卷二三、《全唐诗》卷七六一收此诗爲丁元和作，《全五代诗》卷六十云丁元和號淘沙子。","《茅亭客話》卷四載丁元和事迹較詳，與卷三所載之淘沙子似非一人。","）。"]', '诗', 'shi', '', NULL, '詩 淘沙子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e857fd39-d229-4725-a685-a5008d0e1c25', '遺詩', '遺诗', '8c94328a-5d56-42fe-8b05-eedb4df48d9d', '唐', '["心是靈臺神是室，口爲玉池生玉液。","常將玉液溉靈臺，流利關元滋百脈。","百脈潤，柯葉青，葉青柯潤便長生。","世人不會長生藥，煉石燒丹勞爾形。","（《茅亭客話》四）（〖1〗《全唐詩》無宋自然詩，茲據《茅亭客話》補其事跡：宋自然，長興中遂州貧士，常於街市中行乞。","孟知祥攻圍遂州時，餓殍於州市。","後有人云曾於潞州見之，又於其埋處得遺詩一紙。","）。"]', '["心是靈台神是室，口爲玉池生玉液。","常將玉液溉靈台，流利关元滋百脈。","百脈潤，柯葉青，葉青柯潤便长生。","世人不會长生藥，煉石燒丹勞爾形。","（《茅亭客話》四）（〖1〗《全唐诗》無宋自然诗，茲據《茅亭客話》補其事跡：宋自然，长兴中遂州貧士，常於街市中行乞。","孟知祥攻圍遂州时，餓殍於州市。","後有人云曾於潞州见之，又於其埋处得遺诗一紙。","）。"]', '诗', 'shi', '', NULL, '遺詩 宋自然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acefc38c-725f-4f7f-8201-9472d63244e2', '書妙圓塔院張道者屋壁（蜀大東門外有妙圓塔院，僧名行勤，俗姓張氏，人以其精於修行，因謂之道者。）', '书妙圓塔院張道者屋壁（蜀大东门外有妙圓塔院，僧名行勤，俗姓張氏，人以其精於修行，因謂之道者。）', '43932f58-564e-4140-b04c-279467c964c5', '唐', '["成都有一張道者，五十年來住村野。","祇將淡薄作家風，未省承迎相苟且。","南地禪宗盡偏參，西蜀叢林遊已罷。","深知大藏是解粘，不把三乘定真假。","張道者，傍沙溪，居蘭若，草作衣裳茅作舍。","活計生涯一物無，免被外人來借借。","寅齋午睡樂咍咍，檀越供須都不謝。","沿身不直五分銅，一句玄玄豈論價。","張道者，貌古神清不可畫。","鶴性雲情本自然，生死無心全不怕。","縱逢刼火未爲災，暗裏龍蛇應歎訝。","張道者，不說禪，不答話，蓋爲人心難誘化。","盡奔名利謾馳驅，個個何曾有般若。","分明與說速休心，供家卻道也爛也。","張道者，不聚徒，甚脫灑，不結遠公白蓮社。","心似秋潭月一輪，何用聲名播天下。","（《茅亭客話》三）。"]', '["成都有一張道者，五十年来住村野。","祇將淡薄作家风，未省承迎相苟且。","南地禪宗尽偏參，西蜀叢林游已罷。","深知大藏是解粘，不把三乘定真假。","張道者，傍沙溪，居蘭若，草作衣裳茅作舍。","活計生涯一物無，免被外人来借借。","寅斋午睡乐咍咍，檀越供須都不謝。","沿身不直五分銅，一句玄玄豈論價。","張道者，貌古神清不可畫。","鹤性云情本自然，生死無心全不怕。","縱逢刼火未爲災，暗裏龙蛇應歎訝。","張道者，不说禪，不答話，蓋爲人心难誘化。","尽奔名利謾驰驱，個個何曾有般若。","分明與说速休心，供家卻道也爛也。","張道者，不聚徒，甚脫灑，不結远公白蓮社。","心似秋潭月一輪，何用声名播天下。","（《茅亭客話》三）。"]', '诗', 'shi', '', NULL, '書妙圓塔院張道者屋壁（蜀大東門外有妙圓塔院，僧名行勤，俗姓張氏，人以其精於修行，因謂之道者。） 慈覺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae61afd-0ed7-4e15-b0ff-5e082eff3a57', '蒸豚（王中令既平蜀，捕逐餘寇，與步隊〖隊伍〗相遠，饑甚，乃入一村寺中。主僧醉甚箕踞，公怒，欲斬之。僧應對不懾，公奇而釋之。間求蔬食，僧云：「有肉無蔬。」公益奇之。餽以蒸豚頭，食之甚美。公喜，問僧：「止能飲酒食肉耶，抑有他技耶？」僧自言能詩。公令賦蒸豚詩，援〖操〗筆立成。詩云〖見下〗。公大喜，與紫衣，賜號爲蜀中詩僧。）', '蒸豚（王中令既平蜀，捕逐餘寇，與步隊〖隊伍〗相远，饑甚，乃入一村寺中。主僧醉甚箕踞，公怒，欲斬之。僧應对不懾，公奇而釋之。间求蔬食，僧云：「有肉無蔬。」公益奇之。餽以蒸豚头，食之甚美。公喜，问僧：「止能饮酒食肉耶，抑有他技耶？」僧自言能诗。公令賦蒸豚诗，援〖操〗笔立成。诗云〖见下〗。公大喜，與紫衣，賜號爲蜀中诗僧。）', 'e83a0093-0415-4fde-bf5d-150516dec8bf', '唐', '["嘴長毛短淺含臕，久向山中食藥苗。","蒸處已將蒸葉裹，熟時兼（一作「更」）用杏漿澆。","紅鮮雅稱食盤飣（一作貯），軟熟真堪玉筯挑。","若把羶根來比並，羶根只合喫（一作「喚」）藤條。","（《五代詩話》七引《百斛明珠》。","《全五代詩》六十引《東坡志林》）（〖1〗見《仇池筆記》卷下、《苕溪漁隱叢話前集》卷五十七。","）。"]', '["嘴长毛短淺含臕，久向山中食藥苗。","蒸处已將蒸葉裹，熟时兼（一作「更」）用杏漿澆。","紅鲜雅稱食盤飣（一作貯），軟熟真堪玉筯挑。","若把羶根来比並，羶根只合喫（一作「喚」）藤條。","（《五代诗話》七引《百斛明珠》。","《全五代诗》六十引《东坡志林》）（〖1〗见《仇池笔記》卷下、《苕溪漁隐叢話前集》卷五十七。","）。"]', '诗', 'shi', '', NULL, '蒸豚（王中令既平蜀，捕逐餘寇，與步隊〖隊伍〗相遠，饑甚，乃入一村寺中。主僧醉甚箕踞，公怒，欲斬之。僧應對不懾，公奇而釋之。間求蔬食，僧云：「有肉無蔬。」公益奇之。餽以蒸豚頭，食之甚美。公喜，問僧：「止能飲酒食肉耶，抑有他技耶？」僧自言能詩。公令賦蒸豚詩，援〖操〗筆立成。詩云〖見下〗。公大喜，與紫衣，賜號爲蜀中詩僧。） 村寺僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82840466-e431-495b-9da1-58596b5bcf84', '詠後主出降（《後山詩話》以爲花蕊夫人作，但前二句多異文）', '詠後主出降（《後山诗話》以爲花蕊夫人作，但前二句多異文）', '17904923-124a-4530-9e33-39162fa88337', '唐', '["蜀朝昬主出降時，銜璧牽羊倒繫旗。","二十萬軍齊拱手，更無一箇是男兒。","（《鑑誡錄》五《徐后事》）（〖1〗王承旨，應即王仁裕，詳《全唐詩續拾》卷四二。","）。"]', '["蜀朝昬主出降时，銜璧牽羊倒繫旗。","二十万軍齊拱手，更無一箇是男兒。","（《鑑誡錄》五《徐后事》）（〖1〗王承旨，應即王仁裕，詳《全唐诗續拾》卷四二。","）。"]', '诗', 'shi', '', NULL, '詠後主出降（《後山詩話》以爲花蕊夫人作，但前二句多異文） 王承旨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fa1ded-ec1b-4ce6-9c90-773e488d99be', '題九仙山', '題九仙山', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["太白歌中昔未聞，佛天高處却逢君。"]', '["太白歌中昔未闻，佛天高处却逢君。"]', '诗', 'shi', '', NULL, '題九仙山 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb2d119-b3d4-475a-adc9-f586c6339ff7', '題二石將軍', '題二石將軍', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["屹然相對兩將軍，化石經年久臥雲。"]', '["屹然相对兩將軍，化石經年久臥云。"]', '诗', 'shi', '', NULL, '題二石將軍 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af9867f-d308-44f6-bb0d-712dac09b44a', '題佛耳山', '題佛耳山', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["我愛佛耳山，來偷一日閑。","不見佛耳面，愧汗不開顏。","有時見佛耳，與山重往還。","（以上《嘉靖安溪縣志》七）。"]', '["我愛佛耳山，来偷一日闲。","不见佛耳面，愧汗不开顏。","有时见佛耳，與山重往還。","（以上《嘉靖安溪縣志》七）。"]', '诗', 'shi', '', NULL, '題佛耳山 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4cf1642-e923-4310-869c-6393ec43e470', '介庵贈古墨梅酬以一篇', '介庵贈古墨梅酬以一篇', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["開屏展素看梅花，淡蕊疎枝驀驀斜。","墨散餘香點酥萼，月留殘影照窗紗。","（《永樂大典》二八一二「梅」字韻）。"]', '["开屏展素看梅花，淡蕊疎枝驀驀斜。","墨散餘香点酥萼，月留殘影照窗紗。","（《永乐大典》二八一二「梅」字韻）。"]', '诗', 'shi', '', NULL, '介庵贈古墨梅酬以一篇 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a852b93-f67a-47c9-aced-f1e3cbb1ea96', '清隱堂', '清隐堂', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["一間茅屋寬容膝，半畝蔬園剩供廚。","靜把舊書重點勘，旋沽美酒養疎愚。","（一本作「縱教窮鬼每揶揄」）。","（同上七二三九「堂」字韻）。"]', '["一间茅屋寬容膝，半畝蔬园剩供廚。","静把旧书重点勘，旋沽美酒養疎愚。","（一本作「縱教窮鬼每揶揄」）。","（同上七二三九「堂」字韻）。"]', '诗', 'shi', '', NULL, '清隱堂 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('585aa2fe-e725-47c1-8fca-a81617438955', '題舫齋（原作詹時澤詩，敦仁字君澤，疑即一人）', '題舫斋（原作詹时澤诗，敦仁字君澤，疑即一人）', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["尖頭屋子不嫌低，上有青山下有池。","一陣東風拂松響，恰如蓬底雨來時。","（同上二五四○「齋」字韻）。"]', '["尖头屋子不嫌低，上有青山下有池。","一陣东风拂松响，恰如蓬底雨来时。","（同上二五四○「斋」字韻）。"]', '诗', 'shi', '', NULL, '題舫齋（原作詹時澤詩，敦仁字君澤，疑即一人） 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ce6052-2d98-48d5-9dd5-c72cd1ebc20e', '承清隱命訪劉處士已歿因弔以詩', '承清隐命訪劉处士已歿因弔以诗', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["鳳髻山前鳳閣郎，耕雲釣石久荒凉。","我來弔舊多悲感，一紙哀辭酹一觴。","（《嘉靖安溪縣志》七）。"]', '["鳳髻山前鳳閣郎，耕云釣石久荒凉。","我来弔旧多悲感，一紙哀辞酹一觴。","（《嘉靖安溪縣志》七）。"]', '诗', 'shi', '', NULL, '承清隱命訪劉處士已歿因弔以詩 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad019215-54c7-47be-98d6-acf219e03581', '雨後溪邊見早梅', '雨後溪邊见早梅', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["老榦疎枝浸寒碧，淺香孤韻帶微霜。","迎風破萼未全折，含笑佳人對曉粧。"]', '["老榦疎枝浸寒碧，淺香孤韻带微霜。","迎风破萼未全折，含笑佳人对晓粧。"]', '诗', 'shi', '', NULL, '雨後溪邊見早梅 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f80977-301f-4472-a13d-08f8507abe52', '又一本', '又一本', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["老榦疎枝浸寒碧，淺香孤韻湛清晨。","招魂不用開屏障，惟有詩情當寫真。","（《永樂大典》二八○八「梅」字韻）。"]', '["老榦疎枝浸寒碧，淺香孤韻湛清晨。","招魂不用开屏障，惟有诗情當寫真。","（《永乐大典》二八○八「梅」字韻）。"]', '诗', 'shi', '', NULL, '又一本 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a9f3de-b4ea-495f-b1e1-21b4552a1425', '詔福建置惠民倉呈陳守御史', '詔福建置惠民倉呈陳守御史', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["閩邦赤子近來王，聖主憂勤念遠方。","酌取古人救荒政，頒爲今日惠民倉。","備先水旱民亡瘠，弊在侵移數謾張。","我願相君謹刑政，雨暘時若自平康。","（同上七五一八「倉」字韻引詹琲《清隱集》）。"]', '["閩邦赤子近来王，聖主憂勤念远方。","酌取古人救荒政，頒爲今日惠民倉。","備先水旱民亡瘠，弊在侵移數謾張。","我願相君謹刑政，雨暘时若自平康。","（同上七五一八「倉」字韻引詹琲《清隐集》）。"]', '诗', 'shi', '', NULL, '詔福建置惠民倉呈陳守御史 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbef673b-c1fd-484f-a5d8-7b3912b31182', '', '', 'a1a9fb3b-6bf6-482a-abde-5cd5942bbca5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 慧稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('858ac78a-13ef-4117-8793-7be2e4a33ffe', '', '', 'a1a9fb3b-6bf6-482a-abde-5cd5942bbca5', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, ' 慧稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63213afd-3251-4227-bdf1-98d86b971b66', '捲簾大悟', '捲簾大悟', 'a1a9fb3b-6bf6-482a-abde-5cd5942bbca5', '唐', '["也大差，也不差，捲起簾來見天下。","有人問我解何宗，拈起拂子擘觜打。"]', '["也大差，也不差，捲起簾来见天下。","有人问我解何宗，拈起拂子擘觜打。"]', '诗', 'shi', '', NULL, '捲簾大悟 慧稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2059b16-3607-4931-891e-09a39da37649', '又口占一頌', '又口占一頌', 'a1a9fb3b-6bf6-482a-abde-5cd5942bbca5', '唐', '["萬象之中獨露身，惟人自肯乃相親。","昔時謬向途中覓，今日看來火裏冰。","（《全五代詩》八七引《槜李詩繫》）（〖1〗見《槜李詩繫》卷三十。","二詩最早出處爲《景德傳燈錄》卷十八，又見《五燈會元》卷七。","「擘觜」，二書作「擘口」；「相親」，二書作「方親」；「看來」，《景德傳燈錄》作「看如」。","）。"]', '["万象之中独露身，惟人自肯乃相親。","昔时謬向途中覓，今日看来火裏冰。","（《全五代诗》八七引《槜李诗繫》）（〖1〗见《槜李诗繫》卷三十。","二诗最早出处爲《景德傳灯錄》卷十八，又见《五灯會元》卷七。","「擘觜」，二书作「擘口」；「相親」，二书作「方親」；「看来」，《景德傳灯錄》作「看如」。","）。"]', '诗', 'shi', '', NULL, '又口占一頌 慧稜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa978067-bae9-40aa-b383-fdb823a3939d', '過三嶺苧溪', '過三嶺苧溪', '8c07c2ad-c545-4770-a1d5-5589dd8df8d2', '唐', '["世人休說行路難，鳥道羊腸咫尺間。","珍重苧溪溪[畔]（上）水，汝歸[滄]（蒼）海我歸山。","（《古今圖書集成·職方典》一○五二《泉州府部》〖2〗）（〖1〗《全唐詩》卷八八八收清豁詩一首，無傳，茲據《景德傳燈錄》卷二二、《宋詩紀事》卷九一補其事跡：清豁，福州永泰人，俗姓張。","嗣睡龍道溥禪師，住漳州保福院。","刺史陳洪進表奏，賜號性空禪師。","太平興國年卒。","原收入時）（代未詳僧，今移此。","〖2〗《景德傳燈錄》卷二二以此詩爲清豁「遺偈」，今據以校改。","）。"]', '["世人休说行路难，鸟道羊腸咫尺间。","珍重苧溪溪[畔]（上）水，汝归[滄]（蒼）海我归山。","（《古今圖书集成·職方典》一○五二《泉州府部》〖2〗）（〖1〗《全唐诗》卷八八八收清豁诗一首，無傳，茲據《景德傳灯錄》卷二二、《宋诗紀事》卷九一補其事跡：清豁，福州永泰人，俗姓張。","嗣睡龙道溥禪師，住漳州保福院。","刺史陳洪進表奏，賜號性空禪師。","太平兴国年卒。","原收入时）（代未詳僧，今移此。","〖2〗《景德傳灯錄》卷二二以此诗爲清豁「遺偈」，今據以校改。","）。"]', '诗', 'shi', '', NULL, '過三嶺苧溪 清豁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e10956-c420-4760-af10-87bd449b6d3b', '陽朔道中', '陽朔道中', '43670ba6-5549-4ba1-856c-b996f77afdf6', '唐', '["平原翠削萬瓊瑰，頓轡塵沙眼暫開。","文網牽人寧底急，未妨得意看山來。","（《全五代詩》六一）（〖1〗《古今圖書集成·職方典》卷一四○六《桂林府部》收此詩，題作《壽陽山》，第二句「暫」作「漸」，第四句「得意」作「特特」。","）。"]', '["平原翠削万瓊瑰，頓轡塵沙眼暫开。","文網牽人寧底急，未妨得意看山来。","（《全五代诗》六一）（〖1〗《古今圖书集成·職方典》卷一四○六《桂林府部》收此诗，題作《壽陽山》，第二句「暫」作「漸」，第四句「得意」作「特特」。","）。"]', '诗', 'shi', '', NULL, '陽朔道中 石仲元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b186db-bd03-4bf7-ab3b-8e317f071da8', '與何致雍僧貫徽聯句（馬希振爲鼎州節度使，馬氏諸子[中]白眉也。與門下客何致雍、僧貫徽聯句。） 一', '與何致雍僧貫徽聯句（马希振爲鼎州節度使，马氏諸子[中]白眉也。與门下客何致雍、僧貫徽聯句。） 一', '79a4a255-c9c2-47c1-b3f3-344b59f37371', '唐', '["青蛇每用腰爲力。","（希振）紅莧時將葉作花。","（貫徽）。"]', '["青蛇每用腰爲力。","（希振）紅莧时將葉作花。","（貫徽）。"]', '诗', 'shi', '', NULL, '與何致雍僧貫徽聯句（馬希振爲鼎州節度使，馬氏諸子[中]白眉也。與門下客何致雍、僧貫徽聯句。） 一 馬希振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bbbf8ad-f1f4-4faa-9a14-6d0e2fc16c37', '與何致雍僧貫徽聯句（馬希振爲鼎州節度使，馬氏諸子[中]白眉也。與門下客何致雍、僧貫徽聯句。） 二', '與何致雍僧貫徽聯句（马希振爲鼎州節度使，马氏諸子[中]白眉也。與门下客何致雍、僧貫徽聯句。） 二', '79a4a255-c9c2-47c1-b3f3-344b59f37371', '唐', '["蟻子子啣蟲子子。","（希振）猫兒兒捉雀兒兒。","（致雍）〖1〗（《五代詩話》六引《續歸田錄》〖2〗）（〖1〗《續歸田錄》謂此二句爲「又見蟻子緣砌」作。","〖2〗見《增修詩話總龜》卷二引《續歸田錄》。","）。"]', '["蟻子子啣蟲子子。","（希振）猫兒兒捉雀兒兒。","（致雍）〖1〗（《五代诗話》六引《續归田錄》〖2〗）（〖1〗《續归田錄》謂此二句爲「又见蟻子緣砌」作。","〖2〗见《增修诗話總龟》卷二引《續归田錄》。","）。"]', '诗', 'shi', '', NULL, '與何致雍僧貫徽聯句（馬希振爲鼎州節度使，馬氏諸子[中]白眉也。與門下客何致雍、僧貫徽聯句。） 二 馬希振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31aa39bf-09fe-41de-b6a7-b59f8a808b01', '潭州（諷楚王之侈）', '潭州（諷楚王之侈）', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["千里瀟湘琴瑟流，因思舊宅在鰲頭。","鑿開青帝春風浦，移下嫦娥夜月樓。","（《永樂大典》五七七○「沙」字韻）（今按：《全唐詩》只有後二句。","）。"]', '["千里瀟湘琴瑟流，因思旧宅在鰲头。","鑿开青帝春风浦，移下嫦娥夜月楼。","（《永乐大典》五七七○「沙」字韻）（今按：《全唐诗》只有後二句。","）。"]', '诗', 'shi', '', NULL, '潭州（諷楚王之侈） 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b079a815-2833-44e2-99cf-4173a2744032', '弔賈島（句）', '弔賈島（句）', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["江城賣藥常將鶴，古寺看碑不下驢。","（《五代詩話》引《南唐逸史》）（〖1〗見《增修詩話總龜》卷十一引《唐宋遺史》，云爲「王元贈詩」。","）。"]', '["江城賣藥常將鹤，古寺看碑不下驢。","（《五代诗話》引《南唐逸史》）（〖1〗见《增修诗話總龟》卷十一引《唐宋遺史》，云爲「王元贈诗」。","）。"]', '诗', 'shi', '', NULL, '弔賈島（句） 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba1b5c5-e0c7-43b6-ad17-f20e210f6186', '宿玉泉寺（句）', '宿玉泉寺（句）', '98012646-79ce-4856-8ef3-a56b7cb775de', '唐', '["山偷半庭月，池印一天星。","。"]', '["山偷半庭月，池印一天星。","。"]', '诗', 'shi', '', NULL, '宿玉泉寺（句） 曾弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b3f0f2-77d2-43b0-bfb0-298fb545994e', '君山（句）', '君山（句）', '98012646-79ce-4856-8ef3-a56b7cb775de', '唐', '["翠壓魚龍窟，寒堆波浪心。","（以上《詩話總龜》十四引《雅言系述》）（〖1〗楊億《武夷新集》卷八《劉氏太夫人天水縣太君趙氏墓碣銘》：「一女適曾弼，舉進士，終殿中丞。","」趙氏卒于景德二年，年八十六。","）。"]', '["翠壓鱼龙窟，寒堆波浪心。","（以上《诗話總龟》十四引《雅言系述》）（〖1〗楊億《武夷新集》卷八《劉氏太夫人天水縣太君趙氏墓碣銘》：「一女適曾弼，舉進士，終殿中丞。","」趙氏卒于景德二年，年八十六。","）。"]', '诗', 'shi', '', NULL, '君山（句） 曾弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d650475-d164-44c9-ad5a-5fe9581d0c89', '南越行（句）', '南越行（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["因尋買珠客，悮入射猿家。"]', '["因尋買珠客，悮入射猿家。"]', '诗', 'shi', '', NULL, '南越行（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a4ca91b-4b14-4dbf-ba1f-2795aca75b4d', '細雨（句）', '細雨（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["何處殘春夜，和花落古宮。","（「古」一作「漢」）。"]', '["何处殘春夜，和花落古宮。","（「古」一作「漢」）。"]', '诗', 'shi', '', NULL, '細雨（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdc4cfb-99a4-4ed3-8ae9-a36b31990da0', '途中逢宮人（句）', '途中逢宮人（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["孤舟半夜雨，上國十年心。","（以上《詩話總龜》十一《雅什門》引《雅言系述》）。"]', '["孤舟半夜雨，上国十年心。","（以上《诗話總龟》十一《雅什门》引《雅言系述》）。"]', '诗', 'shi', '', NULL, '途中逢宮人（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24e252c9-f609-4e38-9193-75ed60e274b7', '塞上曲（句）', '塞上曲（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["風高弓力大（一作「滿」），霜重角聲枯（一作「乾」）。"]', '["风高弓力大（一作「满」），霜重角声枯（一作「乾」）。"]', '诗', 'shi', '', NULL, '塞上曲（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60becc96-dabc-4abe-84c3-07542c09355a', '海中山（句）', '海中山（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["客帆來異域，別島落蟠桃。"]', '["客帆来異域，別島落蟠桃。"]', '诗', 'shi', '', NULL, '海中山（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065779d8-c07e-427a-916c-cb24a3dd8ec3', '中秋月（句）', '中秋月（句）', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["寒清萬國土，冷浸（一作鬦）四維根。","（以上《詩藪雜編》四）（〖1〗以上三題，均見《增修詩話總龜》卷十一引《雅言系述》。","）。"]', '["寒清万国土，冷浸（一作鬦）四維根。","（以上《诗藪杂編》四）（〖1〗以上三題，均见《增修诗話總龟》卷十一引《雅言系述》。","）。"]', '诗', 'shi', '', NULL, '中秋月（句） 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef8eef6-1b21-45ca-8493-2910319bd1b4', '鸂鶒', '鸂鶒', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["棲息應難近小池，性靈閒雅衆禽希。","蒲洲日暖依花立，漁浦烟深貼浪飛。","遺羽參差沾水沫，餘蹤稠疊印苔衣。","晚來林徑微風起，何處相呼著對歸。"]', '["棲息應难近小池，性靈閒雅衆禽希。","蒲洲日暖依花立，漁浦烟深貼浪飞。","遺羽參差沾水沫，餘蹤稠叠印苔衣。","晚来林徑微风起，何处相呼著对归。"]', '诗', 'shi', '', NULL, '鸂鶒 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae3bd8c-28dd-45bb-9e60-025b4af31375', '洪州西山（句）', '洪州西山（句）', '3d4601fc-f34c-487c-83be-b89ad8921a8e', '唐', '["林泉空有東西路，風月難尋十二家。","（以上《全五代詩》六二引《詩話總龜》）（〖1〗見《詩話總龜》卷三二引《拾遺》。","）。"]', '["林泉空有东西路，风月难尋十二家。","（以上《全五代诗》六二引《诗話總龟》）（〖1〗见《诗話總龟》卷三二引《拾遺》。","）。"]', '诗', 'shi', '', NULL, '洪州西山（句） 王鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2d6f5d-5d71-472d-95fe-ab95170066a1', '', '', '1deb69e2-fccf-43a6-b6ba-183f01eab1b9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 曹菘〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb2f854-ecd7-4fa8-b4c3-e78bdafa5d09', '題衡山尋仙觀（句）', '題衡山尋仙观（句）', '1deb69e2-fccf-43a6-b6ba-183f01eab1b9', '唐', '["千年松引東陵鶴，三級芝田草木香。"]', '["千年松引东陵鹤，三級芝田草木香。"]', '诗', 'shi', '', NULL, '題衡山尋仙觀（句） 曹菘〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85515f6a-e5ed-4428-a321-833ddb4fa503', '贈陳先生（句）', '贈陳先生（句）', '1deb69e2-fccf-43a6-b6ba-183f01eab1b9', '唐', '["讀《太玄經》秋醮罷，註《參同契》夜燈微。"]', '["读《太玄經》秋醮罷，註《參同契》夜灯微。"]', '诗', 'shi', '', NULL, '贈陳先生（句） 曹菘〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758a61a1-d9a5-4564-a194-7ada4b7a2b8c', '經羅大夫故居（句）', '經羅大夫故居（句）', '1deb69e2-fccf-43a6-b6ba-183f01eab1b9', '唐', '["鹿眠荒圃寒蕪白，鴉噪殘陽敗葉飛。","〖2〗（以上《詩話總龜》十四《警句門》引《雅言系述》）（〖1〗原作「松」，據《四部叢刊》影明本《增修詩話總龜》卷十四校改。","〖2〗《全唐詩》卷七一七據《錦繡萬花谷》誤收此詩於舒州人曹松名下。","）。"]', '["鹿眠荒圃寒蕪白，鴉噪殘陽敗葉飞。","〖2〗（以上《诗話總龟》十四《警句门》引《雅言系述》）（〖1〗原作「松」，據《四部叢刊》影明本《增修诗話總龟》卷十四校改。","〖2〗《全唐诗》卷七一七據《錦繡万花谷》誤收此诗於舒州人曹松名下。","）。"]', '诗', 'shi', '', NULL, '經羅大夫故居（句） 曹菘〖1〗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca222d7-a88f-4f58-a38f-24c727e0b5e0', '題君山', '題君山', '8ce9cfe1-ccb3-4e90-bcaf-79ece2a3a947', '唐', '["不礙揚帆路，盤根壓洞庭。","波濤四面白，雲外一堆青。","魚躍晴波動，龍歸石洞腥。","纔期託名畫，爲我簇爲屏。"]', '["不礙揚帆路，盤根壓洞庭。","波濤四面白，云外一堆青。","鱼躍晴波动，龙归石洞腥。","纔期託名畫，爲我簇爲屏。"]', '诗', 'shi', '', NULL, '題君山 任鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6049cbb-29f8-4edd-a0c6-6c176c705190', '送王正己歸山', '送王正己归山', '8ce9cfe1-ccb3-4e90-bcaf-79ece2a3a947', '唐', '["五峯青拄天，直下掛[飛]（龍）泉。","琴鶴同歸去，烟霞到處眠。","鼯跳霜葉徑，虎嘯夕陽川。","獨酌應懷我，排空樹影連。","（以上《詩話總龜》十五引《雅言雜載》）。"]', '["五峯青拄天，直下掛[飞]（龙）泉。","琴鹤同归去，烟霞到处眠。","鼯跳霜葉徑，虎嘯夕陽川。","独酌應懷我，排空樹影連。","（以上《诗話總龟》十五引《雅言杂載》）。"]', '诗', 'shi', '', NULL, '送王正己歸山 任鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2159bf3d-7927-4992-8c07-5499c498cabb', '題螺江廟', '題螺江廟', '08b51056-bf7b-403a-9734-87d8fff847f7', '唐', '["廟裏杉松蕭颯[風]（颯），廟前江水碧溶溶。","憑欄不見當時事，落日遠山千萬重。","（《詩藪雜編》四引《郡閣雅談》）（〖1〗見《增修詩話總龜》卷十六引《郡閣雅談》、《吟窗雜錄》卷四九引《江表志》。","據後書，陳誼應爲南唐時人。","）。"]', '["廟裏杉松蕭颯[风]（颯），廟前江水碧溶溶。","憑欄不见當时事，落日远山千万重。","（《诗藪杂編》四引《郡閣雅談》）（〖1〗见《增修诗話總龟》卷十六引《郡閣雅談》、《吟窗杂錄》卷四九引《江表志》。","據後书，陳誼應爲南唐时人。","）。"]', '诗', 'shi', '', NULL, '題螺江廟 陳誼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30040170-d2c8-4eca-8be2-f26ee6603fb6', '旅中（句）〖2〗', '旅中（句）〖2〗', '9aab706b-9a86-4771-bce9-6ce62ebf4529', '唐', '["未有一夜夢，不歸千里家。"]', '["未有一夜梦，不归千里家。"]', '诗', 'shi', '', NULL, '旅中（句）〖2〗 蔣維東 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a90107-6e68-41d5-9c3a-d9d0f7576390', '落花（句）', '落花（句）', '9aab706b-9a86-4771-bce9-6ce62ebf4529', '唐', '["流水從將去，春風解送來。","（以上《五代詩話》六引《零陵總記》〖3〗）（〖1〗宋馬永易《實賓錄》卷十一《山長》條云：「五代零陵蔣維東好學，能屬文。","乾祐中嘗隱居衡嶽，從而受業五十餘）（人，號維東爲山長云。","」〖2〗《詩話總龜》題作《旅中書懷》。","〖3〗見《增修詩話總龜》卷二十一引《零陵總記》。","）。"]', '["流水從將去，春风解送来。","（以上《五代诗話》六引《零陵總記》〖3〗）（〖1〗宋马永易《實賓錄》卷十一《山长》條云：「五代零陵蔣維东好学，能屬文。","乾祐中嘗隐居衡嶽，從而受業五十餘）（人，號維东爲山长云。","」〖2〗《诗話總龟》題作《旅中书懷》。","〖3〗见《增修诗話總龟》卷二十一引《零陵總記》。","）。"]', '诗', 'shi', '', NULL, '落花（句） 蔣維東 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a61177e-6476-4e9f-93b7-868b5c2d29ac', '句', '句', '93c34043-53df-4375-924c-1e76c2c9e855', '唐', '["甕中每醖逍遙藥，筆下閒偷造化功。","（《五代詩話》六引《圖畫見聞志》）（〖1〗見《圖畫見聞誌》卷二。","）。"]', '["甕中每醖逍遙藥，笔下閒偷造化功。","（《五代诗話》六引《圖畫见闻志》）（〖1〗见《圖畫见闻誌》卷二。","）。"]', '诗', 'shi', '', NULL, '句 胡擢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c226fca8-9dda-46d1-9d22-f19bc6fadb13', '送成務崇（宋初奄有金陵，孟賓于先居連上，嘏興國中亦自吉水還故鄉，逾年卒。書生成務崇因遊廬山，與嘏有忘年之分。興國中見嘏，且言自連上來遊江左，時有詩送成務崇云云。務崇詢於連上知交，皆言嘏卒已十餘矣。）', '送成務崇（宋初奄有金陵，孟賓于先居連上，嘏兴国中亦自吉水還故乡，逾年卒。书生成務崇因游廬山，與嘏有忘年之分。兴国中见嘏，且言自連上来游江左，时有诗送成務崇云云。務崇詢於連上知交，皆言嘏卒已十餘矣。）', 'be363c0a-bb57-4af8-a17e-cf1b3a03ce5a', '唐', '["同呼碧嶂前，已是十餘年。","話別非容易，相逢不偶然。","多爲詩酒役，早免利名牽。","幸有歸真路，何妨學上玄。","（《全五代詩》六五引《雅言雜載》〖2〗）（〖1〗「復捷江右士頗奇之」，《詩話總龜》作「後捷名，不欲止，江左士人頗奇之」。","〖2〗見《增修詩話總龜》卷四四引《雅言雜載》。","）。"]', '["同呼碧嶂前，已是十餘年。","話別非容易，相逢不偶然。","多爲诗酒役，早免利名牽。","幸有归真路，何妨学上玄。","（《全五代诗》六五引《雅言杂載》〖2〗）（〖1〗「复捷江右士頗奇之」，《诗話總龟》作「後捷名，不欲止，江左士人頗奇之」。","〖2〗见《增修诗話總龟》卷四四引《雅言杂載》。","）。"]', '诗', 'shi', '', NULL, '送成務崇（宋初奄有金陵，孟賓于先居連上，嘏興國中亦自吉水還故鄉，逾年卒。書生成務崇因遊廬山，與嘏有忘年之分。興國中見嘏，且言自連上來遊江左，時有詩送成務崇云云。務崇詢於連上知交，皆言嘏卒已十餘矣。） 孟嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2194fe-aa38-4650-8fd5-535f8f602950', '贈史虛白（句）', '贈史虛白（句）', 'be363c0a-bb57-4af8-a17e-cf1b3a03ce5a', '唐', '["詩酒獨遊寺，琴書多寄僧。","（《詩藪雜編》四引《郡閣雅談》）（〖1〗與前條同見《增修詩話總龜》引《雅言雜載》。","《詩藪》誤作《郡閣雅談》。","）。"]', '["诗酒独游寺，琴书多寄僧。","（《诗藪杂編》四引《郡閣雅談》）（〖1〗與前條同见《增修诗話總龟》引《雅言杂載》。","《诗藪》誤作《郡閣雅談》。","）。"]', '诗', 'shi', '', NULL, '贈史虛白（句） 孟嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b91b6491-9c12-4997-b32f-0f53f1da82d4', '題廬山瀑布', '題廬山瀑布', '2f8f7b7b-8580-4c0b-9723-7bfc05165479', '唐', '["正源人莫測，千尺掛雲端。","岳色染不得，神功裁亦難。","夏噴猿鳥浴，秋射斗牛寒。","流到滄溟日，翻濤更好看。","〖2〗。"]', '["正源人莫測，千尺掛云端。","岳色染不得，神功裁亦难。","夏噴猿鸟浴，秋射斗牛寒。","流到滄溟日，翻濤更好看。","〖2〗。"]', '诗', 'shi', '', NULL, '題廬山瀑布 陸蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('025d9797-e6d5-4f46-a5b1-dc31d5fcbdeb', '春暮經石頭城', '春暮經石头城', '2f8f7b7b-8580-4c0b-9723-7bfc05165479', '唐', '["六朝多少事，搘肘思悠悠。","落日空江上，子規啼渡頭。","蒹葭侵[壞]（廢）壘，烟霧接滄洲。","今古分明在，那堪向九秋？","（以上《詩話總龜》十五引《雅言雜載》）（〖1〗北宋釋契嵩《鐔津文集》卷十三有《陸蟾傳》，云蟾爲藤州鐔津人，有王霸大略，以能詩名於楚越間，後客死於攸縣司空山。","又引高閬語稱爲國初人。","〖2〗《陸蟾傳》所引，題作《瀑布詠》，「正源」作「靈源」，「浴」作「凝」，「射」作）（「濺」，「流」作「待」，「翻」作「爲」。","）。"]', '["六朝多少事，搘肘思悠悠。","落日空江上，子規啼渡头。","蒹葭侵[壞]（廢）壘，烟霧接滄洲。","今古分明在，那堪向九秋？","（以上《诗話總龟》十五引《雅言杂載》）（〖1〗北宋釋契嵩《鐔津文集》卷十三有《陸蟾傳》，云蟾爲藤州鐔津人，有王霸大略，以能诗名於楚越间，後客死於攸縣司空山。","又引高閬語稱爲国初人。","〖2〗《陸蟾傳》所引，題作《瀑布詠》，「正源」作「靈源」，「浴」作「凝」，「射」作）（「濺」，「流」作「待」，「翻」作「爲」。","）。"]', '诗', 'shi', '', NULL, '春暮經石頭城 陸蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96305df7-2115-41c6-832e-76d999dba34b', '司空山聞子規', '司空山闻子規', '2f8f7b7b-8580-4c0b-9723-7bfc05165479', '唐', '["後夜入清明，遊人何處聽？","花殘斑竹廟，雨歇峴山亭。","樹罅月欲落，窗間酒正醒。","衆鳥方在夢，誰念爾勞形？","（《詩話總龜》十一引《雅言系述》）。"]', '["後夜入清明，游人何处听？","花殘斑竹廟，雨歇峴山亭。","樹罅月欲落，窗间酒正醒。","衆鸟方在梦，誰念爾勞形？","（《诗話總龟》十一引《雅言系述》）。"]', '诗', 'shi', '', NULL, '司空山聞子規 陸蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341a0ea7-66b6-4828-bcd9-83605af64ff2', '題祝融峯（句）', '題祝融峯（句）', 'd8403200-6349-45fd-bc8f-bb19ce41b34e', '唐', '["開雲四邊盡，浮世一齊低。","（《五代詩話》七引《青瑣集》）（〖1〗見《青瑣高議前集》卷九。","栖巖，疑爲棲蟾之誤。","《全唐詩》卷八四八收其南嶽詩多首。","）。"]', '["开云四邊尽，浮世一齊低。","（《五代诗話》七引《青瑣集》）（〖1〗见《青瑣高議前集》卷九。","栖巖，疑爲棲蟾之誤。","《全唐诗》卷八四八收其南嶽诗多首。","）。"]', '诗', 'shi', '', NULL, '題祝融峯（句） 栖巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2aed8e8-1665-49bd-8c94-79323e44907f', '無事歌（長沙獄椽任福祖，[擁]〖推〗騶吏出行。有賣藥道人行吟云動。福祖審思，豈非異人，急遣訪求，已出城矣。）', '無事歌（长沙獄椽任福祖，[擁]〖推〗騶吏出行。有賣藥道人行吟云动。福祖審思，豈非異人，急遣訪求，已出城矣。）', '7c68f1c2-bf85-4e0f-805a-580bf5726ef0', '唐', '["無事歌，呵呵亦呵呵，哀哀亦呵呵。","不似荷葉參軍子，人人與箇拜[頃]木，大作廳上假閻羅。","（《清異錄》三）（〖1〗據商務排印本《說郛》卷六一引《清異錄》校補。","）。"]', '["無事歌，呵呵亦呵呵，哀哀亦呵呵。","不似荷葉參軍子，人人與箇拜[頃]木，大作廳上假閻羅。","（《清異錄》三）（〖1〗據商務排印本《说郛》卷六一引《清異錄》校補。","）。"]', '诗', 'shi', '', NULL, '無事歌（長沙獄椽任福祖，[擁]〖推〗騶吏出行。有賣藥道人行吟云動。福祖審思，豈非異人，急遣訪求，已出城矣。） 賣藥道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2b7f1a-89b5-4ef5-bdec-69b26b2ab364', '上成汭（句）（《全唐詩》七一九誤作路德延）（荆南舊有五花館，待賓之上地也。故蔣肱上成汭詩云：）', '上成汭（句）（《全唐诗》七一九誤作路德延）（荆南旧有五花館，待賓之上地也。故蔣肱上成汭诗云：）', '76e2ba6b-6a1e-4967-9dbc-9e1b49c1311f', '唐', '["不是上台名姓字，五花賓館敢（一作「收」）從容。","（《南部新書》癸）。"]', '["不是上台名姓字，五花賓館敢（一作「收」）從容。","（《南部新书》癸）。"]', '诗', 'shi', '', NULL, '上成汭（句）（《全唐詩》七一九誤作路德延）（荆南舊有五花館，待賓之上地也。故蔣肱上成汭詩云：） 蔣肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67e5849-f466-48d6-bdcd-13f7c4532bed', '爐火詩', '爐火诗', '95fa421a-5467-4fb9-9768-9c631f32d3f1', '唐', '["近冬附火爲泰火，透春擁爐成否爐。","用否隨時有輕重，進身君子合知無。","（《清異錄》一）。"]', '["近冬附火爲泰火，透春擁爐成否爐。","用否隨时有轻重，進身君子合知無。","（《清異錄》一）。"]', '诗', 'shi', '', NULL, '爐火詩 趙節 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4086b1d-c6e5-4270-b814-0d5e8050530d', '漳州', '漳州', '810a4a39-bb78-441b-8161-e6c8b25b2228', '唐', '["漳溪郡有佳山水，遷客因之作勝遊。","怪石千峯聳晴巘，枯槎百尺擁寒流。","（《輿地紀勝》一三一《漳州》）。"]', '["漳溪郡有佳山水，遷客因之作勝游。","怪石千峯聳晴巘，枯槎百尺擁寒流。","（《輿地紀勝》一三一《漳州》）。"]', '诗', 'shi', '', NULL, '漳州 史維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4f33ed-414e-41ba-85b0-f33b489aa093', '八公山（嘉慶志按《江南通志》引《綱目集覽》云：「山在壽春者，淮南王與八公憇處；在巢縣者，王遇八公處。」《方輿勝覽》以爲晉敗苻堅處，非是。）', '八公山（嘉慶志按《江南通志》引《綱目集覽》云：「山在壽春者，淮南王與八公憇处；在巢縣者，王遇八公处。」《方輿勝覽》以爲晉敗苻堅处，非是。）', 'b97e8d5d-eda7-420f-8657-caa2eedeabfb', '唐', '["幼度提晉師，胡卒驚鶴唳。","城外軍屯壘，可數不可計。","至今風雨夜，鬼哭雜異類。","（《光緒續修廬州府志》六《山川志》上）。"]', '["幼度提晉師，胡卒驚鹤唳。","城外軍屯壘，可數不可計。","至今风雨夜，鬼哭杂異類。","（《光緒續修廬州府志》六《山川志》上）。"]', '诗', 'shi', '', NULL, '八公山（嘉慶志按《江南通志》引《綱目集覽》云：「山在壽春者，淮南王與八公憇處；在巢縣者，王遇八公處。」《方輿勝覽》以爲晉敗苻堅處，非是。） 吳資 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30cc4f6-8810-416e-a7d2-bc248fd724b0', '教弩臺（《方輿勝覽》：教弩臺在懷德坊明教寺。舊經云：昔魏武帝築臺，教強弩五百人，以禦孫權櫂船。唐大曆間因得鐵佛高一丈八尺，刺史裴絹奏請爲寺。）', '教弩台（《方輿勝覽》：教弩台在懷德坊明教寺。旧經云：昔魏武帝築台，教強弩五百人，以禦孫權櫂船。唐大曆间因得鐵佛高一丈八尺，刺史裴絹奏請爲寺。）', 'b97e8d5d-eda7-420f-8657-caa2eedeabfb', '唐', '["曹公教弩臺，今爲比丘寺。","東門小河橋，曾飛吳主騎。","（同上十一《古蹟志》）（〖1〗裴絹，疑應作裴諝，詳《唐刺史考》卷一二九。","〖2〗《輿地紀勝》卷四五《廬州》收以上二詩，題作《合肥懷古》。","）。"]', '["曹公教弩台，今爲比丘寺。","东门小河橋，曾飞吳主騎。","（同上十一《古蹟志》）（〖1〗裴絹，疑應作裴諝，詳《唐刺史考》卷一二九。","〖2〗《輿地紀勝》卷四五《廬州》收以上二诗，題作《合肥懷古》。","）。"]', '诗', 'shi', '', NULL, '教弩臺（《方輿勝覽》：教弩臺在懷德坊明教寺。舊經云：昔魏武帝築臺，教強弩五百人，以禦孫權櫂船。唐大曆間因得鐵佛高一丈八尺，刺史裴絹奏請爲寺。） 吳資 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b1a89b0-b6cb-4235-85c9-e0bb6659931f', '遊北巖（句）', '游北巖（句）', 'e94e5d1f-67d4-4dd8-9ca8-d7477dc196e1', '唐', '["淮陽清淨理，永嘉山水心。","（《蜀中名勝記》八《成都府·資縣》）（〖1〗《新唐書·宰相世系表》趙郡李氏東祖房有李渭，爲長洲主簿李暄之子。","《蜀中名勝記》卷八引《蜀志補遺》云：「唐李渭爲刺史，有游山詩云〖詩略〗。","刻於等慈寺壁。","」另參後文。","〖2〗《輿地紀勝》卷一五七云：「李渭爲本州刺史，有詩刻留等慈寺。","時與前進士崔公輔同遊，崔有詩略曰：淮陽清靜理，永嘉山水心。","」二句詩頌揚刺史善政多才，以崔作爲近是。","崔公輔爲杜甫同時人，詳《全唐詩續拾》。","）。"]', '["淮陽清淨理，永嘉山水心。","（《蜀中名勝記》八《成都府·資縣》）（〖1〗《新唐书·宰相世系表》趙郡李氏东祖房有李渭，爲长洲主簿李暄之子。","《蜀中名勝記》卷八引《蜀志補遺》云：「唐李渭爲刺史，有游山诗云〖诗略〗。","刻於等慈寺壁。","」另參後文。","〖2〗《輿地紀勝》卷一五七云：「李渭爲本州刺史，有诗刻留等慈寺。","时與前進士崔公輔同游，崔有诗略曰：淮陽清静理，永嘉山水心。","」二句诗頌揚刺史善政多才，以崔作爲近是。","崔公輔爲杜甫同时人，詳《全唐诗續拾》。","）。"]', '诗', 'shi', '', NULL, '遊北巖（句） 李渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3ccff0-0113-43f9-837d-9abac7e0621e', '漢武帝祈仙臺（《三秦記》：「坊州橋山有漢武帝祈仙臺，高百尺。」李欽止題詩云：）', '漢武帝祈仙台（《三秦記》：「坊州橋山有漢武帝祈仙台，高百尺。」李欽止題诗云：）', 'a4373547-ef8c-498f-a0c1-f95f067a3080', '唐', '["四方禍結與兵連，海內空虛在末年。","謾築此臺高百尺，不知何處有神仙。","（《永樂大典》二六○四「臺」字韻）（〖1〗李欽止，疑非唐人。","《大典》殆據《類編長安志》卷三。","）。"]', '["四方禍結與兵連，海內空虛在末年。","謾築此台高百尺，不知何处有神仙。","（《永乐大典》二六○四「台」字韻）（〖1〗李欽止，疑非唐人。","《大典》殆據《類編长安志》卷三。","）。"]', '诗', 'shi', '', NULL, '漢武帝祈仙臺（《三秦記》：「坊州橋山有漢武帝祈仙臺，高百尺。」李欽止題詩云：） 李欽止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f526e6a7-07f4-413c-9972-ccde3ee16696', '丫頭山', '丫头山', 'a105ef3d-00cb-4cc6-a05f-6923290513fd', '唐', '["何不梳粧嫁去休，常教人喚作丫頭。","只因不信良媒說，躭閣千秋與萬秋。","（《古今圖書集成·職方典》二八四《黃州府志》）（〖1〗弘治《黃州府志》卷七作蘇軾詩。","）。"]', '["何不梳粧嫁去休，常教人喚作丫头。","只因不信良媒说，躭閣千秋與万秋。","（《古今圖书集成·職方典》二八四《黄州府志》）（〖1〗弘治《黄州府志》卷七作蘇軾诗。","）。"]', '诗', 'shi', '', NULL, '丫頭山 施逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ee4f3b-9f89-4274-b09e-624edb32d19e', '金華山', '金华山', '95ca9601-8a45-45d8-a77a-5428ebe7d53f', '唐', '["金華山色與天齊，一徑盤紆盡石梯。","步步前登清漢近，時時回首白雲低。","風偷藥氣名何限，水泛花光路即迷。","洞口數聲仙犬吠，始知羽客此真棲。","（《古今圖書集成·山川典》一二七《金華山部》）（〖1〗光緒《金華縣志》卷二稱袁吉爲「唐刺史」。","）。"]', '["金华山色與天齊，一徑盤紆尽石梯。","步步前登清漢近，时时回首白云低。","风偷藥氣名何限，水泛花光路即迷。","洞口數声仙犬吠，始知羽客此真棲。","（《古今圖书集成·山川典》一二七《金华山部》）（〖1〗光緒《金华縣志》卷二稱袁吉爲「唐刺史」。","）。"]', '诗', 'shi', '', NULL, '金華山 袁吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c6de80-194e-4b49-ba02-7906a662d2a0', '早春送郎官出宰（〖1〗《全唐詩》七八一作袁求賢詩○《文苑英華》一八九《省試》。）', '早春送郎官出宰（〖1〗《全唐诗》七八一作袁求賢诗○《文苑英华》一八九《省試》。）', '2d49b036-38a9-458c-ad3a-6c5ba0c98bb1', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '早春送郎官出宰（〖1〗《全唐詩》七八一作袁求賢詩○《文苑英華》一八九《省試》。） 張隨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce27afc0-578e-4a4e-b012-cd127ea2ae7f', '題透明巖安祿山題記後（透明巖，亦名棲真巖，在大蓬山。巖西曰禪窟，巖壁上有安祿山題記云：「大唐先天二年，歲在辛丑，七月朔，安祿山敬造彌勒佛一龕。」有清遠居士題其後云云。王象之按：「先天二年即開元元年，是時祿山尚未顯，以相傳之久，兼恐別有姓名偶同，姑兩存之。」）', '題透明巖安祿山題記後（透明巖，亦名棲真巖，在大蓬山。巖西曰禪窟，巖壁上有安祿山題記云：「大唐先天二年，歲在辛丑，七月朔，安祿山敬造彌勒佛一龕。」有清远居士題其後云云。王象之按：「先天二年即开元元年，是时祿山尚未显，以相傳之久，兼恐別有姓名偶同，姑兩存之。」）', '3c0fa440-6149-4098-8012-fe52f1866feb', '唐', '["妖胡作逆罪滔天，翠輦倉皇幸蜀川。","千載業緣磨不盡，卻來邀福向金仙。","（《輿地紀勝》一八八《蓬州·景物》及《碑記》）（〖1〗葉奕苞《金石錄補》卷十二云：「居士不知何許人。","顏魯公于虎邱題詠，同游者亦曰清遠，未知即其人否。","」）。"]', '["妖胡作逆罪滔天，翠輦倉皇幸蜀川。","千載業緣磨不尽，卻来邀福向金仙。","（《輿地紀勝》一八八《蓬州·景物》及《碑記》）（〖1〗葉奕苞《金石錄補》卷十二云：「居士不知何許人。","顏魯公于虎邱題詠，同游者亦曰清远，未知即其人否。","」）。"]', '诗', 'shi', '', NULL, '題透明巖安祿山題記後（透明巖，亦名棲真巖，在大蓬山。巖西曰禪窟，巖壁上有安祿山題記云：「大唐先天二年，歲在辛丑，七月朔，安祿山敬造彌勒佛一龕。」有清遠居士題其後云云。王象之按：「先天二年即開元元年，是時祿山尚未顯，以相傳之久，兼恐別有姓名偶同，姑兩存之。」） 清遠居士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b562768d-0124-4ef3-80ac-5db572989510', '子規（〖1〗《全唐詩》二六七作顧況詩○《文苑英華》三二九《禽獸》。）', '子規（〖1〗《全唐诗》二六七作顧況诗○《文苑英华》三二九《禽獸》。）', 'd5f2d220-d508-4f20-803b-49149e458736', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '子規（〖1〗《全唐詩》二六七作顧況詩○《文苑英華》三二九《禽獸》。） 楊逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016b1a8f-609d-4a68-a726-15ec4d499880', '題孟巖（句）', '題孟巖（句）', 'e78d3b25-9dd5-4fb8-b629-fd08c9376da8', '唐', '["郡雖饒勝境，偏愛此巖幽。","（《輿地紀勝》一五七《資州》）。"]', '["郡雖饒勝境，偏愛此巖幽。","（《輿地紀勝》一五七《資州》）。"]', '诗', 'shi', '', NULL, '題孟巖（句） 楊禹珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852f32f1-7ba3-4042-a277-e445d2871c0f', '和杜甫（句）', '和杜甫（句）', 'faa0e826-f274-4029-a6a3-996f12c6d2c6', '唐', '["莫嫌袍紫歸家阻，且慶豐年雅俗安。"]', '["莫嫌袍紫归家阻，且慶豐年雅俗安。"]', '诗', 'shi', '', NULL, '和杜甫（句） 楊興義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4f98d0-c5c0-4b82-9d7b-e60d3cb2bf7e', '題秋風（句）', '題秋风（句）', 'faa0e826-f274-4029-a6a3-996f12c6d2c6', '唐', '["霜風一夜將紅葉，換盡江頭萬木青。","（《蜀中名勝記》二五《保寧府·巴州》）（〖1〗《蜀中名勝記》稱「唐進士楊興義」。","）。"]', '["霜风一夜將紅葉，換尽江头万木青。","（《蜀中名勝記》二五《保寧府·巴州》）（〖1〗《蜀中名勝記》稱「唐進士楊兴義」。","）。"]', '诗', 'shi', '', NULL, '題秋風（句） 楊興義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83343b7b-71b9-4825-925e-4646a99af3af', '送尹蔓回睦州', '送尹蔓回睦州', '36b65e22-7815-49f7-a1a8-c485448b815f', '唐', '["憐君授衣月，遠作泛舟行。","江闊桐廬岸，山深建德城。","千尋喬木影，七里暮灘聲。","興盡當停櫂，臨流更濯纓。","（《嚴陵集》二）。"]', '["怜君授衣月，远作泛舟行。","江闊桐廬岸，山深建德城。","千尋喬木影，七里暮灘声。","兴尽當停櫂，臨流更濯纓。","（《嚴陵集》二）。"]', '诗', 'shi', '', NULL, '送尹蔓回睦州 厲翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2c1acb-09ef-4022-8203-731e6e2135b7', '贈妓（詳縱情詩酒，至廬江謁郡守，留連吟醉，因贈妓曰：）', '贈妓（詳縱情诗酒，至廬江謁郡守，留連吟醉，因贈妓曰：）', '39abcd64-f14e-4460-ae1a-d74aa0db5394', '唐', '["臺盤闊狹纔三尺，似隔中當有阻艱。","若不騎龍與騎鳳，樂營門是望夫山。","（《詩話總龜》二三《寓情門》引《南部新書》）（〖1〗《登科記考》卷二二載會昌四年登進士第者有鄭祥，漢南人，疑即此人。","）。"]', '["台盤闊狹纔三尺，似隔中當有阻艱。","若不騎龙與騎鳳，乐營门是望夫山。","（《诗話總龟》二三《寓情门》引《南部新书》）（〖1〗《登科記考》卷二二載會昌四年登進士第者有鄭祥，漢南人，疑即此人。","）。"]', '诗', 'shi', '', NULL, '贈妓（詳縱情詩酒，至廬江謁郡守，留連吟醉，因贈妓曰：） 鄭詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a1ef10-7277-4de7-ae22-89f4e1b22e9a', '題蓮花洞', '題蓮花洞', '17c5abae-8c50-401f-a00f-c4dae51a190f', '唐', '["路迴千曲繞芝田，羽客相擕訪謫仙。","石竇嵌空惟有跡，靈龕隱軫莫知年。","來居洞裏長無死，不出人間自有天。","更欲不眠吟至曉，恐驚龍動起愁烟。"]', '["路迴千曲繞芝田，羽客相擕訪謫仙。","石竇嵌空惟有跡，靈龕隐軫莫知年。","来居洞裏长無死，不出人间自有天。","更欲不眠吟至晓，恐驚龙动起愁烟。"]', '诗', 'shi', '', NULL, '題蓮花洞 獨孤均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2023a6c-5b68-4685-b357-59d03019f4da', '題含虛洞二首 一', '題含虛洞二首 一', '17c5abae-8c50-401f-a00f-c4dae51a190f', '唐', '["高樹猿啼亂水聲，尋幽不覺洞中行。","驪龍宿處雲常暗，羽客歸時路自明。","別後已迷舟竈火，迴來猶認玉童名。","從今已去朝金闕，便隔人間五百生。"]', '["高樹猿啼亂水声，尋幽不覺洞中行。","驪龙宿处云常暗，羽客归时路自明。","別後已迷舟竈火，迴来猶認玉童名。","從今已去朝金闕，便隔人间五百生。"]', '诗', 'shi', '', NULL, '題含虛洞二首 一 獨孤均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f43d1a-6964-4d74-9795-87de6eb9fa56', '題含虛洞二首 二', '題含虛洞二首 二', '17c5abae-8c50-401f-a00f-c4dae51a190f', '唐', '["捫蘿攀蹬步欹危，歷覽幽巖駭怪奇。","泉石膏肓傳亦久，神仙窟宅到何遲。","真人鹿引非無路，洞府龍升自有時。","但覺塵緣挹絕景，躊躇落筆媿題詩。","（以上《康熙徽州府志》二《婺源·山川》）（〖1〗光緒《婺源縣志》卷六十二作獨孤筠。","）。"]', '["捫蘿攀蹬步欹危，歷覽幽巖駭怪奇。","泉石膏肓傳亦久，神仙窟宅到何遲。","真人鹿引非無路，洞府龙升自有时。","但覺塵緣挹絕景，躊躇落笔媿題诗。","（以上《康熙徽州府志》二《婺源·山川》）（〖1〗光緒《婺源縣志》卷六十二作独孤筠。","）。"]', '诗', 'shi', '', NULL, '題含虛洞二首 二 獨孤均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb74feb5-8e64-418f-95f9-820a964fe84e', '經故宮女墳有感（二首） 一', '經故宮女墳有感（二首） 一', '080f9ba2-80ef-4672-bf02-2cb1276250a3', '唐', '["家國久隨狂虜沒，春蕪又向冢頭青。","如今憶得當時事，爲爾傷心一涕零。"]', '["家国久隨狂虜沒，春蕪又向冢头青。","如今憶得當时事，爲爾傷心一涕零。"]', '诗', 'shi', '', NULL, '經故宮女墳有感（二首） 一 聶通志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1645e4-33f0-4d9e-95a1-2c9c6a38e8a8', '經故宮女墳有感（二首） 二', '經故宮女墳有感（二首） 二', '080f9ba2-80ef-4672-bf02-2cb1276250a3', '唐', '["長郊煙淡月華清，因醉荒墳半夜醒。","失路孤吟不勝苦，暗中應有鬼神聽。","（《萬首唐人絕句》三五〖1〗）（〖1〗此指明趙宧光、黃習遠重訂本。","又見《才鬼記》卷七。","）。"]', '["长郊煙淡月华清，因醉荒墳半夜醒。","失路孤吟不勝苦，暗中應有鬼神听。","（《万首唐人絕句》三五〖1〗）（〖1〗此指明趙宧光、黄習远重訂本。","又见《才鬼記》卷七。","）。"]', '诗', 'shi', '', NULL, '經故宮女墳有感（二首） 二 聶通志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5318a98d-cde1-4889-a433-1dd4c4112d63', '沃洲山', '沃洲山', '0a87bf2b-05a4-4ca6-b2e3-6b2fd927da58', '唐', '["一聲清磬海邊月，十里香風澗底松。","何代沃洲今夜興，倚欄干聽赤城鐘。","（《輿地紀勝》四《紹興府》）（〖1〗《會稽掇英總集》卷四作魏徵詩，爲七律，此爲後四句。","然魏徵平生未及東南，詩律成熟，亦非初唐所宜有。","或另其魏證其人。","參《全唐詩續拾》卷一。","）。"]', '["一声清磬海邊月，十里香风澗底松。","何代沃洲今夜兴，倚欄干听赤城鐘。","（《輿地紀勝》四《紹兴府》）（〖1〗《會稽掇英總集》卷四作魏徵诗，爲七律，此爲後四句。","然魏徵平生未及东南，诗律成熟，亦非初唐所宜有。","或另其魏證其人。","參《全唐诗續拾》卷一。","）。"]', '诗', 'shi', '', NULL, '沃洲山 魏證 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be10538c-7b07-49f0-8066-49c2149cbd27', '送芝上人遊羅浮（二首） 一', '送芝上人游羅浮（二首） 一', '278a1f08-2292-471d-8d88-0a1f431901bf', '唐', '["一瓶一錫十方遊，揮塵湘南夜語投。","四百好峯在何許？寄師雙眼看羅浮。"]', '["一瓶一錫十方游，揮塵湘南夜語投。","四百好峯在何許？寄師雙眼看羅浮。"]', '诗', 'shi', '', NULL, '送芝上人遊羅浮（二首） 一 清範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c9d741-0425-43a6-bdd4-33aa18ea6476', '送芝上人遊羅浮（二首） 二', '送芝上人游羅浮（二首） 二', '278a1f08-2292-471d-8d88-0a1f431901bf', '唐', '["此身政坐愛名山，投老求閒可得閒。","遙夜相思千里月，想應騎虎度松關。","（《羅浮志》十《詩》）。"]', '["此身政坐愛名山，投老求閒可得閒。","遙夜相思千里月，想應騎虎度松关。","（《羅浮志》十《诗》）。"]', '诗', 'shi', '', NULL, '送芝上人遊羅浮（二首） 二 清範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001f83f2-243d-4c76-b569-10b83321ce4c', '雲門寺', '云门寺', 'b7eb5222-4bfb-45ac-96b2-061befeff3e8', '唐', '["若耶溪邊寺，幽勝絕塵囂。","一洞花將發，千巖雪未消。","依陰生徑竹，野色映溪橋。","漸賞登高處，鐘聲應寂寥。","（《古今圖書集成·山川典》一一四《雲門山部》）。"]', '["若耶溪邊寺，幽勝絕塵囂。","一洞花將發，千巖雪未消。","依陰生徑竹，野色映溪橋。","漸賞登高处，鐘声應寂寥。","（《古今圖书集成·山川典》一一四《云门山部》）。"]', '诗', 'shi', '', NULL, '雲門寺 德圓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7da7e2d-a225-448e-9b54-261ffb1fa8db', '望樊川', '望樊川', '4c77cb0c-0cd2-4538-8466-6a600081bb21', '唐', '["萬樹葉初紅，人家樹色中。","疎鐘搖雨足，積水浸雲容。","雪磧回寒雁，村燈促夜舂。","舊山歸未得，生計欲何從？","（《古今圖書集成·職方典》五二○《西安府部》）。"]', '["万樹葉初紅，人家樹色中。","疎鐘搖雨足，積水浸云容。","雪磧回寒雁，村灯促夜舂。","旧山归未得，生計欲何從？","（《古今圖书集成·職方典》五二○《西安府部》）。"]', '诗', 'shi', '', NULL, '望樊川 澹交 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86693ac7-1c93-4ce3-9b7e-2d4a99b81fb6', '江亭晚眺', '江亭晚眺', 'b7b1fcc4-f4be-4395-b97f-b8babd019122', '唐', '["獨隱清江秋思長，晚潮初上水亭凉。","海門雲起雙巒暝，一抹銀花影夕陽。","（《古今圖書集成·職方典》七八五《安慶府部》）。"]', '["独隐清江秋思长，晚潮初上水亭凉。","海门云起雙巒暝，一抹銀花影夕陽。","（《古今圖书集成·職方典》七八五《安慶府部》）。"]', '诗', 'shi', '', NULL, '江亭晚眺 覺隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efae1f8-4f02-4d6a-a6ca-b12e52c17d30', '戰城南', '戰城南', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["戰地何昏昏，戰士如羣蟻。","氣重日輪紅，血染蓬蒿紫。","烏鳥銜人肉，食悶飛不起。","昨日城上人，今日城下鬼。","旗色如羅星，鼙聲殊未已。","妾家夫與兒，俱在鼙聲裏。","（《文苑英華》一九六《樂府》）。"]', '["戰地何昏昏，戰士如羣蟻。","氣重日輪紅，血染蓬蒿紫。","烏鸟銜人肉，食悶飞不起。","昨日城上人，今日城下鬼。","旗色如羅星，鼙声殊未已。","妾家夫與兒，俱在鼙声裏。","（《文苑英华》一九六《乐府》）。"]', '诗', 'shi', '', NULL, '戰城南 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb33277-9207-40bc-9931-3df35a1ba329', '昭君怨', '昭君怨', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["銜悲出漢關，落淚灑胡鞍。","關榆三夏凍，塞柳九春寒。","眉任愁中結，腰隨帶裏寬。","別曲易悽斷，哀絃不忍彈。","（同上二○四《樂府》）。"]', '["銜悲出漢关，落泪灑胡鞍。","关榆三夏凍，塞柳九春寒。","眉任愁中結，腰隨带裏寬。","別曲易悽斷，哀絃不忍彈。","（同上二○四《乐府》）。"]', '诗', 'shi', '', NULL, '昭君怨 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e41acb8-237e-44a7-b1b6-4bb29c91721e', '採菱女', '採菱女', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白日期何去？青春只自矜。","艷歌呈幾曲，江畔采新菱，望浦思同濟，輕舟喜共乘。","翠（一作葉）將眉比色，聲與調相應。","蕩漾微波散，清泠遠水澄。","更看池際影，若對玉壺冰。","（同上二○八《樂府》）。"]', '["白日期何去？青春只自矜。","艷歌呈幾曲，江畔采新菱，望浦思同濟，轻舟喜共乘。","翠（一作葉）將眉比色，声與調相應。","蕩漾微波散，清泠远水澄。","更看池際影，若对玉壺冰。","（同上二○八《乐府》）。"]', '诗', 'shi', '', NULL, '採菱女 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836a6f2a-6961-4c01-b1ec-10fc4cf535b7', '分柑子歌示諸小', '分柑子歌示諸小', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["癡男騃女愁殺人，偏呼小者大者嗔。","粗衣糲食盡須一，何況異味兼時新。","今朝樓下[柑]（甘）初熟，摘得一筐分不足。","兒童豈待父母施，自各捻來（一作「各自捻將」）獻兄叔。","就中小女有所翳，（下缺）（同上三三七《歌行》）。"]', '["癡男騃女愁殺人，偏呼小者大者嗔。","粗衣糲食尽須一，何況異味兼时新。","今朝楼下[柑]（甘）初熟，摘得一筐分不足。","兒童豈待父母施，自各捻来（一作「各自捻將」）獻兄叔。","就中小女有所翳，（下缺）（同上三三七《歌行》）。"]', '诗', 'shi', '', NULL, '分柑子歌示諸小 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2cac32e-a99f-494f-b723-a3883968022e', '哭從伯祭酒', '哭從伯祭酒', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["剖符馮翊次，以疾拜司成。","義重疎皆友，仁深怨不生。","昔居南比省，長話水雲情。","吟諷資高興，絲綸發重名。","經秋漳浦臥，一旦逝川聲。","自古誰迴得，重泉獨往程。","明靈辭魏闕，冬日冷秦宮。","〖1〗孝子號天護，銘旌引柩行。","門闌容足跡，章句許才清。","劣薄無因報，恩知豈謂輕？","捫膺詞莫吐，奠酒淚先傾。","從此階前石，何人肯念貞？","（愚魯獻孤石蒙賞孤峭。","同上三○四《悲悼》）（〖1〗「宮」字不韻，趙遂之校作「庭」。","）。"]', '["剖符馮翊次，以疾拜司成。","義重疎皆友，仁深怨不生。","昔居南比省，长話水云情。","吟諷資高兴，絲綸發重名。","經秋漳浦臥，一旦逝川声。","自古誰迴得，重泉独往程。","明靈辞魏闕，冬日冷秦宮。","〖1〗孝子號天護，銘旌引柩行。","门闌容足跡，章句許才清。","劣薄無因報，恩知豈謂轻？","捫膺词莫吐，奠酒泪先傾。","從此階前石，何人肯念貞？","（愚魯獻孤石蒙賞孤峭。","同上三○四《悲悼》）（〖1〗「宮」字不韻，趙遂之校作「庭」。","）。"]', '诗', 'shi', '', NULL, '哭從伯祭酒 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c317a4-b873-4a4c-899d-34ea248ab177', '雜詩', '杂诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舊山雖在不關身，且向長安過暮春。","一樹梨花一溪月，不知今夜屬何人？","（《萬首唐人絕句》三八）。"]', '["旧山雖在不关身，且向长安過暮春。","一樹梨花一溪月，不知今夜屬何人？","（《万首唐人絕句》三八）。"]', '诗', 'shi', '', NULL, '雜詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a33868-18a0-4b37-af7f-111993425d24', '碧玉潭（潭在武康西一十里響應山之下，唐人有詩刻於岩上云：）', '碧玉潭（潭在武康西一十里响應山之下，唐人有诗刻於岩上云：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["水面平鋪映碧空，夜深明月照龍宮。","猿啼未響潭先響，一樹花開兩樹紅。","（《輿地紀勝》四《安吉州·景物》）。"]', '["水面平鋪映碧空，夜深明月照龙宮。","猿啼未响潭先响，一樹花开兩樹紅。","（《輿地紀勝》四《安吉州·景物》）。"]', '诗', 'shi', '', NULL, '碧玉潭（潭在武康西一十里響應山之下，唐人有詩刻於岩上云：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8348381e-a0a5-430e-8924-86d6d98a0510', '子陵山洞（在京山縣南六十里，即嚴子陵隱所也。傍有石室名帝星井，寺曰淨安，嘗有一星，光芒見井中。昔人賦詩云：）', '子陵山洞（在京山縣南六十里，即嚴子陵隐所也。傍有石室名帝星井，寺曰淨安，嘗有一星，光芒见井中。昔人賦诗云：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["翩翩釣臺翁，弊屣棄利祿。","煙溪七里瀨，風月一竿竹。","平生知己誰？故人劉文叔。","三聘乃肯來，公卿指爲辱。","高風輕萬乘，敢以足加腹。","居然動天象，下應太史卜。"]', '["翩翩釣台翁，弊屣棄利祿。","煙溪七里瀨，风月一竿竹。","平生知己誰？故人劉文叔。","三聘乃肯来，公卿指爲辱。","高风轻万乘，敢以足加腹。","居然动天象，下應太史卜。"]', '诗', 'shi', '', NULL, '子陵山洞（在京山縣南六十里，即嚴子陵隱所也。傍有石室名帝星井，寺曰淨安，嘗有一星，光芒見井中。昔人賦詩云：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbe1f71-08eb-463b-9ad3-4158f76d1857', '帝星井', '帝星井', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["帝星胡爲落此間？豈非此有子陵山。","蒼蒼珉井一百丈，至今深夜光芒寒。","野老相傳是陳迹，斷碑摸索苔蘚斑。","往事恍惚不可問，青山綠水空潺潺。","（以上《輿地紀勝》八四《郢州·古跡》。","後一首又見《古文圖書集成·職方典》一一四七《安陸府部》）。"]', '["帝星胡爲落此间？豈非此有子陵山。","蒼蒼珉井一百丈，至今深夜光芒寒。","野老相傳是陳迹，斷碑摸索苔蘚斑。","往事恍惚不可问，青山綠水空潺潺。","（以上《輿地紀勝》八四《郢州·古跡》。","後一首又见《古文圖书集成·職方典》一一四七《安陸府部》）。"]', '诗', 'shi', '', NULL, '帝星井 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963854b4-72b8-4f29-b5ba-a732baaf3c08', '小桃源（曩有耕于小桃源得一銅牌，牌上有詩一絕云：）', '小桃源（曩有耕于小桃源得一銅牌，牌上有诗一絕云：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["綽約去朝真，仙源萬木春。","要知竊桃客，定是會（一作滑）稽人。","（《輿地紀勝》一六六《長寧軍》）。"]', '["綽約去朝真，仙源万木春。","要知竊桃客，定是會（一作滑）稽人。","（《輿地紀勝》一六六《长寧軍》）。"]', '诗', 'shi', '', NULL, '小桃源（曩有耕于小桃源得一銅牌，牌上有詩一絕云：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e51954-4f59-4be2-96c0-ef037035a741', '題靈鷲', '題靈鷲', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靈鷲名山萬古名，幾回無事繞廊行。","殿前流水晴尤急，塔上春雲晚自生。","鶴傍經牀聽梵語，鳥窺齋鉢候鐘聲。","我來借得蒲團坐，歸去閒眠夢亦清。","（《咸淳臨安志》八○《寺觀》）。"]', '["靈鷲名山万古名，幾回無事繞廊行。","殿前流水晴尤急，塔上春云晚自生。","鹤傍經牀听梵語，鸟窺斋鉢候鐘声。","我来借得蒲團坐，归去閒眠梦亦清。","（《咸淳臨安志》八○《寺观》）。"]', '诗', 'shi', '', NULL, '題靈鷲 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f73717-bbe4-4463-9bdb-4652505e9a78', '平蓋山', '平蓋山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["平蓋山高古木疎，昔人曾此築仙居。","井通八角寒泉湧，觀燬三清劫火餘。","洗墨池邊丹竈冷，繫龍巖畔石潭虛。","吟成獨坐荒苔上，閑看蝸牛學篆書。","（《蜀中名勝記》十二《眉州彭山縣》）。"]', '["平蓋山高古木疎，昔人曾此築仙居。","井通八角寒泉湧，观燬三清劫火餘。","洗墨池邊丹竈冷，繫龙巖畔石潭虛。","吟成独坐荒苔上，闲看蝸牛学篆书。","（《蜀中名勝記》十二《眉州彭山縣》）。"]', '诗', 'shi', '', NULL, '平蓋山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd72b7ee-16c7-40f1-8c4a-3bc9996df510', '洞真觀（在酃縣北）', '洞真观（在酃縣北）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉洞瑤壇長冷落，真虛崖竇色常新。","可憐城裏悠悠者，不識瀟湘四季春。","（同治《湖南通志》二三九《方外志·寺觀》）。"]', '["玉洞瑤壇长冷落，真虛崖竇色常新。","可怜城裏悠悠者，不識瀟湘四季春。","（同治《湖南通志》二三九《方外志·寺观》）。"]', '诗', 'shi', '', NULL, '洞真觀（在酃縣北） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cdf8a1-da94-46c6-b028-cd1d5bf8f410', '滄浪寺（在沅江縣南三十里）', '滄浪寺（在沅江縣南三十里）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["閒步滄浪野，棲禪竹作扉。","浮生自有樂，塵慮總皆非。","（同上二四○）。"]', '["閒步滄浪野，棲禪竹作扉。","浮生自有乐，塵慮總皆非。","（同上二四○）。"]', '诗', 'shi', '', NULL, '滄浪寺（在沅江縣南三十里） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0673865-dc44-4c08-b8bc-c570d541a1e5', '玉乳泉壁間詩', '玉乳泉壁间诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["騎馬出門三月暮，楊花無奈雪漫天。","客情最苦夜難度，宿處先尋無杜鵑。","（《重修丹陽縣志》三四《藝文》）。"]', '["騎马出门三月暮，楊花無奈雪漫天。","客情最苦夜难度，宿处先尋無杜鵑。","（《重修丹陽縣志》三四《藝文》）。"]', '诗', 'shi', '', NULL, '玉乳泉壁間詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea6bf55-bb1f-4e34-a8b5-c155b00e29eb', '楚泊亭（二首） 一', '楚泊亭（二首） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天垂六幕水浮空，霽月光風上下同。","我向山頭一舒笑，楚人還望白雲中。"]', '["天垂六幕水浮空，霽月光风上下同。","我向山头一舒笑，楚人還望白云中。"]', '诗', 'shi', '', NULL, '楚泊亭（二首） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcfa5f70-2303-4859-9233-affe09c218a1', '楚泊亭（二首） 二', '楚泊亭（二首） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["卷逃屈放兩俱空，山止波流萬古同。","美惡不隨天地老，斷魂啼鳥一聲中。","（《嘉靖常德府志》十九《賦詠》）。"]', '["卷逃屈放兩俱空，山止波流万古同。","美惡不隨天地老，斷魂啼鸟一声中。","（《嘉靖常德府志》十九《賦詠》）。"]', '诗', 'shi', '', NULL, '楚泊亭（二首） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d23c33fa-50bb-4649-8c81-dd0249304c42', '黃金臺', '黄金台', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["燕昭北築黃金臺，四方豪傑乘風來。","秦家燒書殺儒客，肘腋之間千里隔。","去年八月幽州道，昭君墓前哭秋草。","今年五月咸陽關，秦家城外悲河山。","河上關頭車馬路，殘日青烟五陵樹。","（見元人王惲《秋澗集》。","《古今圖書集成·職方典》二九《順天府部》亦載此詩，題作《燕臺》）。"]', '["燕昭北築黄金台，四方豪傑乘风来。","秦家燒书殺儒客，肘腋之间千里隔。","去年八月幽州道，昭君墓前哭秋草。","今年五月咸陽关，秦家城外悲河山。","河上关头车马路，殘日青烟五陵樹。","（见元人王惲《秋澗集》。","《古今圖书集成·職方典》二九《順天府部》亦載此诗，題作《燕台》）。"]', '诗', 'shi', '', NULL, '黃金臺 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff03a664-b0f6-4892-a765-75001fe9db07', '題仙人洞石鐘', '題仙人洞石鐘', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["我欲扣石鐘，驚起洞中人。","烟蘿杳無際，空鎖石門春。","石洞何窈窕，云是仙人庭。","仙人渺何許？瑤草空自青。","石洞窅且深，花落無人掃。","仙翁去不還，何處尋瑤草。"]', '["我欲扣石鐘，驚起洞中人。","烟蘿杳無際，空鎖石门春。","石洞何窈窕，云是仙人庭。","仙人渺何許？瑤草空自青。","石洞窅且深，花落無人掃。","仙翁去不還，何处尋瑤草。"]', '诗', 'shi', '', NULL, '題仙人洞石鐘 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10378f5-4993-4a7b-a40b-a6b3e1f1ffc0', '盤山', '盤山', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["盤山高巍峩，半入青雲裏。","中間最上峯，更向天邊起。","行行白石崖，六月不知暑。"]', '["盤山高巍峩，半入青云裏。","中间最上峯，更向天邊起。","行行白石崖，六月不知暑。"]', '诗', 'shi', '', NULL, '盤山 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717341b6-340c-45a7-9c59-d1dfdde91f69', '題薊州桃李寺', '題薊州桃李寺', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舊有桃花樹，人呼寺故云。","石危秋鷺上，灘遠夜僧聞。","汲井連黃葉，登臺散白雲。","燒丹勾漏合，無處不逢君。","（以上孫承澤《天府廣記》四二《失名唐人詩》，見石刻。","）。"]', '["旧有桃花樹，人呼寺故云。","石危秋鷺上，灘远夜僧闻。","汲井連黄葉，登台散白云。","燒丹勾漏合，無处不逢君。","（以上孫承澤《天府廣記》四二《失名唐人诗》，见石刻。","）。"]', '诗', 'shi', '', NULL, '題薊州桃李寺 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce10a39-231e-4556-a718-776d7710cdcf', '魯陽城', '魯陽城', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["豢術緣何竟醢龍，因遷僻壤隔雲封。","山迷故國芙蓉秀，水瀉沙河玳瑁封。","離黍何須發浩歎，荒城久矣屬空墉。","獨憐遼鶴歸何處，漫向深芊聽曉鐘。"]', '["豢術緣何竟醢龙，因遷僻壤隔云封。","山迷故国芙蓉秀，水瀉沙河玳瑁封。","離黍何須發浩歎，荒城久矣屬空墉。","独怜遼鹤归何处，漫向深芊听晓鐘。"]', '诗', 'shi', '', NULL, '魯陽城 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02aee58e-fa25-4aad-895a-07fee6a020c8', '思父臺', '思父台', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["駐馬空山親舍迷，不堪回首白雲低。","王師爲國驅鋒鏑，爭向兒家杖履追。","（以上《古今圖書集成·職方典》四八八《汝州部》）。"]', '["駐马空山親舍迷，不堪回首白云低。","王師爲国驱鋒鏑，爭向兒家杖履追。","（以上《古今圖书集成·職方典》四八八《汝州部》）。"]', '诗', 'shi', '', NULL, '思父臺 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43bb96b2-44c4-4cf1-85f4-26b517ccc4ab', '桃川宮（方士，失名）', '桃川宮（方士，失名）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["流水迴環日夕澄，烟蘿石壁四時新。","清風臺上生瑤草，夜雨松根老茯苓。","九轉丹砂龍虎伏，千年劍氣鬼神驚。","道人今向蓬萊去，白鶴歸來月滿庭。","（同上一二六二《常德府部》。","又同治《湖南通志》二四○《方外志·寺觀·桃源縣》）。"]', '["流水迴环日夕澄，烟蘿石壁四时新。","清风台上生瑤草，夜雨松根老茯苓。","九轉丹砂龙虎伏，千年劍氣鬼神驚。","道人今向蓬萊去，白鹤归来月满庭。","（同上一二六二《常德府部》。","又同治《湖南通志》二四○《方外志·寺观·桃源縣》）。"]', '诗', 'shi', '', NULL, '桃川宮（方士，失名） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd62b47-71db-42e8-a718-d7118fcaefad', '聖壽寺（三首） 一', '聖壽寺（三首） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["石罅題詩紀別年，風煙南北各凄然。","薝蒲坐我靈山下，猶借高人半日緣。","。"]', '["石罅題诗紀別年，风煙南北各凄然。","薝蒲坐我靈山下，猶借高人半日緣。","。"]', '诗', 'shi', '', NULL, '聖壽寺（三首） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e30b2637-afab-4eef-a082-13e0a4925325', '聖壽寺（三首） 二', '聖壽寺（三首） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夕籟鳴寒雨，晴峯出翠屏。","風塵吾獨愧，鴻鵠下蒼冥。"]', '["夕籟鳴寒雨，晴峯出翠屏。","风塵吾独愧，鴻鵠下蒼冥。"]', '诗', 'shi', '', NULL, '聖壽寺（三首） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc8e41ab-2104-4a67-bf1d-d54d7911ce13', '聖壽寺（三首） 三', '聖壽寺（三首） 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["趺坐叢林下，朗吟白石巔。","一丘盤曲處，中有老龍眠。","（《古今圖書集成·職方典》一○八五《興化府部》）。"]', '["趺坐叢林下，朗吟白石巔。","一丘盤曲处，中有老龙眠。","（《古今圖书集成·職方典》一○八五《兴化府部》）。"]', '诗', 'shi', '', NULL, '聖壽寺（三首） 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d89dd51-024f-42ae-b982-582607d1afc0', '寒亭', '寒亭', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["朔風凜凜雪漫漫，未是寒亭分外寒。","六月火雲天不雨，請君來此凭欄杆。","（同上一一四七《安陸府部》）。"]', '["朔风凜凜雪漫漫，未是寒亭分外寒。","六月火云天不雨，請君来此凭欄杆。","（同上一一四七《安陸府部》）。"]', '诗', 'shi', '', NULL, '寒亭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24fcc6fa-3893-47bd-9886-031f8d945bf2', '緱山廟', '緱山廟', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["獨挹榴花夜向闌，詩情高寄碧雲間。","不知鶴駕人何在，笙月亭亭滿故山。","（同上《山川典》六三《緱山部》）。"]', '["独挹榴花夜向闌，诗情高寄碧云间。","不知鹤駕人何在，笙月亭亭满故山。","（同上《山川典》六三《緱山部》）。"]', '诗', 'shi', '', NULL, '緱山廟 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b443a3-f922-47bf-9dd1-b192f57b2c92', '牡丹', '牡丹', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["傾國姿容別，多開富貴家。","臨軒一賞後，輕薄萬千花。","（同上《草木典》二八九《牡丹部》）。"]', '["傾国姿容別，多开富貴家。","臨軒一賞後，轻薄万千花。","（同上《草木典》二八九《牡丹部》）。"]', '诗', 'shi', '', NULL, '牡丹 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3346ed12-7292-4b23-b424-43c55d317230', '紀信墓', '紀信墓', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["紀信生降爲沛公，草荒古塚臥秋風。","不知青史緣何事，却道蕭何第一功。","（乾隆《直隸秦州新志》十一《藝文·詩》）。"]', '["紀信生降爲沛公，草荒古塚臥秋风。","不知青史緣何事，却道蕭何第一功。","（乾隆《直隸秦州新志》十一《藝文·诗》）。"]', '诗', 'shi', '', NULL, '紀信墓 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f073e5e-3332-43ba-84e5-d58a84d6469c', '卻鬼丸', '卻鬼丸', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["走鹿枯風吼夜闌，頌花還喜向椒盤。","人情此日非前日，歲事新官對舊官。","竹[葉]（裏）莫辭終日醉，梅花已拚隔年看。","書生但恐寒爲祟，不用朱泥卻鬼丹。","（《歲時廣記》五《元旦》）。"]', '["走鹿枯风吼夜闌，頌花還喜向椒盤。","人情此日非前日，歲事新官对旧官。","竹[葉]（裏）莫辞終日醉，梅花已拚隔年看。","书生但恐寒爲祟，不用朱泥卻鬼丹。","（《歲时廣記》五《元旦》）。"]', '诗', 'shi', '', NULL, '卻鬼丸 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e65f08f-1554-4767-b57d-565458cb4688', '上元詞（句）', '上元词（句）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["金吾不禁元宵，漏聲更莫催曉。","（同上十《上元》引《唐西京新記》）。"]', '["金吾不禁元宵，漏声更莫催晓。","（同上十《上元》引《唐西京新記》）。"]', '诗', 'shi', '', NULL, '上元詞（句） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd7fe047-0998-474d-8d86-fe924ebef7f0', '中秋詩（句）', '中秋诗（句）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["端正月臨端正樹，韻香人在韻香樓。","（端正樹，韻香樓，皆明皇故事。","同上三一《中秋》）。"]', '["端正月臨端正樹，韻香人在韻香楼。","（端正樹，韻香楼，皆明皇故事。","同上三一《中秋》）。"]', '诗', 'shi', '', NULL, '中秋詩（句） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3366b90-982f-41a7-8f35-8bd03af193bd', '句（東坡曰：「此唐人得意句。」）', '句（东坡曰：「此唐人得意句。」）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一鳩鳴午寂，雙燕話春愁。","（《苕溪漁隱叢話前集》二四引《西清詩話》）。"]', '["一鳩鳴午寂，雙燕話春愁。","（《苕溪漁隐叢話前集》二四引《西清诗話》）。"]', '诗', 'shi', '', NULL, '句（東坡曰：「此唐人得意句。」） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d13d20-e5b4-4053-b62f-6f975e509216', '簡池（句）（簡池獨劉氏三溪號一郡之勝。）', '簡池（句）（簡池独劉氏三溪號一郡之勝。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["入蜀最宜遊簡郡，尋山須是訪劉家。","（《輿地紀勝》一四五《簡州》）（〖1〗詩後原注：「此古詩也，簡池獨劉氏三溪號一郡之勝。","」劉氏指劉昊，北宋天聖中人，其先人唐僖宗時遷簡州。","）。"]', '["入蜀最宜游簡郡，尋山須是訪劉家。","（《輿地紀勝》一四五《簡州》）（〖1〗诗後原注：「此古诗也，簡池独劉氏三溪號一郡之勝。","」劉氏指劉昊，北宋天聖中人，其先人唐僖宗时遷簡州。","）。"]', '诗', 'shi', '', NULL, '簡池（句）（簡池獨劉氏三溪號一郡之勝。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2023f70-3180-4c7e-8eba-dde06a65cf5e', '東周詩（句）', '东周诗（句）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鍾會壘邊山月白，武侯橋畔水風清。","（同上一八六《隆慶府》）。"]', '["鍾會壘邊山月白，武侯橋畔水风清。","（同上一八六《隆慶府》）。"]', '诗', 'shi', '', NULL, '東周詩（句） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f84c64f-0f77-460b-a3ce-cd5eba6da80d', '任氏行（句二） 一', '任氏行（句二） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蘭膏新沐雲鬢滑，寶釵斜墜青絲髮。"]', '["蘭膏新沐云鬢滑，寶釵斜墜青絲髮。"]', '诗', 'shi', '', NULL, '任氏行（句二） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6ebaaa-4bef-4579-a66e-4cba011d8bf7', '任氏行（句二） 二', '任氏行（句二） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["蟬鬢尚隨雲勢動，素衣猶帶月光來。","（《錦繡萬花谷》十七）（〖1〗日本大江維時《千載佳句》謂《任氏行》爲白居易作。","）。"]', '["蟬鬢尚隨云勢动，素衣猶带月光来。","（《錦繡万花谷》十七）（〖1〗日本大江維时《千載佳句》謂《任氏行》爲白居易作。","）。"]', '诗', 'shi', '', NULL, '任氏行（句二） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311ca584-0c50-4d76-8cf6-e55f462ee9c2', '奉和詠雪應制（和太宗）', '奉和詠雪應制（和太宗）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["寒雲垂廣幕，飄霰下天津。","無轍方秪至，有感瑞氣新。","色映姑山質，舞對洛川神。","忽奉瑤池韻，漸和郢中春。","（《文苑英華》一七三《應制》）。"]', '["寒云垂廣幕，飄霰下天津。","無轍方秪至，有感瑞氣新。","色映姑山質，舞对洛川神。","忽奉瑤池韻，漸和郢中春。","（《文苑英华》一七三《應制》）。"]', '诗', 'shi', '', NULL, '奉和詠雪應制（和太宗） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e20fd4a-81e6-4ff1-84a1-6e16dca514c4', '句（開元中，有儒士登終南山，得句云：「野迥雲根闊，山高樹影長。」私心自負，吟諷之際，忽聞空中語云：「未若天河云云。」儒士不勝喜，以爲己有。歸誇於僧，智潛掩鼻笑曰：「臭氣可掬，何足多也。」儒士驚愕，遽以實告。自此又號爲鑑文大師，有《浮漚篇》行於世。）', '句（开元中，有儒士登終南山，得句云：「野迥云根闊，山高樹影长。」私心自負，吟諷之際，忽闻空中語云：「未若天河云云。」儒士不勝喜，以爲己有。归誇於僧，智潛掩鼻笑曰：「臭氣可掬，何足多也。」儒士驚愕，遽以實告。自此又號爲鑑文大師，有《浮漚篇》行於世。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天河雖有浪，月桂不聞香。","（《詩話總龜》八《評論門》引《零陵總記》）。"]', '["天河雖有浪，月桂不闻香。","（《诗話總龟》八《評論门》引《零陵總記》）。"]', '诗', 'shi', '', NULL, '句（開元中，有儒士登終南山，得句云：「野迥雲根闊，山高樹影長。」私心自負，吟諷之際，忽聞空中語云：「未若天河云云。」儒士不勝喜，以爲己有。歸誇於僧，智潛掩鼻笑曰：「臭氣可掬，何足多也。」儒士驚愕，遽以實告。自此又號爲鑑文大師，有《浮漚篇》行於世。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ca9468-8029-4d36-a2ca-45f361c8c733', '編入樂府詞四首 一', '編入乐府词四首 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山川雖異所，艸木尚同春。","亦如溱洧地，自有采花人。"]', '["山川雖異所，艸木尚同春。","亦如溱洧地，自有采花人。"]', '诗', 'shi', '', NULL, '編入樂府詞四首 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68cbc3ac-8823-4774-b374-863fdcd54174', '編入樂府詞四首 二', '編入乐府词四首 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["受律辭元首，相將討叛臣。","咸歌《破陣樂》，共賞太平人。"]', '["受律辞元首，相將討叛臣。","咸歌《破陣乐》，共賞太平人。"]', '诗', 'shi', '', NULL, '編入樂府詞四首 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f7d979-1a91-457a-bdb5-cfd4cc2b54fd', '編入樂府詞四首 三', '編入乐府词四首 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["四海皇風被，千年德水清。","戎衣更不著，今日告功成。"]', '["四海皇风被，千年德水清。","戎衣更不著，今日告功成。"]', '诗', 'shi', '', NULL, '編入樂府詞四首 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423e1e8a-bb69-4f33-a778-153010eef8f6', '編入樂府詞四首 四', '編入乐府词四首 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主上開昌曆，臣忠奉大猷。","君看偃革後，便是太平秋。","（《萬首唐人絕句》三盛唐後）（〖1〗以上四首，原列卷三蓋嘉運名下。","按《萬首唐人絕句》收蓋嘉運《編入樂府詞》凡十四首，應爲指蓋嘉運採輯奏進之作，而非指其所自作。","十四首中，《全唐詩》已收入十首，皆非蓋作。","此四首，「山川雖異所」一首見《樂府詩集》卷七十三，題作《于闐採花》，作無名氏詩，其餘三首，《樂府詩集》卷二十均作《唐凱樂歌辭》，分別題作《破陣樂》、《賀聖歡》、《君臣同慶樂》，幷引《唐書·樂志》云：「太常舊有《破陣樂》、《應聖期》兩曲歌辭，至大和三年始具儀注，又補撰二曲爲四曲。","」今據以移歸無名氏之作。","）。"]', '["主上开昌曆，臣忠奉大猷。","君看偃革後，便是太平秋。","（《万首唐人絕句》三盛唐後）（〖1〗以上四首，原列卷三蓋嘉運名下。","按《万首唐人絕句》收蓋嘉運《編入乐府词》凡十四首，應爲指蓋嘉運採輯奏進之作，而非指其所自作。","十四首中，《全唐诗》已收入十首，皆非蓋作。","此四首，「山川雖異所」一首见《乐府诗集》卷七十三，題作《于闐採花》，作無名氏诗，其餘三首，《乐府诗集》卷二十均作《唐凱乐歌辞》，分別題作《破陣乐》、《賀聖歡》、《君臣同慶乐》，幷引《唐书·乐志》云：「太常旧有《破陣乐》、《應聖期》兩曲歌辞，至大和三年始具儀注，又補撰二曲爲四曲。","」今據以移归無名氏之作。","）。"]', '诗', 'shi', '', NULL, '編入樂府詞四首 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b206995a-f158-4fb4-8276-eb8d712fabcc', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 一', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["遠山重疊水縈紆，水碧山青畫不如。","山水裏，在巖居，誰道儂家也釣魚。"]', '["远山重叠水縈紆，水碧山青畫不如。","山水裏，在巖居，誰道儂家也釣鱼。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a76f40-9860-49dd-a152-aa0ea4ea850c', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 二', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["釣得紅鮮劈水開，錦鱗如畫逐鉤來。","從棹尾，且穿顋，不管前溪一夜雷。"]', '["釣得紅鲜劈水开，錦鱗如畫逐鉤来。","從棹尾，且穿顋，不管前溪一夜雷。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9031790c-562b-4d23-9147-b5c060136b38', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 三', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["桃花浪起五湖春，一葉隨風萬里身。","車宛□，餌輪囷，水邊時有羨魚人。"]', '["桃花浪起五湖春，一葉隨风万里身。","车宛□，餌輪囷，水邊时有羨鱼人。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce435ca-1b4a-4266-a193-f3a968e75600', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 四', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["五嶺風煙絕四鄰，滿川鳧雁是交親。","風觸岸，浪搖身，青草燈深不見人。"]', '["五嶺风煙絕四鄰，满川鳧雁是交親。","风觸岸，浪搖身，青草灯深不见人。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d04d241-bbf9-440f-9589-01c80f4c595b', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 五', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雪色髭鬚一老翁，時開短棹撥長空。","微有雨，正無風，宜在五湖煙水中。"]', '["雪色髭鬚一老翁，时开短棹撥长空。","微有雨，正無风，宜在五湖煙水中。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d064322-612f-4da2-b762-56010c8c4d6a', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 六', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["殘霞晚照四山明，雲起雲收陰又晴。","風腳動，浪頭生，定是虛篷夜雨聲。"]', '["殘霞晚照四山明，云起云收陰又晴。","风腳动，浪头生，定是虛篷夜雨声。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7459a3ee-387f-4192-a1ea-a8b52bf75bcb', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 七', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["極浦遙看兩岸花，碧波微影弄晴霞。","孤艇小，信橫斜，那箇汀洲不是家。"]', '["極浦遙看兩岸花，碧波微影弄晴霞。","孤艇小，信橫斜，那箇汀洲不是家。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4d7927-3adb-4230-9547-91887b9b9e69', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 八', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["洞庭湖上曉風生，風觸湖心一葉橫。","蘭棹快，草衣輕，只釣鱸魚不釣名。","。"]', '["洞庭湖上晓风生，风觸湖心一葉橫。","蘭棹快，草衣轻，只釣鱸鱼不釣名。","。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e1e032d-5176-4d2f-aa20-2748ef8f2bde', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 九', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舴艋爲舟力幾多，江頭雷雨半相和。","珍重意，下長波，半夜潮生不奈何。"]', '["舴艋爲舟力幾多，江头雷雨半相和。","珍重意，下长波，半夜潮生不奈何。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58bc007-6e7d-4cbc-ad76-c531dff102a6', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["垂楊灣外遠山微，萬里晴波浸落暉。","擊楫去，本無機，驚起鴛鴦撲塵飛。"]', '["垂楊灣外远山微，万里晴波浸落暉。","擊楫去，本無機，驚起鴛鴦撲塵飞。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b67fdb4-62b9-49aa-a07c-49fa7e6e228a', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十一', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["衝波棹子橛頭船，青草湖中欲暮天。","看白鳥，下長川，點破瀟湘萬里煙。"]', '["衝波棹子橛头船，青草湖中欲暮天。","看白鸟，下长川，点破瀟湘万里煙。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f225b3e9-e3e7-4d87-9caa-f16aabd44cfc', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十二', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["料理絲綸欲放船，江頭明月向人圓。","尊有酒，坐無氊，拋下漁竿踏水眠。"]', '["料理絲綸欲放船，江头明月向人圓。","尊有酒，坐無氊，拋下漁竿踏水眠。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bfb4bb6-bfd1-4311-a34f-0d6ad579e529', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十三', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風攪長空浪攪風，魚龍混雜一川中。","藏遠溆，繫長松，儘待雲收月照空。"]', '["风攪长空浪攪风，鱼龙混杂一川中。","藏远溆，繫长松，儘待云收月照空。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3593d915-6eec-4e9a-9474-0d9fd84ba30f', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十四', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["舴艋爲家無姓名，胡蘆中有甕頭清。","香稻飯，紫蓴羹，破浪穿雲樂性靈。"]', '["舴艋爲家無姓名，胡蘆中有甕头清。","香稻飯，紫蓴羹，破浪穿云乐性靈。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff218266-0ffe-4ae5-a3ca-78b7ff17cb00', '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十五', '和漁父词（十五首）（《顏魯公集·逸诗存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父词》共二十五首。今惟志和词存，见《續仙傳》。」係張志和同时諸人倡和词，《直斋书錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["偶然香餌得長鱏，魚大船輕力不任。","隨遠近，共浮沉，事事從輕不要深。","（《金奩集》）。"]', '["偶然香餌得长鱏，鱼大船轻力不任。","隨远近，共浮沉，事事從轻不要深。","（《金奩集》）。"]', '诗', 'shi', '', NULL, '和漁父詞（十五首）（《顏魯公集·逸詩存目》云：「公與陸鴻漸、徐士衡、李成矩共和玄真子〖張志和〗《漁父詞》共二十五首。今惟志和詞存，見《續仙傳》。」係張志和同時諸人倡和詞，《直齋書錄解題》有《玄真子漁歌碑傳集錄》一卷，可參考。） 十五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d79474-c3c9-4354-bd8a-0ec20f982a41', '答張籍（句）（元和中，長安有沙門〖不記名氏〗善病人文章，尤能捉語意相合處。張水部頗恚之，冥搜愈切，因得句曰：「長因送人處，憶得別家時。」徑往誇揚。乃曰：「此應不合前輩意也。」僧微笑曰：「此有人道了也。」籍曰：「向有何人？」僧乃吟曰：〖見下〗籍因撫掌大笑。）', '答張籍（句）（元和中，长安有沙门〖不記名氏〗善病人文章，尤能捉語意相合处。張水部頗恚之，冥搜愈切，因得句曰：「长因送人处，憶得別家时。」徑往誇揚。乃曰：「此應不合前輩意也。」僧微笑曰：「此有人道了也。」籍曰：「向有何人？」僧乃吟曰：〖见下〗籍因撫掌大笑。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["見他桃李樹，思得後園春。","（《唐摭言》十三）。"]', '["见他桃李樹，思得後园春。","（《唐摭言》十三）。"]', '诗', 'shi', '', NULL, '答張籍（句）（元和中，長安有沙門〖不記名氏〗善病人文章，尤能捉語意相合處。張水部頗恚之，冥搜愈切，因得句曰：「長因送人處，憶得別家時。」徑往誇揚。乃曰：「此應不合前輩意也。」僧微笑曰：「此有人道了也。」籍曰：「向有何人？」僧乃吟曰：〖見下〗籍因撫掌大笑。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d60e39-48d5-48f8-92be-792187e3a844', '誚失婢牓詩（原情寄嘲。三首） 一', '誚失婢牓诗（原情寄嘲。三首） 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["撫養在香閨，嬌癡教不依。","縱然桃葉寵，打得柳花飛。","曉露空調粉，春羅枉賜衣。","內家方妒殺，好處任從歸。"]', '["撫養在香閨，嬌癡教不依。","縱然桃葉寵，打得柳花飞。","晓露空調粉，春羅枉賜衣。","內家方妒殺，好处任從归。"]', '诗', 'shi', '', NULL, '誚失婢牓詩（原情寄嘲。三首） 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2717cc6-bea2-4eca-8b93-3890f3066237', '誚失婢牓詩（原情寄嘲。三首） 二', '誚失婢牓诗（原情寄嘲。三首） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["偷鎖出深閨，風花何所依？","想因乘月去，難道綽天飛。","燭暗新垂淚，香凝舊舞衣。","恩情如不斷，還向夢中歸。"]', '["偷鎖出深閨，风花何所依？","想因乘月去，难道綽天飞。","燭暗新垂泪，香凝旧舞衣。","恩情如不斷，還向梦中归。"]', '诗', 'shi', '', NULL, '誚失婢牓詩（原情寄嘲。三首） 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e09766-1ba2-427e-bdf4-ebc76ec5281b', '誚失婢牓詩（原情寄嘲。三首） 三', '誚失婢牓诗（原情寄嘲。三首） 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["揭牓諱因依，千聲叫不歸。","頭盤紅縷髻，身著紫羅衣。","夾帶無金玉，窩藏有是非。","請君看賞格，惆悵信音稀。","（汪立名輯本《白香山詩集·補遺》注引《堯山堂外紀》）。"]', '["揭牓諱因依，千声叫不归。","头盤紅縷髻，身著紫羅衣。","夾带無金玉，窩藏有是非。","請君看賞格，惆悵信音稀。","（汪立名輯本《白香山诗集·補遺》注引《堯山堂外紀》）。"]', '诗', 'shi', '', NULL, '誚失婢牓詩（原情寄嘲。三首） 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ca1ec8-4d2b-4615-9543-8d446b007897', '詠二遊女（大中年，有江淮郡守名郎，登樓縱飲，見二遊女羅衣飄飄，目送久之，因詠曰：）', '詠二游女（大中年，有江淮郡守名郎，登楼縱饮，见二游女羅衣飄飄，目送久之，因詠曰：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["兩朵紅英值萬金，教人不負看花心。"]', '["兩朵紅英值万金，教人不負看花心。"]', '诗', 'shi', '', NULL, '詠二遊女（大中年，有江淮郡守名郎，登樓縱飲，見二遊女羅衣飄飄，目送久之，因詠曰：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4356094-bffd-4081-937f-8bd23dee9fa3', '攝中郎將作詩（在省日，宣宗顧問稱旨，攝中郎將，有詩曰：〖見下〗風神後邁。後擁節旄。）', '攝中郎將作诗（在省日，宣宗顧问稱旨，攝中郎將，有诗曰：〖见下〗风神後邁。後擁節旄。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["宮娃引入玉爲行，金殿齊趨近御牀。","不見聖明親顧問，如何得攝漢中郎？","（以上《詩話總龜》二三《寓情門》引《南部新書》）。"]', '["宮娃引入玉爲行，金殿齊趨近御牀。","不见聖明親顧问，如何得攝漢中郎？","（以上《诗話總龟》二三《寓情门》引《南部新书》）。"]', '诗', 'shi', '', NULL, '攝中郎將作詩（在省日，宣宗顧問稱旨，攝中郎將，有詩曰：〖見下〗風神後邁。後擁節旄。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a968e23e-6c36-4d85-a0eb-971dba38b146', '商山館（商山館中窗頰上有八句詩云云，不知何人作。淨君、涼友，是帚與扇明矣。）', '商山館（商山館中窗頰上有八句诗云云，不知何人作。淨君、涼友，是帚與扇明矣。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["淨君掃浮塵，涼友招清風。","炎炎火雲節，蕭然一堂中。","誰知鹿冠叟，心地如虛空。","虛空亦莫問，睡起照青銅。","（《清異錄》三）。"]', '["淨君掃浮塵，涼友招清风。","炎炎火云節，蕭然一堂中。","誰知鹿冠叟，心地如虛空。","虛空亦莫问，睡起照青銅。","（《清異錄》三）。"]', '诗', 'shi', '', NULL, '商山館（商山館中窗頰上有八句詩云云，不知何人作。淨君、涼友，是帚與扇明矣。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e98484f7-621d-436c-91c5-75aaa24d0c3d', '宮詞', '宮词', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["落絮濛濛立夏天，樓前槐樹影初圓。","傳聞紫殿深深處，別有薰風入舜絃。"]', '["落絮濛濛立夏天，楼前槐樹影初圓。","傳闻紫殿深深处，別有薰风入舜絃。"]', '诗', 'shi', '', NULL, '宮詞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58809712-ce76-4b0f-a69e-fb5085f1111e', '送春', '送春', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["斜風細雨趲春歸，何不從容奈妾時。","未辦三盃相別酒，先吟一首送行詩。","再三留得鶬鶊晚，千萬休教杜宇知。","縱若苦留留不住，明年早早到南枝。"]', '["斜风細雨趲春归，何不從容奈妾时。","未辦三盃相別酒，先吟一首送行诗。","再三留得鶬鶊晚，千万休教杜宇知。","縱若苦留留不住，明年早早到南枝。"]', '诗', 'shi', '', NULL, '送春 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd62049-52d0-454f-9be9-f7b739fa3e0a', '題壁', '題壁', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一團茅草亂蓬蓬，驀地燒天驀地空。","爭似滿爐煨榾柮，慢騰騰地煖烘烘。","〖1〗（以上江標影刻南宋書棚本《唐人五十家小集》（〖1〗《許彥周詩話》稱宣和癸卯年遊嵩山峻極中院，見法堂後檐壁間有此詩，「字畫極草草」，旁有司馬光書「勿毀此詩」四字。","又見《貴耳集》卷上。","〖2〗以上三，原收歸韋轂名下，今移作無名氏詩，詳《修訂說明》。","）。"]', '["一團茅草亂蓬蓬，驀地燒天驀地空。","爭似满爐煨榾柮，慢腾腾地煖烘烘。","〖1〗（以上江標影刻南宋书棚本《唐人五十家小集》（〖1〗《許彥周诗話》稱宣和癸卯年游嵩山峻極中院，见法堂後檐壁间有此诗，「字畫極草草」，旁有司马光书「勿毀此诗」四字。","又见《貴耳集》卷上。","〖2〗以上三，原收归韋轂名下，今移作無名氏诗，詳《修訂说明》。","）。"]', '诗', 'shi', '', NULL, '題壁 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00bbb71f-b3fc-4bcc-8710-653c34c52185', '錢氏雷威琴（李巽伯云：「先公得雷威琴，錢氏物也，中題云云。故號忘味，爲當代第一。」）', '錢氏雷威琴（李巽伯云：「先公得雷威琴，錢氏物也，中題云云。故號忘味，爲當代第一。」）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["嶧陽孫枝，匠成雅器。","一聽秋堂，三月忘味。","（《全五代詩》七四引《西溪叢話》上）。"]', '["嶧陽孫枝，匠成雅器。","一听秋堂，三月忘味。","（《全五代诗》七四引《西溪叢話》上）。"]', '诗', 'shi', '', NULL, '錢氏雷威琴（李巽伯云：「先公得雷威琴，錢氏物也，中題云云。故號忘味，爲當代第一。」） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01488cf0-b68e-4890-ab9c-a3eeb6fa58bc', '嘲曹翰（曹翰事世宗爲樞密承旨。性貪侈。常著錦韤金綫絲鞵。朝士有托無名子嘲之者，詩曰：）', '嘲曹翰（曹翰事世宗爲樞密承旨。性貪侈。常著錦韤金綫絲鞵。朝士有托無名子嘲之者，诗曰：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不作錦衣裳，裁爲十指倉。","千金包汗脚，慚愧絡絲娘。","（《清異錄》三）。"]', '["不作錦衣裳，裁爲十指倉。","千金包汗脚，慚愧絡絲娘。","（《清異錄》三）。"]', '诗', 'shi', '', NULL, '嘲曹翰（曹翰事世宗爲樞密承旨。性貪侈。常著錦韤金綫絲鞵。朝士有托無名子嘲之者，詩曰：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610e4989-b243-47d6-8a79-1ebbde639069', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」）', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕时，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前归。」若去远，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默晓，譁曰：「扈君恐砌水隐形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖诗略〗。逼載饮尽。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。載連沃六七巨觥，吐嘔淋漓。既上马，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 無名氏 shi');
