INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551486a9-cc3a-456a-aeb8-a6f74509d4ba', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 二', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕时，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前归。」若去远，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默晓，譁曰：「扈君恐砌水隐形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖诗略〗。逼載饮尽。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。載連沃六七巨觥，吐嘔淋漓。既上马，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["細彈防事水，短藝戒時香。","。"]', '["細彈防事水，短藝戒时香。","。"]', '诗', 'shi', '', NULL, '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 二 無名氏 shi');
