INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd95464-0bcf-40e6-a921-4400b5820f13', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 五', '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕时，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前归。」若去远，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默晓，譁曰：「扈君恐砌水隐形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖诗略〗。逼載饮尽。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。別云〖诗略〗。載連沃六七巨觥，吐嘔淋漓。既上马，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["命繫逡巡水，時牽決定香。","（《清異錄》一）。"]', '["命繫逡巡水，时牽決定香。","（《清異錄》一）。"]', '诗', 'shi', '', NULL, '水香勸盞嘲扈載（酒令）（扈載畏內特甚。未仕時，欲出，則謁假于細君。細君滴水于地，指曰：「不乾須前歸。」若去遠，則然香印掐至某所，以爲還家之驗。因筵聚，方三行酒，載色欲逃遁。朋友默曉，譁曰：「扈君恐砌水隱形，香印過界耳，是當罰也。吾徒人撰新句一聯，勸清酒一盞。」衆以爲善，乃俱起。一人捧甌吟曰〖詩略〗。逼載飲盡。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。別云〖詩略〗。載連沃六七巨觥，吐嘔淋漓。既上馬，羣譟曰：「若夫人怪遲，但道被水香勸盞留住。」） 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb716a4-b3ad-4f70-8bfc-ef8e41a65b85', '玄卿鏡銘（玄卿鏡，文筆古雅似六朝，字體圓潤似李唐，疑是隋末唐初之物。玄卿，鑄鏡字也。廣州某氏所藏。）', '玄卿镜銘（玄卿镜，文笔古雅似六朝，字體圓潤似李唐，疑是隋末唐初之物。玄卿，鑄镜字也。廣州某氏所藏。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["日初升，月初盈，纖塵不生，肖茲萬形。","是曰攖寧，瑩虖太清。","（嘉慶《廣東通志》二○○《金石略》）（〖1〗玄卿，原均作元卿，清人諱改，今改回。","《金石萃編》卷一一八錄銘文，注云「廟諱」。","民國《重修信陽縣志》卷四錄邑貢生劉海涵藏鏡，即題《唐玄卿鏡》，文同。","又見《小檀欒室鏡影》卷四。","原以元卿列目，未允，今移此。","）。"]', '["日初升，月初盈，纖塵不生，肖茲万形。","是曰攖寧，瑩虖太清。","（嘉慶《廣东通志》二○○《金石略》）（〖1〗玄卿，原均作元卿，清人諱改，今改回。","《金石萃編》卷一一八錄銘文，注云「廟諱」。","民国《重修信陽縣志》卷四錄邑貢生劉海涵藏镜，即題《唐玄卿镜》，文同。","又见《小檀欒室镜影》卷四。","原以元卿列目，未允，今移此。","）。"]', '诗', 'shi', '', NULL, '玄卿鏡銘（玄卿鏡，文筆古雅似六朝，字體圓潤似李唐，疑是隋末唐初之物。玄卿，鑄鏡字也。廣州某氏所藏。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c67a8e9-55d5-4319-8236-4bd5b9eb433d', '高宗時瑤（胡楚賓，秋浦〖貴池〗人。善屬文，高宗召爲右史、兼崇賢直學士，預選與諸儒論禁中，撰《臣軌》等書千餘篇。朝廷疑議表疏密使參處，以分宰相權，號北門學士。楚賓爲文甚敏，必酒中下筆。高宗每命作時，常以金銀杯𣂏酒飲之，文成輙賜焉。其英資豪穎，與李白倫，故當時謠曰：）（《全唐詩》八七八《胡楚賓謠》，以爲與晚唐顧雲、張喬、殷文圭等爲同時人，文字有不同。〖2〗）', '高宗时瑤（胡楚賓，秋浦〖貴池〗人。善屬文，高宗召爲右史、兼崇賢直学士，預選與諸儒論禁中，撰《臣軌》等书千餘篇。朝廷疑議表疏密使參处，以分宰相權，號北门学士。楚賓爲文甚敏，必酒中下笔。高宗每命作时，常以金銀杯𣂏酒饮之，文成輙賜焉。其英資豪穎，與李白倫，故當时謠曰：）（《全唐诗》八七八《胡楚賓謠》，以爲與晚唐顧云、張喬、殷文圭等爲同时人，文字有不同。〖2〗）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["前有胡楚賓，後有李翰林。","詞同三峽水，字值萬黃金。","（《嘉靖池州府志》七《人物篇·賢哲》）（〖1〗謠中「李翰林」即李白，玄宗時人，是此謠至早亦應爲天寶間李白居秋浦後方可能出現，題誤甚明。","似仍當從《全唐詩》題作《胡楚賓謠》爲妥。","〖2〗《全唐詩》以楚賓與顧雲等人皆爲秋浦人，非謂與諸人同時。","）。"]', '["前有胡楚賓，後有李翰林。","词同三峽水，字值万黄金。","（《嘉靖池州府志》七《人物篇·賢哲》）（〖1〗謠中「李翰林」即李白，玄宗时人，是此謠至早亦應爲天寶间李白居秋浦後方可能出現，題誤甚明。","似仍當從《全唐诗》題作《胡楚賓謠》爲妥。","〖2〗《全唐诗》以楚賓與顧云等人皆爲秋浦人，非謂與諸人同时。","）。"]', '诗', 'shi', '', NULL, '高宗時瑤（胡楚賓，秋浦〖貴池〗人。善屬文，高宗召爲右史、兼崇賢直學士，預選與諸儒論禁中，撰《臣軌》等書千餘篇。朝廷疑議表疏密使參處，以分宰相權，號北門學士。楚賓爲文甚敏，必酒中下筆。高宗每命作時，常以金銀杯𣂏酒飲之，文成輙賜焉。其英資豪穎，與李白倫，故當時謠曰：）（《全唐詩》八七八《胡楚賓謠》，以爲與晚唐顧雲、張喬、殷文圭等爲同時人，文字有不同。〖2〗） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd25cba3-e4df-4933-8722-a4b51e9f5ec4', '開元時謠（《楊妃外傳》：開元十載上元日，楊家五宅夜遊，與廣寧公主騎從爭西門市。楊氏奴鞭公主衣，公主墮馬。駙馬程昌胤扶主，因及數撾。主泣奏，上令決殺楊家奴，昌胤停官。於是楊家轉橫。時謠云：）', '开元时謠（《楊妃外傳》：开元十載上元日，楊家五宅夜游，與廣寧公主騎從爭西门市。楊氏奴鞭公主衣，公主墮马。駙马程昌胤扶主，因及數撾。主泣奏，上令決殺楊家奴，昌胤停官。於是楊家轉橫。时謠云：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["生女勿悲酸，生男勿喜歡。","（《歲時廣記》十一《上元》）（〖1〗最早見陳鴻《長恨歌傳》，又見樂史《楊太真外傳》卷上。","）。"]', '["生女勿悲酸，生男勿喜歡。","（《歲时廣記》十一《上元》）（〖1〗最早见陳鴻《长恨歌傳》，又见乐史《楊太真外傳》卷上。","）。"]', '诗', 'shi', '', NULL, '開元時謠（《楊妃外傳》：開元十載上元日，楊家五宅夜遊，與廣寧公主騎從爭西門市。楊氏奴鞭公主衣，公主墮馬。駙馬程昌胤扶主，因及數撾。主泣奏，上令決殺楊家奴，昌胤停官。於是楊家轉橫。時謠云：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('552561ec-1bb2-4b73-9200-6e0ccdca6948', '三高僧諺（道標，富陽人。姓黎氏，一作秦氏。年七歲，有大沙門過而識之，勸令出家。爲靈隱山白雲峯海和尚弟子。至德二年詔白衣通佛經七百紙者，命爲比丘，標首中選，即日得度居南天竺寺。嘗於靈鷲峯之南西嶺下，葺茅爲堂，號西嶺草堂，稱西嶺和尚。經營之外，尤練詩章。當時吳興清晝〖皎然〗、會稽靈澈，相與酬唱。諺云〖見下〗。又陸羽云：「夫日月雲霞爲天標，山川草木爲地標，推能歸美爲德標，居閑趣寂爲道標。」長慶三年卒，年八十四。〖《高僧傳》參《西湖高僧事略》〗）', '三高僧諺（道標，富陽人。姓黎氏，一作秦氏。年七歲，有大沙门過而識之，勸令出家。爲靈隐山白云峯海和尚弟子。至德二年詔白衣通佛經七百紙者，命爲比丘，標首中選，即日得度居南天竺寺。嘗於靈鷲峯之南西嶺下，葺茅爲堂，號西嶺草堂，稱西嶺和尚。經營之外，尤練诗章。當时吳兴清晝〖皎然〗、會稽靈澈，相與酬唱。諺云〖见下〗。又陸羽云：「夫日月云霞爲天標，山川草木爲地標，推能归美爲德標，居闲趣寂爲道標。」长慶三年卒，年八十四。〖《高僧傳》參《西湖高僧事略》〗）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["霅之晝，能清秀。","越之澈，洞冰雪。","杭之標，摩雲霄。","（雍正《浙江通志》一九八《仙釋傳·杭州府》）（〖1〗見《宋高僧傳》卷十五《唐杭州靈隱山道標傳》。","首二句又見同書卷二九《唐湖州杼山皎然傳》，中二句又見卷十五《唐會稽雲門寺靈澈傳》。","）。"]', '["霅之晝，能清秀。","越之澈，洞冰雪。","杭之標，摩云霄。","（雍正《浙江通志》一九八《仙釋傳·杭州府》）（〖1〗见《宋高僧傳》卷十五《唐杭州靈隐山道標傳》。","首二句又见同书卷二九《唐湖州杼山皎然傳》，中二句又见卷十五《唐會稽云门寺靈澈傳》。","）。"]', '诗', 'shi', '', NULL, '三高僧諺（道標，富陽人。姓黎氏，一作秦氏。年七歲，有大沙門過而識之，勸令出家。爲靈隱山白雲峯海和尚弟子。至德二年詔白衣通佛經七百紙者，命爲比丘，標首中選，即日得度居南天竺寺。嘗於靈鷲峯之南西嶺下，葺茅爲堂，號西嶺草堂，稱西嶺和尚。經營之外，尤練詩章。當時吳興清晝〖皎然〗、會稽靈澈，相與酬唱。諺云〖見下〗。又陸羽云：「夫日月雲霞爲天標，山川草木爲地標，推能歸美爲德標，居閑趣寂爲道標。」長慶三年卒，年八十四。〖《高僧傳》參《西湖高僧事略》〗） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b30283b-be70-4557-b8b2-0a03701e22ab', '國學新修五經壁歌（幷記）', '国学新修五經壁歌（幷記）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["我有學宇，既傾而成之。","我有壁經，既昧而明之。","孰規摹之？孰發揮之？祭酒維齊，博士維韋。","俾我學徒，弦歌以時。","切切祁祁，不敖不嬉。","庶乎遒人，來采我詩。","（《劉夢得集》二六《記》）（〖1〗此歌原收劉禹錫名下，然按記中所述，應爲國學生徒所作，故移歸無名氏。","）。"]', '["我有学宇，既傾而成之。","我有壁經，既昧而明之。","孰規摹之？孰發揮之？祭酒維齊，博士維韋。","俾我学徒，弦歌以时。","切切祁祁，不敖不嬉。","庶乎遒人，来采我诗。","（《劉梦得集》二六《記》）（〖1〗此歌原收劉禹錫名下，然按記中所述，應爲国学生徒所作，故移归無名氏。","）。"]', '诗', 'shi', '', NULL, '國學新修五經壁歌（幷記） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67dfd4f1-29f6-4003-9d92-3b67ed958cc0', '高黎貢山謠（高黎貢山在永昌西，下臨怒江，左右平川，謂之穹賧湯浪，加萌所居也。朝濟怒江登山，暮方到山頂。冬中山上積雪苦寒，夏秋又苦穹賧湯浪毒暑酷熱。河賧賈客，在尋傳羈旅未還者，爲之謠曰：）', '高黎貢山謠（高黎貢山在永昌西，下臨怒江，左右平川，謂之穹賧湯浪，加萌所居也。朝濟怒江登山，暮方到山頂。冬中山上積雪苦寒，夏秋又苦穹賧湯浪毒暑酷熱。河賧賈客，在尋傳羈旅未還者，爲之謠曰：）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["冬日欲歸來，高黎貢山雪。","秋夏欲歸來，無那穹賧熱。","春時欲歸來，囊中絡賂絕。","（原注：絡賂，財之名也。","《蠻書》二、《永昌府文徵》一）。"]', '["冬日欲归来，高黎貢山雪。","秋夏欲归来，無那穹賧熱。","春时欲归来，囊中絡賂絕。","（原注：絡賂，財之名也。","《蠻书》二、《永昌府文徵》一）。"]', '诗', 'shi', '', NULL, '高黎貢山謠（高黎貢山在永昌西，下臨怒江，左右平川，謂之穹賧湯浪，加萌所居也。朝濟怒江登山，暮方到山頂。冬中山上積雪苦寒，夏秋又苦穹賧湯浪毒暑酷熱。河賧賈客，在尋傳羈旅未還者，爲之謠曰：） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b5f469-cd3d-4b67-9ce3-41bdd95db14a', '籤詞（盧多遜相生曹南，方幼，其父携就雲陽道觀小學。時與羣兒誦書廢壇上，有古籤一筒，競往抽取爲戲。時多遜尚未識字，得一籤，歸示其父。詞曰云云。父見頗喜，以爲吉讖，留籤於家。迨後作相，及其敗也，始因遣堂吏趙白陰與秦王廷美連謀，事暴，遂南竄，年五十二卒於朱崖。籤中之語，一字不差。）', '籤词（盧多遜相生曹南，方幼，其父携就云陽道观小学。时與羣兒誦书廢壇上，有古籤一筒，競往抽取爲戲。时多遜尚未識字，得一籤，归示其父。词曰云云。父见頗喜，以爲吉讖，留籤於家。迨後作相，及其敗也，始因遣堂吏趙白陰與秦王廷美連謀，事暴，遂南竄，年五十二卒於朱崖。籤中之語，一字不差。）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["身出中書堂，須因天水白。","登仙五十二，終爲蓬海客。","（《玉壺清話》三）。"]', '["身出中书堂，須因天水白。","登仙五十二，終爲蓬海客。","（《玉壺清話》三）。"]', '诗', 'shi', '', NULL, '籤詞（盧多遜相生曹南，方幼，其父携就雲陽道觀小學。時與羣兒誦書廢壇上，有古籤一筒，競往抽取爲戲。時多遜尚未識字，得一籤，歸示其父。詞曰云云。父見頗喜，以爲吉讖，留籤於家。迨後作相，及其敗也，始因遣堂吏趙白陰與秦王廷美連謀，事暴，遂南竄，年五十二卒於朱崖。籤中之語，一字不差。） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc81a619-f338-484c-8288-b9ca08631638', '磨劍泉', '磨劍泉', 'e4272ccf-3ff3-466a-ac1e-e6b3eb2230ea', '唐', '["源泉巖溜漾清波，淬出光鋩利太阿。","橋下斬蛟餘事耳，斷除天下幾妖魔。"]', '["源泉巖溜漾清波，淬出光鋩利太阿。","橋下斬蛟餘事耳，斷除天下幾妖魔。"]', '诗', 'shi', '', NULL, '磨劍泉 程太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8fd194-e2e2-4ea6-ab62-678f0c7511c1', '清心泉', '清心泉', 'e4272ccf-3ff3-466a-ac1e-e6b3eb2230ea', '唐', '["飛泉觸石玉玎璫，中隱神龍歲月長。","多少人間煩苦事，只消一點便清涼。"]', '["飞泉觸石玉玎璫，中隐神龙歲月长。","多少人间煩苦事，只消一点便清涼。"]', '诗', 'shi', '', NULL, '清心泉 程太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d10298d-daec-4c70-8968-348a5f57f460', '漱玉泉', '漱玉泉', 'e4272ccf-3ff3-466a-ac1e-e6b3eb2230ea', '唐', '["瀑布橫飛翠壑間，泉聲入耳送清寒。","天然一曲非凡響，萬顆明珠落玉盤。"]', '["瀑布橫飞翠壑间，泉声入耳送清寒。","天然一曲非凡响，万顆明珠落玉盤。"]', '诗', 'shi', '', NULL, '漱玉泉 程太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88020cd6-c877-4632-a3d0-174216653e83', '洞陽峯', '洞陽峯', 'e4272ccf-3ff3-466a-ac1e-e6b3eb2230ea', '唐', '["南岷勝槩壓諸方，東壁奇峯出洞陽。","丈五月輪纔晃曜，大千世界便輝光。","扶開華嶽烟雲渺，顯得蓬萊日月長。","世道廢興原有數，浮沉聚散亦何傷。"]', '["南岷勝槩壓諸方，东壁奇峯出洞陽。","丈五月輪纔晃曜，大千世界便輝光。","扶开华嶽烟云渺，显得蓬萊日月长。","世道廢兴原有數，浮沉聚散亦何傷。"]', '诗', 'shi', '', NULL, '洞陽峯 程太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e025081-bcc8-4475-83c9-fd98a1a5c6ea', '醮壇峯', '醮壇峯', 'e4272ccf-3ff3-466a-ac1e-e6b3eb2230ea', '唐', '["蒼松老檜擁華壇，鶴唳猿啼白晝閒。","烟篆香殘凌漢表，風飄仙樂響山間。","高燒華嶽金蓮炬，齊到黃岡玉笋班。","獨步蒼苔尋故址，恍然咫尺覲天顏。","（以上《古今圖書集成·職方典》六○二《順慶府部》）。"]', '["蒼松老檜擁华壇，鹤唳猿啼白晝閒。","烟篆香殘凌漢表，风飄仙乐响山间。","高燒华嶽金蓮炬，齊到黄岡玉笋班。","独步蒼苔尋故址，恍然咫尺覲天顏。","（以上《古今圖书集成·職方典》六○二《順慶府部》）。"]', '诗', 'shi', '', NULL, '醮壇峯 程太虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('943a1f3e-7e77-4160-8f82-2d387a27956b', '', '', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["空（原案：《太平廣記》：廣州有何二娘，以織鞋爲業。","後飛去上羅浮山爲仙。","唐開元中勅令黃門使往廣州求何氏，得之。","後又踊身而去，不知所之。","《孔氏六帖》：增城何氏女，有神仙之術云云。","《輿地紀勝》：女仙中增城何氏女下有何仙云。","《會仙觀記》：昔有何仙居此，食雲母。","唐景龍中白日昇仙。","竊疑何二娘、何氏女、何仙乃一人，即世俗八仙中之何仙姑也。","今按：《古今圖書集成·神仙部》及《中國人名大辭典》又雜引《安慶府志》、《歙縣志》、《祁陽縣志》、《浙江通志》及《福建通志》，各有異說。","）。"]', '["空（原案：《太平廣記》：廣州有何二娘，以织鞋爲業。","後飞去上羅浮山爲仙。","唐开元中勅令黄门使往廣州求何氏，得之。","後又踊身而去，不知所之。","《孔氏六帖》：增城何氏女，有神仙之術云云。","《輿地紀勝》：女仙中增城何氏女下有何仙云。","《會仙观記》：昔有何仙居此，食云母。","唐景龙中白日昇仙。","竊疑何二娘、何氏女、何仙乃一人，即世俗八仙中之何仙姑也。","今按：《古今圖书集成·神仙部》及《中国人名大辞典》又杂引《安慶府志》、《歙縣志》、《祁陽縣志》、《浙江通志》及《福建通志》，各有異说。","）。"]', '诗', 'shi', '', NULL, ' 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93b06f6-db58-4272-99ac-f3226b868f1c', '鳳臺雲母（所居春岡，地產雲母。嘗夢老人授服餌丹法，漸覺身輕健。有詩曰〖見下〗。後果有鳳來集其上，遂改名鳳臺云。）', '鳳台云母（所居春岡，地產云母。嘗梦老人授服餌丹法，漸覺身轻健。有诗曰〖见下〗。後果有鳳来集其上，遂改名鳳台云。）', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["鳳臺雲母似天花，鍊作芙蓉白雲芽。","笑殺狂游勾漏令，更從何處覓丹砂？。"]', '["鳳台云母似天花，鍊作芙蓉白云芽。","笑殺狂游勾漏令，更從何处覓丹砂？。"]', '诗', 'shi', '', NULL, '鳳臺雲母（所居春岡，地產雲母。嘗夢老人授服餌丹法，漸覺身輕健。有詩曰〖見下〗。後果有鳳來集其上，遂改名鳳臺云。） 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe333b5b-e8f0-4e26-ac95-1e0f50e2773d', '將遊羅浮留詩（江北與羅浮山相望，嘗曰：「將遊羅浮。」父母怪之，私爲擇配。結縭之夕，忽不知所之。留詩屏硯間曰〖見下〗。明早起視家側井逕，有遺履而已。）', '將游羅浮留诗（江北與羅浮山相望，嘗曰：「將游羅浮。」父母怪之，私爲擇配。結縭之夕，忽不知所之。留诗屏硯间曰〖见下〗。明早起視家側井逕，有遺履而已。）', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["麻姑怪我戀塵囂，一隔仙凡道路遙。","去去滄洲弄明月，倒騎黃鶴聽鸞簫。"]', '["麻姑怪我戀塵囂，一隔仙凡道路遙。","去去滄洲弄明月，倒騎黄鹤听鸾簫。"]', '诗', 'shi', '', NULL, '將遊羅浮留詩（江北與羅浮山相望，嘗曰：「將遊羅浮。」父母怪之，私爲擇配。結縭之夕，忽不知所之。留詩屏硯間曰〖見下〗。明早起視家側井逕，有遺履而已。） 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5327d9ab-fa2e-4833-b4da-8a4997e7e386', '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 一', '有道士自羅浮之增城口占三絕寄家（頃之，有道士来自羅浮，见姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖见下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黄巖人，始悟仙語無一不有驗云。） 一', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["鐵橋風景勝天台，千樹萬樹梅花開。","玉簫吹過黃巖洞，勾引長庚跨鶴來。"]', '["鐵橋风景勝天台，千樹万樹梅花开。","玉簫吹過黄巖洞，勾引长庚跨鹤来。"]', '诗', 'shi', '', NULL, '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 一 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff08d407-afb9-4249-8465-1c5817b1271b', '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 二', '有道士自羅浮之增城口占三絕寄家（頃之，有道士来自羅浮，见姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖见下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黄巖人，始悟仙語無一不有驗云。） 二', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["寄語童童與阿瓊，休將塵事惱閒情。","蓬萊弱水今清淺，滿地花陰護月明。"]', '["寄語童童與阿瓊，休將塵事惱閒情。","蓬萊弱水今清淺，满地花陰護月明。"]', '诗', 'shi', '', NULL, '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 二 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d354922-7ecc-43cc-97df-b62dc2491454', '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 三', '有道士自羅浮之增城口占三絕寄家（頃之，有道士来自羅浮，见姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖见下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黄巖人，始悟仙語無一不有驗云。） 三', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["已趁羣真入紫微，故鄉回首尚遲遲。","千年留取井邊履，說與草堂仙子知。"]', '["已趁羣真入紫微，故乡回首尚遲遲。","千年留取井邊履，说與草堂仙子知。"]', '诗', 'shi', '', NULL, '有道士自羅浮之增城口占三絕寄家（頃之，有道士來自羅浮，見姑在麻姑石上，顧謂道士曰：「而之增城，屬吾親收拾井上履，口占三絕寄其家曰〖見下〗。」其後增城李令世英與謝草堂者表其事。李令爲天台黃巖人，始悟仙語無一不有驗云。） 三 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03d5979-87c2-4a53-8776-c5e3c971241b', '柔珠庵東壁題詩（句）（仙姑又嘗於柔珠庵壁題一絕，字比晉人差，清婉少骨。壁後半毀，惟餘「百尺」十三字，其下必「風」字也。後二句無人能續之者。）', '柔珠庵东壁題诗（句）（仙姑又嘗於柔珠庵壁題一絕，字比晉人差，清婉少骨。壁後半毀，惟餘「百尺」十三字，其下必「风」字也。後二句無人能續之者。）', '5abbd168-beca-4c80-abf7-b5ed6b3c0ba9', '唐', '["百尺水簾飛白虹，笙簫松柏語天[風]。","（嘉慶《廣東通志》三二九《釋老傳》轉引《羅浮山志會編》引明孫蕡《何仙姑記》）（〖1〗何仙姑諸詩，當皆出宋以後人依託。","）。"]', '["百尺水簾飞白虹，笙簫松柏語天[风]。","（嘉慶《廣东通志》三二九《釋老傳》轉引《羅浮山志會編》引明孫蕡《何仙姑記》）（〖1〗何仙姑諸诗，當皆出宋以後人依託。","）。"]', '诗', 'shi', '', NULL, '柔珠庵東壁題詩（句）（仙姑又嘗於柔珠庵壁題一絕，字比晉人差，清婉少骨。壁後半毀，惟餘「百尺」十三字，其下必「風」字也。後二句無人能續之者。） 何仙姑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec1676f-cc0c-4065-bffc-26fbe3124c8d', '鐵筆歌（今按：疑爲後人所作，錄附參考。）', '鐵笔歌（今按：疑爲後人所作，錄附參考。）', '134facea-f346-487b-a0fc-d3d8d032e787', '唐', '["皇天生我兮男子，君王用我兮熊羆。","力拔山兮勢雄，氣貫日兮虹霓。","月正明兮磨鎗礪劍，星未落兮擊鼓掀旗。","擣賊室兮焚寨，臠賊肉兮充饑。","食馬革兮計盡，殺妻妾兮心悲。","爲厲鬼兮身被鐵甲，爲明神兮手執金鎚。","亦莫指我爲張毅，亦莫指我爲張飛。","我乃唐之張巡，與許遠兮同時。","在東嶽兮押案，都統使兮陰司。","事蓬萊兮殿直，任酆都兮獄推。","景祐真君兮陽間封爵，忠烈大夫兮天上官資。","漫濡毫而爲翰，俾世人而皆知。","（《古今圖書集成·職方典》三九九《歸德府部》）（〖1〗康熙《商邱縣志》卷十八收此詩，注：「公降乩所作。","」）。"]', '["皇天生我兮男子，君王用我兮熊羆。","力拔山兮勢雄，氣貫日兮虹霓。","月正明兮磨鎗礪劍，星未落兮擊鼓掀旗。","擣賊室兮焚寨，臠賊肉兮充饑。","食马革兮計尽，殺妻妾兮心悲。","爲厲鬼兮身被鐵甲，爲明神兮手執金鎚。","亦莫指我爲張毅，亦莫指我爲張飞。","我乃唐之張巡，與許远兮同时。","在东嶽兮押案，都統使兮陰司。","事蓬萊兮殿直，任酆都兮獄推。","景祐真君兮陽间封爵，忠烈大夫兮天上官資。","漫濡毫而爲翰，俾世人而皆知。","（《古今圖书集成·職方典》三九九《归德府部》）（〖1〗康熙《商邱縣志》卷十八收此诗，注：「公降乩所作。","」）。"]', '诗', 'shi', '', NULL, '鐵筆歌（今按：疑爲後人所作，錄附參考。） 張巡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ecd300-7f6d-41a7-ba02-46285c5789b6', '劉處靜贈金不受（劉處靜，字道遊，彭城人。其先避地遂昌，因家焉。遇異人，授以吐納之道。嘗召見，賜緋衣，退居仙都山隱真巖，結廬金龍洞側，門人欲塑其像。一日，有嗜酒道人來成之，處靜留飲旬日，以黃金三十銖贈其行，相送金龍洞前。及回，得片紙書云云十六字，裹原金在焉。於是頓悟，遂豫築玄壚於廬後，自譔其志。咸通十四年六月辛酉日解化。）', '劉处静贈金不受（劉处静，字道游，彭城人。其先避地遂昌，因家焉。遇異人，授以吐納之道。嘗召见，賜緋衣，退居仙都山隐真巖，結廬金龙洞側，门人欲塑其像。一日，有嗜酒道人来成之，处静留饮旬日，以黄金三十銖贈其行，相送金龙洞前。及回，得片紙书云云十六字，裹原金在焉。於是頓悟，遂豫築玄壚於廬後，自譔其志。咸通十四年六月辛酉日解化。）', 'd87a3387-40bb-46f6-97c4-af308a372fb4', '唐', '["子與吾金，吾授子真。","真抱子形，形全於神。","（雍正《浙江通志》二○一《仙釋傳·處州府》引《仙都志》）。"]', '["子與吾金，吾授子真。","真抱子形，形全於神。","（雍正《浙江通志》二○一《仙釋傳·处州府》引《仙都志》）。"]', '诗', 'shi', '', NULL, '劉處靜贈金不受（劉處靜，字道遊，彭城人。其先避地遂昌，因家焉。遇異人，授以吐納之道。嘗召見，賜緋衣，退居仙都山隱真巖，結廬金龍洞側，門人欲塑其像。一日，有嗜酒道人來成之，處靜留飲旬日，以黃金三十銖贈其行，相送金龍洞前。及回，得片紙書云云十六字，裹原金在焉。於是頓悟，遂豫築玄壚於廬後，自譔其志。咸通十四年六月辛酉日解化。） 嗜酒道人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cd083c-16e7-4963-8cc0-dd50a9d41fad', '詩寄太原學士（題元祐七年九月九日書。爲宋人依託）（潁川莊綽跋云：「昔維揚有何仙姑者，世以爲謫仙，能與真靈接。一日，鍾離過之，使治黃素，乃書此詩。呂公亦跋其後，令俟王學士至而授之。後數日，王古敏仲自貳卿出守會稽，至維揚訪姑，即以與之。王祕不以示人。」）', '诗寄太原学士（題元祐七年九月九日书。爲宋人依託）（潁川莊綽跋云：「昔維揚有何仙姑者，世以爲謫仙，能與真靈接。一日，鍾離過之，使治黄素，乃书此诗。呂公亦跋其後，令俟王学士至而授之。後數日，王古敏仲自貳卿出守會稽，至維揚訪姑，即以與之。王祕不以示人。」）', '9c34759e-1711-4083-89f7-ce0be63dabc4', '唐', '["風燈泡沫兩相悲，未肯遺榮自保持。","頷下藏珠當猛取，身中有道更求誰？","才高雅稱神仙骨，智照靈如大寶龜。","一半青山無買處，與君攜手話希夷。","（《雲麓漫鈔》卷二）。"]', '["风灯泡沫兩相悲，未肯遺榮自保持。","頷下藏珠當猛取，身中有道更求誰？","才高雅稱神仙骨，智照靈如大寶龟。","一半青山無買处，與君携手話希夷。","（《云麓漫鈔》卷二）。"]', '诗', 'shi', '', NULL, '詩寄太原學士（題元祐七年九月九日書。爲宋人依託）（潁川莊綽跋云：「昔維揚有何仙姑者，世以爲謫仙，能與真靈接。一日，鍾離過之，使治黃素，乃書此詩。呂公亦跋其後，令俟王學士至而授之。後數日，王古敏仲自貳卿出守會稽，至維揚訪姑，即以與之。王祕不以示人。」） 鍾離權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dceb5308-87a2-400e-aa16-3339d62ec27a', '西靈觀（在新喻縣西五十里瑞仙山下，晉永和八年許真君建。）', '西靈观（在新喻縣西五十里瑞仙山下，晉永和八年許真君建。）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["八月秋高氣漸清，再攜琴劍宿西靈。","蕊珠新換當年殿，函谷重開往日經。","晉代宰王香馥馥，周朝柱史燭熒熒。","一聲鶴唳人間曉，吟起晴空徹杳冥。","（隆慶《臨江府志》十三）。"]', '["八月秋高氣漸清，再携琴劍宿西靈。","蕊珠新換當年殿，函谷重开往日經。","晉代宰王香馥馥，周朝柱史燭熒熒。","一声鹤唳人间晓，吟起晴空徹杳冥。","（隆慶《臨江府志》十三）。"]', '诗', 'shi', '', NULL, '西靈觀（在新喻縣西五十里瑞仙山下，晉永和八年許真君建。） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27c6bdc-d5a5-49e9-8687-03d92da97b4b', '朗州戲筆（二首） 一', '朗州戲笔（二首） 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["賣墨遨遊到朗州，無端太守問因由。","家居北斗星辰下，劍掛南山月角頭。","朝覲玉皇登寶殿，暮隨王母宴瓊樓。","知君相見不相識，回首白雲歸去休。"]', '["賣墨遨游到朗州，無端太守问因由。","家居北斗星辰下，劍掛南山月角头。","朝覲玉皇登寶殿，暮隨王母宴瓊楼。","知君相见不相識，回首白云归去休。"]', '诗', 'shi', '', NULL, '朗州戲筆（二首） 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e918830-50e9-4118-8a51-5e6faaf5da9c', '朗州戲筆（二首） 二', '朗州戲笔（二首） 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["數年不到鼎城遊，反掌俄經八十秋。","劉氏宅爲張氏宅，謝家樓作李家樓。","千金公子皆空手，三歲孩兒盡白頭。","惟有兩般依舊在，青山長秀水長流。","（嘉靖《常德府志》十九）。"]', '["數年不到鼎城游，反掌俄經八十秋。","劉氏宅爲張氏宅，謝家楼作李家楼。","千金公子皆空手，三歲孩兒尽白头。","惟有兩般依旧在，青山长秀水长流。","（嘉靖《常德府志》十九）。"]', '诗', 'shi', '', NULL, '朗州戲筆（二首） 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1fa1a5-1758-4149-ad7e-7a6ceaab2096', '白雲巖', '白云巖', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["古木叢林號白雲，高巖更去謁觀音。","路登青嶂上頭上，寺隱白雲深處深。","法鼓震開天地眼，飛輪推出聖凡心。","時人到此如中悟，何必南巖海上尋。"]', '["古木叢林號白云，高巖更去謁观音。","路登青嶂上头上，寺隐白云深处深。","法鼓震开天地眼，飞輪推出聖凡心。","时人到此如中悟，何必南巖海上尋。"]', '诗', 'shi', '', NULL, '白雲巖 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ac86e1-2c57-44d3-9a53-1e2bb0cdad52', '過水坪', '過水坪', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["山巔雲起日初辰，山徑霜清絕點塵。","林下支鍋炊飯客，道旁背籠販鹽人。","白崖嶺峻藏風洞，碧澗泉音露石垠。","跋涉不知殘臘盡，動勞寧復計冬春。","（以上《古今圖書集成·職方典》一一六二《鄖陽府部》）。"]', '["山巔云起日初辰，山徑霜清絕点塵。","林下支鍋炊飯客，道旁背籠販鹽人。","白崖嶺峻藏风洞，碧澗泉音露石垠。","跋涉不知殘臘尽，动勞寧复計冬春。","（以上《古今圖书集成·職方典》一一六二《鄖陽府部》）。"]', '诗', 'shi', '', NULL, '過水坪 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc032720-4303-4605-8519-6c460a1740a3', '遊靈顯觀', '游靈显观', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["素衣丹壑寄生涯，相近衡茅共幾家。","臥聽松音臨水石，坐看山色老烟霞。","林中有鶴窺來客，岩畔無人見落花。","但把琴書消白晝，不須爐裏煉丹砂。","（同上三三五《潞安府部》）。"]', '["素衣丹壑寄生涯，相近衡茅共幾家。","臥听松音臨水石，坐看山色老烟霞。","林中有鹤窺来客，岩畔無人见落花。","但把琴书消白晝，不須爐裏煉丹砂。","（同上三三五《潞安府部》）。"]', '诗', 'shi', '', NULL, '遊靈顯觀 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73dd5e7d-7e92-42ef-bf19-355397535d4c', '呂劍留泉', '呂劍留泉', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["五百年前此地來，碧桃移向石壇栽。","三春綠柳千條縷，萬線清泉一劍開。","紅日照殘新殿閣，白雲堆破舊樓臺。","昔年蹤跡今何在？尚有餘霞點翠苔。","（同上一二八八《靖州部》）。"]', '["五百年前此地来，碧桃移向石壇栽。","三春綠柳千條縷，万線清泉一劍开。","紅日照殘新殿閣，白云堆破旧楼台。","昔年蹤跡今何在？尚有餘霞点翠苔。","（同上一二八八《靖州部》）。"]', '诗', 'shi', '', NULL, '呂劍留泉 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c356f84f-d6cb-4667-8f48-eab75dcc134c', '印山亭即事', '印山亭即事', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰道憑虛不可樓，波心一點注中流。","魚游過影知空相，人到驚雲動遠眸。","隔斷紅塵飛不到，迴旋青氣望來收。","江天寂寞難窮目，煙火漁燈亂客愁。","（同上一四二八《平樂府部》）。"]', '["誰道憑虛不可楼，波心一点注中流。","鱼游過影知空相，人到驚云动远眸。","隔斷紅塵飞不到，迴旋青氣望来收。","江天寂寞难窮目，煙火漁灯亂客愁。","（同上一四二八《平乐府部》）。"]', '诗', 'shi', '', NULL, '印山亭即事 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fda8f7b-836c-4565-a9c9-ccb1896ca21e', '集虛觀留題（在岳池縣郭南門外。○又作《寓雲洞橋夜題石壁》）', '集虛观留題（在岳池縣郭南门外。○又作《寓云洞橋夜題石壁》）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["青蛇煉影月（一作「就自」）徘徊，夜靜雲間尚未（一作「開向此」）來。","應是有人新換骨，暫留蹤跡到天台。","（《輿地紀勝》一六五《廣安軍·仙釋》。","《古今圖書集成·職方典》六○二《順慶府部》。","又一二七○《辰州府部》）。"]', '["青蛇煉影月（一作「就自」）徘徊，夜静云间尚未（一作「开向此」）来。","應是有人新換骨，暫留蹤跡到天台。","（《輿地紀勝》一六五《廣安軍·仙釋》。","《古今圖书集成·職方典》六○二《順慶府部》。","又一二七○《辰州府部》）。"]', '诗', 'shi', '', NULL, '集虛觀留題（在岳池縣郭南門外。○又作《寓雲洞橋夜題石壁》） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ab11e8-0dc4-40c5-8ed9-7d7d5f00f18f', '題昌元驛', '題昌元驛', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["東西南北留蹤跡，縱意風狂到處覓。","朝朝暮暮去尋人，及至人尋還不識。","（《永樂大典》一八二二四「像」字韻引《輿地紀勝》）。"]', '["东西南北留蹤跡，縱意风狂到处覓。","朝朝暮暮去尋人，及至人尋還不識。","（《永乐大典》一八二二四「像」字韻引《輿地紀勝》）。"]', '诗', 'shi', '', NULL, '題昌元驛 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f519c5ea-230d-4aae-b460-d9ea6e219300', '飛雲山留題（飛雲山王氏道院，去蒲村鎮五里，昔有道人過之。留題云云。以逐句第三字合成「呂洞賓來」，主人覺而異之，已失道人所在矣。）', '飞云山留題（飞云山王氏道院，去蒲村鎮五里，昔有道人過之。留題云云。以逐句第三字合成「呂洞賓来」，主人覺而異之，已失道人所在矣。）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["攜笻來此步飛雲，錢滿賓階綠蘚勻。","江上同歸共誰去，不堪回首不逢人。","（《輿地紀勝》一五一《永康軍·仙釋》）。"]', '["携笻来此步飞云，錢满賓階綠蘚勻。","江上同归共誰去，不堪回首不逢人。","（《輿地紀勝》一五一《永康軍·仙釋》）。"]', '诗', 'shi', '', NULL, '飛雲山留題（飛雲山王氏道院，去蒲村鎮五里，昔有道人過之。留題云云。以逐句第三字合成「呂洞賓來」，主人覺而異之，已失道人所在矣。） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9840330-87f0-4f98-808a-2d5f68b01fcf', '題壁二絕 一', '題壁二絕 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["展旗邀我過天聰，玉女雙鸞展笑容。","卓筆醮乾龍鼻水，等閑題破石屏風。"]', '["展旗邀我過天聰，玉女雙鸾展笑容。","卓笔醮乾龙鼻水，等闲題破石屏风。"]', '诗', 'shi', '', NULL, '題壁二絕 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c197c754-51a4-4dee-a54a-3e11e192352b', '題壁二絕 二', '題壁二絕 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["昔時曾臥龍湫水，今日止茲續舊遊。","何處酒家堪醉月，興酣解却白狐裘。","（《廣雁蕩山誌》二十一《藝文》作回道人）。"]', '["昔时曾臥龙湫水，今日止茲續旧游。","何处酒家堪醉月，兴酣解却白狐裘。","（《廣雁蕩山誌》二十一《藝文》作回道人）。"]', '诗', 'shi', '', NULL, '題壁二絕 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de63f15-eed5-4832-98f0-3b6b3681a8b2', '桃花溪（以下詠景十首）', '桃花溪（以下詠景十首）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["東風昨夜落奇葩，散作春江萬頃霞。","從此漁郎得消息，泝流直到是仙家。"]', '["东风昨夜落奇葩，散作春江万頃霞。","從此漁郎得消息，泝流直到是仙家。"]', '诗', 'shi', '', NULL, '桃花溪（以下詠景十首） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('222db5d9-5d2b-4ffa-b884-e25df15e2296', '桃川仙隱', '桃川仙隐', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["說着神仙豈偶然，神仙名不是虛傳。"]', '["说着神仙豈偶然，神仙名不是虛傳。"]', '诗', 'shi', '', NULL, '桃川仙隱 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e54b931-d435-4b81-b3c0-8386e611ebab', '秦人洞', '秦人洞', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["洞門深鎖白雲封，九節丹崖第幾重？欲向山中詢甲子，秦人盡日不相逢。"]', '["洞门深鎖白云封，九節丹崖第幾重？欲向山中詢甲子，秦人尽日不相逢。"]', '诗', 'shi', '', NULL, '秦人洞 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('873ee7fa-f232-4a5e-9a6c-81a2ee923838', '纜船洲', '纜船洲', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["笑拋漁艇入蒼茫，豈意壺中歲月長。","歸到荒洲無覓處，萋萋芳草對斜陽。"]', '["笑拋漁艇入蒼茫，豈意壺中歲月长。","归到荒洲無覓处，萋萋芳草对斜陽。"]', '诗', 'shi', '', NULL, '纜船洲 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2773976c-c566-4cdd-bee1-78b0556d39a8', '空心杉', '空心杉', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["古木槎牙樹底空，學仙遊子坐空中。","自從白日飛昇去，幾度寒鴉噪晚風。"]', '["古木槎牙樹底空，学仙游子坐空中。","自從白日飞昇去，幾度寒鴉噪晚风。"]', '诗', 'shi', '', NULL, '空心杉 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d15f77-c449-4a47-bba1-d30e04b13306', '煉丹臺', '煉丹台', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["誰築斯臺學煉丹？丹成飛上紫雲端。","空餘遺址在人世，滿目青山碧草寒。"]', '["誰築斯台学煉丹？丹成飞上紫云端。","空餘遺址在人世，满目青山碧草寒。"]', '诗', 'shi', '', NULL, '煉丹臺 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa69c85f-4480-4b32-8c99-6c4b518e884f', '遇仙橋', '遇仙橋', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["幾回秦女夜吹簫，洞底松風送寂寥。","不作巫陽雲雨夢，却尋仙侶到藍橋。"]', '["幾回秦女夜吹簫，洞底松风送寂寥。","不作巫陽云雨梦，却尋仙侶到藍橋。"]', '诗', 'shi', '', NULL, '遇仙橋 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00b1fa7-36c3-46e6-87da-e31cafc3ee8a', '仙逕亭', '仙逕亭', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["紫氣南來第一關，道人家在白雲間。","山門深鎖無人到，流水落花春晝閑。","。"]', '["紫氣南来第一关，道人家在白云间。","山门深鎖無人到，流水落花春晝闲。","。"]', '诗', 'shi', '', NULL, '仙逕亭 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4282778a-2331-4d51-bd83-47693bce92ef', '歸鶴峯', '归鹤峯', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["鶴歸華表幾千年，雞犬隨丹盡上天。","開遍碧桃春不老，千巖萬壑鎖蒼煙。"]', '["鹤归华表幾千年，雞犬隨丹尽上天。","开遍碧桃春不老，千巖万壑鎖蒼煙。"]', '诗', 'shi', '', NULL, '歸鶴峯 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68482129-155b-4f20-9143-e4a943c02032', '梅溪煙雨', '梅溪煙雨', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["摩挲睡眼望山凹，非霧非煙景四郊。","一幅生綃不收拾，被風展却掛林梢。","（以上《嘉靖常德府志》十九。","又《古今圖書集成·職方典》一二六二《常德府志》及《山川典》一六二《桃源山部》）。"]', '["摩挲睡眼望山凹，非霧非煙景四郊。","一幅生綃不收拾，被风展却掛林梢。","（以上《嘉靖常德府志》十九。","又《古今圖书集成·職方典》一二六二《常德府志》及《山川典》一六二《桃源山部》）。"]', '诗', 'shi', '', NULL, '梅溪煙雨 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d730aff3-1218-428d-a20c-e7d1be7f0fd9', '大圓山（大圓山有光塵子墨迹云云。傍書宋乾道壬辰年，相傳以爲呂仙作矣。）', '大圓山（大圓山有光塵子墨迹云云。傍书宋乾道壬辰年，相傳以爲呂仙作矣。）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三山相接欲飛騰，高下來爲半日登。","合向中間著夫子，大員道士小員僧。","（《蜀中名勝記》十八《重慶府·定遠縣》）。"]', '["三山相接欲飞腾，高下来爲半日登。","合向中间著夫子，大員道士小員僧。","（《蜀中名勝記》十八《重慶府·定远縣》）。"]', '诗', 'shi', '', NULL, '大圓山（大圓山有光塵子墨迹云云。傍書宋乾道壬辰年，相傳以爲呂仙作矣。） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b7157a-63d7-45c1-b6cc-4e4bd0c78bdf', '登平都訪仙（二首。題呂純陽） 一', '登平都訪仙（二首。題呂純陽） 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["盂蘭清曉過平都，天下名山總不如。","兩口單行誰解識，王陰空使馬蹄虛。"]', '["盂蘭清晓過平都，天下名山總不如。","兩口單行誰解識，王陰空使马蹄虛。"]', '诗', 'shi', '', NULL, '登平都訪仙（二首。題呂純陽） 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee64ff64-8967-49b8-9e98-6ea71b016172', '登平都訪仙（二首。題呂純陽） 二', '登平都訪仙（二首。題呂純陽） 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["一鳴白鳥出青城，再謁王陰二友人。","口口惟言三島樂，擡眸已過洞庭春。","（同上十九《酆都縣》）。"]', '["一鳴白鸟出青城，再謁王陰二友人。","口口惟言三島乐，擡眸已過洞庭春。","（同上十九《酆都縣》）。"]', '诗', 'shi', '', NULL, '登平都訪仙（二首。題呂純陽） 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99992076-39f2-4693-963c-d86e6dd481df', '嵩山觀（題呂巖）', '嵩山观（題呂巖）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["兩日行山興尚稠，塵緣未斷且回頭。","一天風雨吹涼閣，四面藤蘿伴客留。","著眼盡難爲業障，平生無過是浮漚。","何須底死言名利，尋得清閑即便休。","（同上三十《潼川州·遂寧縣》）。"]', '["兩日行山兴尚稠，塵緣未斷且回头。","一天风雨吹涼閣，四面藤蘿伴客留。","著眼尽难爲業障，平生無過是浮漚。","何須底死言名利，尋得清闲即便休。","（同上三十《潼川州·遂寧縣》）。"]', '诗', 'shi', '', NULL, '嵩山觀（題呂巖） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a08411d-7140-4e43-b5f6-207ad6661873', '題酒家門額（唐末，馮翊城外酒家門額，書云云。於王字末，大書酒也。字體散逸，非世俗書，人謂是呂洞賓題。）', '題酒家门額（唐末，馮翊城外酒家门額，书云云。於王字末，大书酒也。字體散逸，非世俗书，人謂是呂洞賓題。）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["飛空却回顧，謝此含春王。","（《清異錄》四）。"]', '["飞空却回顧，謝此含春王。","（《清異錄》四）。"]', '诗', 'shi', '', NULL, '題酒家門額（唐末，馮翊城外酒家門額，書云云。於王字末，大書酒也。字體散逸，非世俗書，人謂是呂洞賓題。） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344de08f-aa59-4b6e-96b6-0815c0da7b87', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 一', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["世有學人無數，愚癡妄意如麻。","汞鉛錯認結爲沙，運火欲覓黃芽。","千日虛勞心力，人人盡破其家。","真鉛似玉本無瑕，將鳳欲比狂鴉。"]', '["世有学人無數，愚癡妄意如麻。","汞鉛錯認結爲沙，運火欲覓黄芽。","千日虛勞心力，人人尽破其家。","真鉛似玉本無瑕，將鳳欲比狂鴉。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f41a2c-952a-4ee5-87af-d8ac7a1ed203', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 二', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["至道不煩不遠，至人只在目前。","淮王煉石得冲天，漢世已經千年。","全在低心下人，事該緣分偶然。","安爐置鼎盡周圓，須得汞去投鉛。"]', '["至道不煩不远，至人只在目前。","淮王煉石得冲天，漢世已經千年。","全在低心下人，事該緣分偶然。","安爐置鼎尽周圓，須得汞去投鉛。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e772c698-3d60-476b-9d55-cfbd25c67b3c', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 三', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["聽說金公兩字，何物喚作金孫。","尋枝尋葉必知根，無智便乃心昏。","若用凡鉛爲體，都來少魄無魂。","水銀漸結必難存，祕訣要處誰論。"]', '["听说金公兩字，何物喚作金孫。","尋枝尋葉必知根，無智便乃心昏。","若用凡鉛爲體，都来少魄無魂。","水銀漸結必难存，祕訣要处誰論。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e2bc92-34a7-42fa-a9ba-ef603dfe6370', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 四', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["真假兩般元字，金公所料重迷。","凡鉛縱與嶽山齊，不肯假與金妻。","聽說真鉛住處，他家跳在深溪。","兩情恩愛事因媒，義重爭向東西。"]', '["真假兩般元字，金公所料重迷。","凡鉛縱與嶽山齊，不肯假與金妻。","听说真鉛住处，他家跳在深溪。","兩情恩愛事因媒，義重爭向东西。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0512d1b-56fe-4480-885e-4d0ed6cc6b75', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 五', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["水火運法周歲，四六勿錯如初。","水多火少失功夫，勝地方始安爐。","直須認鼎與藥，却如雞子無殊。","內黃外白結凝酥，一顆圓明汞珠。"]', '["水火運法周歲，四六勿錯如初。","水多火少失功夫，勝地方始安爐。","直須認鼎與藥，却如雞子無殊。","內黄外白結凝酥，一顆圓明汞珠。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7133d0-9a24-4163-9d3b-50ee1d934a79', '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 六', '西江月（六首。以下词）（原八首，前二首已见《全唐诗》，此六首，《全宋词》亦未收。） 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["彼此離於生處，火遭水破驚忙。","分身各自擬深藏，半路再遣蕭郎。","夫爲無衣素體，妻因水浸衣黃。","丙丁甲乙有形相，剛遣令合陰陽。","（《古今圖書集成·神異典》三○二《靜功部》）。"]', '["彼此離於生处，火遭水破驚忙。","分身各自擬深藏，半路再遣蕭郎。","夫爲無衣素體，妻因水浸衣黄。","丙丁甲乙有形相，剛遣令合陰陽。","（《古今圖书集成·神異典》三○二《静功部》）。"]', '诗', 'shi', '', NULL, '西江月（六首。以下詞）（原八首，前二首已見《全唐詩》，此六首，《全宋詞》亦未收。） 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e68d6f-d2bf-4ddf-ab2d-1406b1f913e4', '西江月', '西江月', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["落日數聲啼鳥，香風滿路吹花。","道人邀我煮新茶，盪滌胸中瀟灑。","世事不堪回音，夢魂猶遶天涯。","鳳停橋畔即吾家，管甚月明今夜。","（《湖海新聞夷堅續志後集》一）。"]', '["落日數声啼鸟，香风满路吹花。","道人邀我煮新茶，盪滌胸中瀟灑。","世事不堪回音，梦魂猶遶天涯。","鳳停橋畔即吾家，管甚月明今夜。","（《湖海新闻夷堅續志後集》一）。"]', '诗', 'shi', '', NULL, '西江月 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c70684-b0f5-4a9a-81eb-369136781491', '沁園春', '沁园春', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["昨日南京，今朝天岳，倐焉忽焉。","指洞庭爲酒，渴時浩飲，君山件枕，醉後高眠。","談笑自如，往來無礙，半是風狂半是仙。","隨身在，有一襟風月，兩袖雲煙。","人間，放浪多年，又排辨東華第二筵。","把珊瑚砍倒，栽吾琪樹，天河放淺，種我金蓮。","搥碎王京，踢翻蓬島，稽首虛皇玉案前。","無難事，信功成八百，行滿三千。","（隆慶《岳州府志》十八）。"]', '["昨日南京，今朝天岳，倐焉忽焉。","指洞庭爲酒，渴时浩饮，君山件枕，醉後高眠。","談笑自如，往来無礙，半是风狂半是仙。","隨身在，有一襟风月，兩袖云煙。","人间，放浪多年，又排辨东华第二筵。","把珊瑚砍倒，栽吾琪樹，天河放淺，種我金蓮。","搥碎王京，踢翻蓬島，稽首虛皇玉案前。","無难事，信功成八百，行满三千。","（隆慶《岳州府志》十八）。"]', '诗', 'shi', '', NULL, '沁園春 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('472b6fab-d353-4140-8559-f3e6119f1df1', '沁園春', '沁园春', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["琳館清標，瓊臺麗質，何年天上飛來。","揚州暫倚，后土爲深栽。","獨立乾坤一樹，春風占，萬朵齊開。","天然巧，蕊珠圓簇，玉瓣輕裁。","見一花九朵，類玲瓏玉斝，錯落瓊盃。","得滿盛香露，洗蕩塵埃。","是真元孕育，有仙風道骨，豈是凡胎。","問真宰，難留下土，攜爾上蓬萊。","（《揚州瓊花集》）（〖1〗此詞調幷非《沁園春》，原書誤題。","趙遂之謂當作《滿庭芳》。","）。"]', '["琳館清標，瓊台丽質，何年天上飞来。","揚州暫倚，后土爲深栽。","独立乾坤一樹，春风占，万朵齊开。","天然巧，蕊珠圓簇，玉瓣轻裁。","见一花九朵，類玲瓏玉斝，錯落瓊盃。","得满盛香露，洗蕩塵埃。","是真元孕育，有仙风道骨，豈是凡胎。","问真宰，难留下土，携爾上蓬萊。","（《揚州瓊花集》）（〖1〗此词調幷非《沁园春》，原书誤題。","趙遂之謂當作《满庭芳》。","）。"]', '诗', 'shi', '', NULL, '沁園春 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('465512fc-fa48-46f3-a8dd-4a95214c6b27', '失調名', '失調名', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["別無巧妙，與你方兒一箇。","子後午前定息坐，夾脊雙門崑崙過。","恁你得氣力，思量我。","（《夷堅丁集》十八）。"]', '["別無巧妙，與你方兒一箇。","子後午前定息坐，夾脊雙门崑崙過。","恁你得氣力，思量我。","（《夷堅丁集》十八）。"]', '诗', 'shi', '', NULL, '失調名 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c22aa3-7280-4fd9-9682-22d2c86de703', '（附）羅浮山八仙石題詩（舊志云：「石在藥槽之下，流杯池上。相傳有八仙飲於此，飲畢題詩云云。鐫諸石上，歲久，字猶未甚漫滅。」）', '（附）羅浮山八仙石題诗（旧志云：「石在藥槽之下，流杯池上。相傳有八仙饮於此，饮畢題诗云云。鐫諸石上，歲久，字猶未甚漫滅。」）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["溜流青嶂瀉溪灣，漱石飛雲湍復旋。","琥珀杯深誰共飲？八仙齊會賀堯年。","（《古今圖書集成·山川典》一八九《羅浮山部》，又見《羅浮山志》十）。"]', '["溜流青嶂瀉溪灣，漱石飞云湍复旋。","琥珀杯深誰共饮？八仙齊會賀堯年。","（《古今圖书集成·山川典》一八九《羅浮山部》，又见《羅浮山志》十）。"]', '诗', 'shi', '', NULL, '（附）羅浮山八仙石題詩（舊志云：「石在藥槽之下，流杯池上。相傳有八仙飲於此，飲畢題詩云云。鐫諸石上，歲久，字猶未甚漫滅。」） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3932552e-2208-4f35-bacc-f3ff14dd7be5', '歌（故人朱當敏歸時，臯及賓客皆送之。至洞門，客以尺八擊玉磬，臯和而歌云云。歌畢，忽然俱去。）', '歌（故人朱當敏归时，臯及賓客皆送之。至洞门，客以尺八擊玉磬，臯和而歌云云。歌畢，忽然俱去。）', '30394975-9d91-499d-b57f-4569c99a9d03', '唐', '["朝爲雄兮暮爲雌，天地終盡兮人生幾時。","（《全五代詩》八七引《榕陰新簡》）（〖1〗《全閩詩話》卷八、《十國春秋》卷九九引《榕陰新檢》，云虞臯入羅喜洞後作此歌，及出洞已爲明洪武十二年，則此詩顯出明人附會。","）。"]', '["朝爲雄兮暮爲雌，天地終尽兮人生幾时。","（《全五代诗》八七引《榕陰新簡》）（〖1〗《全閩诗話》卷八、《十国春秋》卷九九引《榕陰新檢》，云虞臯入羅喜洞後作此歌，及出洞已爲明洪武十二年，則此诗显出明人附會。","）。"]', '诗', 'shi', '', NULL, '歌（故人朱當敏歸時，臯及賓客皆送之。至洞門，客以尺八擊玉磬，臯和而歌云云。歌畢，忽然俱去。） 虞臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28a1942-72fa-47e9-b198-bde0f49c0d34', '詩', '诗', 'b4bcd7de-8ac4-4919-8f69-ece9bc79ac6a', '唐', '["遠遠青青疊疊峯，峯前真宰讀書翁。","半巖冷落高宗雨，一洞淒涼吉甫風。","溪隱豹眠寒霧露，井凋鳳宿點梧桐。","九龍山下英雄氣，盡屬君王宇宙中。","（《永樂大典》七八九二「汀」字韻引《臨汀志·祠廟》）。"]', '["远远青青叠叠峯，峯前真宰读书翁。","半巖冷落高宗雨，一洞淒涼吉甫风。","溪隐豹眠寒霧露，井凋鳳宿点梧桐。","九龙山下英雄氣，尽屬君王宇宙中。","（《永乐大典》七八九二「汀」字韻引《臨汀志·祠廟》）。"]', '诗', 'shi', '', NULL, '詩 寧化九龍進士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b852baa4-8449-4d55-b895-c0921ddcd9af', '月夜吟（李西美帥成都，士人陳甲館於便齋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚麗者誦詩云云。忽不見。今府第，故蜀宮，豈當時宮女猶有鬼耶？） 一', '月夜吟（李西美帥成都，士人陳甲館於便斋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚丽者誦诗云云。忽不见。今府第，故蜀宮，豈當时宮女猶有鬼耶？） 一', '862c74cd-6536-4ae6-9728-3ef8ac82dd44', '唐', '["舊時衣服盡雲霞，不到迎仙不是家。","今日樓臺渾不識，只餘古木記宣華。","（按《蜀檮杌》。","宣華，故苑名。","）。"]', '["旧时衣服尽云霞，不到迎仙不是家。","今日楼台渾不識，只餘古木記宣华。","（按《蜀檮杌》。","宣华，故苑名。","）。"]', '诗', 'shi', '', NULL, '月夜吟（李西美帥成都，士人陳甲館於便齋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚麗者誦詩云云。忽不見。今府第，故蜀宮，豈當時宮女猶有鬼耶？） 一 蜀宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5012dd-f7f9-442e-be85-72d0a0c8f058', '月夜吟（李西美帥成都，士人陳甲館於便齋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚麗者誦詩云云。忽不見。今府第，故蜀宮，豈當時宮女猶有鬼耶？） 二', '月夜吟（李西美帥成都，士人陳甲館於便斋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚丽者誦诗云云。忽不见。今府第，故蜀宮，豈當时宮女猶有鬼耶？） 二', '862c74cd-6536-4ae6-9728-3ef8ac82dd44', '唐', '["小雨廉纖梅子黃，晚雲收盡月侵廊。","樹陰把酒不成醉，何處無情枉斷腸。","（《全五代詩》六十引《聞見後錄》）（〖1〗見《邵氏聞見後錄》卷三十。","李璆，字西美，紹興中帥蜀。","）。"]', '["小雨廉纖梅子黄，晚云收尽月侵廊。","樹陰把酒不成醉，何处無情枉斷腸。","（《全五代诗》六十引《闻见後錄》）（〖1〗见《邵氏闻见後錄》卷三十。","李璆，字西美，紹兴中帥蜀。","）。"]', '诗', 'shi', '', NULL, '月夜吟（李西美帥成都，士人陳甲館於便齋。月夜有危髻古衣裳婦人數輦，笑語花圃中，有甚麗者誦詩云云。忽不見。今府第，故蜀宮，豈當時宮女猶有鬼耶？） 二 蜀宮人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f5d0713-265c-45d5-8795-6c11a3b0f313', '思歸', '思归', '75c45f8c-5be1-45a5-98dc-09f8df4efd8b', '唐', '["慕義名空在，輪忠孝不全。","報恩無有日，歸國定何年？","（《古今和歌集》（《光明日報》一九七八年八月二十日王仁波文引）（〖1〗《古今和歌集》無此詩。","張步雲《唐代逸詩輯存》據《阿倍仲麻呂研究》一五七頁引《國史》錄此詩，「報恩」作「報國」。","）。"]', '["慕義名空在，輪忠孝不全。","報恩無有日，归国定何年？","（《古今和歌集》（《光明日報》一九七八年八月二十日王仁波文引）（〖1〗《古今和歌集》無此诗。","張步云《唐代逸诗輯存》據《阿倍仲麻呂研究》一五七頁引《国史》錄此诗，「報恩」作「報国」。","）。"]', '诗', 'shi', '', NULL, '思歸 晁衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5bb6ee9-7e0e-421a-b69a-6edf471a2b17', '酬惠米詩', '酬惠米诗', '22eaa0bc-7fc6-46db-821c-a7d6ed987c79', '唐', '["棄却金鑾衲布衣，修身浮海到華西。","原身自是皇太子，慕道相逢柯用之。","未敢叩門求地語，昨叨送米續晨炊。","而今飱食黃精飯，腹飽忘思前日飢。","（以上《嘉靖池州府志》九）（〖1〗周贇《九華山志》卷十考訂此詩與李白次韻詩皆爲僞作，其說云：「無論太白時未有次韻之習，金地藏未爲天子第，此等詩真令人見而欲嘔。","曾學爲詩者亦不鄙俚至此，此幷未嘗學爲詩而托名太白地藏者也。","」幷據費冠卿《化城寺記》，考金地藏爲新羅王子而非世子，卒于貞元十一年，壽九十九，應生於武后神功元年。","）。"]', '["棄却金鑾衲布衣，修身浮海到华西。","原身自是皇太子，慕道相逢柯用之。","未敢叩门求地語，昨叨送米續晨炊。","而今飱食黄精飯，腹飽忘思前日飢。","（以上《嘉靖池州府志》九）（〖1〗周贇《九华山志》卷十考訂此诗與李白次韻诗皆爲僞作，其说云：「無論太白时未有次韻之習，金地藏未爲天子第，此等诗真令人见而欲嘔。","曾学爲诗者亦不鄙俚至此，此幷未嘗学爲诗而托名太白地藏者也。","」幷據費冠卿《化城寺記》，考金地藏爲新羅王子而非世子，卒于貞元十一年，壽九十九，應生於武后神功元年。","）。"]', '诗', 'shi', '', NULL, '酬惠米詩 金地藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83804f9e-c430-4be7-b9b3-ab68a7433669', '詠史得韓非', '詠史得韓非', 'f9ee3838-9bd4-4c5f-bd2f-159a308241af', '唐', '["說難徒有美，孤憤竟無申。","定是名傷命，非關犯逆鱗。","（見《十萬卷樓叢書》本唐釋皎然《詩式》卷三。","）（按：此詩原有署「庾抱一」。","同書卷五又收庾抱一《駿馬》四句，爲《全唐詩》卷三九庾抱《驄馬》之後四句，知庾抱一當即庾抱。","《驄馬》全詩出《文苑英華》卷二○九。","）。"]', '["说难徒有美，孤憤竟無申。","定是名傷命，非关犯逆鱗。","（见《十万卷楼叢书》本唐釋皎然《诗式》卷三。","）（按：此诗原有署「庾抱一」。","同书卷五又收庾抱一《駿马》四句，爲《全唐诗》卷三九庾抱《驄马》之後四句，知庾抱一當即庾抱。","《驄马》全诗出《文苑英华》卷二○九。","）。"]', '诗', 'shi', '', NULL, '詠史得韓非 庾抱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c83866f-85e0-4531-964c-0a9607fbe816', '學小庾體', '学小庾體', 'fec84ee4-afe1-4c0e-a4c8-ea6deafbe1ac', '唐', '["拂簟承花落，開簾待燕歸。","（見《四部叢刊》本《後村先生大全集》卷一七七《詩話續集》引唐李康成《玉臺後集》）（按：《玉臺後集》，天寶間李康成所選，收梁陳至天寶間二百九人詩六百七十首，明中葉後失傳。","劉克莊自鄭子敬家得該集，摘其可存者錄入《詩話》。","）。"]', '["拂簟承花落，开簾待燕归。","（见《四部叢刊》本《後村先生大全集》卷一七七《诗話續集》引唐李康成《玉台後集》）（按：《玉台後集》，天寶间李康成所選，收梁陳至天寶间二百九人诗六百七十首，明中葉後失傳。","劉克莊自鄭子敬家得該集，摘其可存者錄入《诗話》。","）。"]', '诗', 'shi', '', NULL, '學小庾體 陳子良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fbfa68-875e-44ee-8e3f-64ae851739b6', '入闕詠空鏡臺詩', '入闕詠空镜台诗', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["即今裝飾廢，彫零衢路間。","姮娥與明月，相共落關山。","（見中華書局排印本唐徐堅等纂《初學記》卷二十五。","）。"]', '["即今裝飾廢，彫零衢路间。","姮娥與明月，相共落关山。","（见中华书局排印本唐徐堅等纂《初学記》卷二十五。","）。"]', '诗', 'shi', '', NULL, '入闕詠空鏡臺詩 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6de850-2f04-4cb6-863b-4f3a659488e4', '別毛明素', '別毛明素', '6733fc3f-2aee-4d21-b966-4dc672e8cbd3', '唐', '["叔夜嗟幽憤，陳思苦責躬。","在余今失候，枉與古人同。","草深難見日，松迥易來風。","因言得意者，誰復免窮通？","（《大正新修大藏經》第五十冊唐釋彥悰撰《唐護法沙門法琳別傳》卷中。","）。"]', '["叔夜嗟幽憤，陳思苦責躬。","在余今失候，枉與古人同。","草深难见日，松迥易来风。","因言得意者，誰复免窮通？","（《大正新修大藏經》第五十冊唐釋彥悰撰《唐護法沙门法琳別傳》卷中。","）。"]', '诗', 'shi', '', NULL, '別毛明素 法琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0151f55b-4f7f-4db2-a9b2-804f48a83f1f', '勅放遷益部臨行賦詩（題擬）', '勅放遷益部臨行賦诗（題擬）', '6733fc3f-2aee-4d21-b966-4dc672e8cbd3', '唐', '["僕秉屈原操，不探漁父篇。","問言蓬轉者，答言直如絃。","。"]', '["僕秉屈原操，不探漁父篇。","问言蓬轉者，答言直如絃。","。"]', '诗', 'shi', '', NULL, '勅放遷益部臨行賦詩（題擬） 法琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1386102e-4b39-4d0c-ab0a-b5306b083a9f', '辭訣友人詩（題擬）', '辞訣友人诗（題擬）', '6733fc3f-2aee-4d21-b966-4dc672e8cbd3', '唐', '["非意延非罪，離友復離親。","山川萬里隔，方勞七尺身。","遊魂長去楚，分念獨留秦。","自匪相知者，誰憐死別人。"]', '["非意延非罪，離友复離親。","山川万里隔，方勞七尺身。","游魂长去楚，分念独留秦。","自匪相知者，誰怜死別人。"]', '诗', 'shi', '', NULL, '辭訣友人詩（題擬） 法琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('359c4765-9081-49c6-ace5-23b137f8c868', '言志', '言志', '6733fc3f-2aee-4d21-b966-4dc672e8cbd3', '唐', '["草命如懸露，輕生類轉蓬。","所嗟明夜月，難與古人同。","（均見前書卷下）。"]', '["草命如懸露，轻生類轉蓬。","所嗟明夜月，难與古人同。","（均见前书卷下）。"]', '诗', 'shi', '', NULL, '言志 法琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0267e76d-c8f7-429c-91a1-ae2f9ab2c256', '青溪野老詩（題從《續古文苑》卷四）', '青溪野老诗（題從《續古文苑》卷四）', '6733fc3f-2aee-4d21-b966-4dc672e8cbd3', '唐', '["元淑世位卑，長卿宦情寡。","二頃且營田，三錢聊飲馬。","懸峰白雲上，挂月青山下。","中心欲有言，未得忘言者。","（見法琳《辨正論》卷七，《大正藏》本。","）。"]', '["元淑世位卑，长卿宦情寡。","二頃且營田，三錢聊饮马。","懸峰白云上，挂月青山下。","中心欲有言，未得忘言者。","（见法琳《辨正論》卷七，《大正藏》本。","）。"]', '诗', 'shi', '', NULL, '青溪野老詩（題從《續古文苑》卷四） 法琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0b8d92-ac0c-4878-9206-09d90293257d', '五言早秋侍宴應詔', '五言早秋侍宴應詔', '3e12d0d8-6ab9-4a80-af41-e39873622c67', '唐', '["殿閣炎光盡，池臺爽氣歸。","荷香風裏歇，樹影日中衰。","蟬聲出林散，鳥路入雲飛。","承恩方未極，無田駐落暉。","（見貴陽陳田影刻本日本尾張國真福寺藏唐卷子本《翰林學士集》）（按：此詩已收入張步雲《唐代逸詩輯存》。","《翰林學士集》收唐貞觀間君臣唱和詩六十首，集名爲後人臆加。","據拙考，此集實爲《許敬宗集》卷二的殘卷。","）。"]', '["殿閣炎光尽，池台爽氣归。","荷香风裏歇，樹影日中衰。","蟬声出林散，鸟路入云飞。","承恩方未極，無田駐落暉。","（见貴陽陳田影刻本日本尾張国真福寺藏唐卷子本《翰林学士集》）（按：此诗已收入張步云《唐代逸诗輯存》。","《翰林学士集》收唐貞观间君臣唱和诗六十首，集名爲後人臆加。","據拙考，此集實爲《許敬宗集》卷二的殘卷。","）。"]', '诗', 'shi', '', NULL, '五言早秋侍宴應詔 朱子奢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72d75c8-af1e-41ba-8eb1-a8fca9bf59e6', '宿沃洲山寺', '宿沃洲山寺', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["崆峒山叟到江東，荷杖來尋支遁蹤。","馬蹟幾經青草沒，仙壇依舊白雲封。","一聲清磬海邊月，十里香風澗底松。","何代沃洲今夜興，倚杖來聽赤城鐘。","（見《會稽掇英總集》卷四。","）（按：《全唐詩續補遺》卷二十據《輿地紀勝》卷四，錄此詩之後四句，作者作魏證。","陳耀東《全唐詩拾遺》據同治《嵊縣志》卷二四收本詩。","魏徵平生未至越中，友人趙昌平謂此詩格律非唐初所有，因疑非徵作。","因出處較早，姑仍錄存。","又按：《會稽掇英總集》，宋孔延之熙寧五年編。","《四庫全書總目》卷一八六該集提要云：「延之以會稽山水人物，著美前世，而紀錄賦詠，多所散佚。","因博加搜採，旁及碑版石刻，自漢迄宋，凡得銘志歌詩等八百五篇，輯爲二十卷。","」今自該集輯出唐人佚詩達百首之多。","）。"]', '["崆峒山叟到江东，荷杖来尋支遁蹤。","马蹟幾經青草沒，仙壇依旧白云封。","一声清磬海邊月，十里香风澗底松。","何代沃洲今夜兴，倚杖来听赤城鐘。","（见《會稽掇英總集》卷四。","）（按：《全唐诗續補遺》卷二十據《輿地紀勝》卷四，錄此诗之後四句，作者作魏證。","陳耀东《全唐诗拾遺》據同治《嵊縣志》卷二四收本诗。","魏徵平生未至越中，友人趙昌平謂此诗格律非唐初所有，因疑非徵作。","因出处較早，姑仍錄存。","又按：《會稽掇英總集》，宋孔延之熙寧五年編。","《四庫全书總目》卷一八六該集提要云：「延之以會稽山水人物，著美前世，而紀錄賦詠，多所散佚。","因博加搜採，旁及碑版石刻，自漢迄宋，凡得銘志歌诗等八百五篇，輯爲二十卷。","」今自該集輯出唐人佚诗達百首之多。","）。"]', '诗', 'shi', '', NULL, '宿沃洲山寺 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07c1953-f71b-43a2-9bdc-73a5e40b1814', '缺題五古詩 一', '缺題五古诗 一', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["大道夷且長，窘路狹且促。","脩翼無卑棲，遠趾不步局。","舒吾凌霄羽，奮此千里足。","超邁絕塵驅，倐忽誰能逐？","賢愚豈常類，稟性在清濁。","富貴有人籍，貧賤無天錄。","通塞苟由己，志士不相卜。","陳平敖里社，韓信釣河曲。","終居天下宰，食此萬鍾祿。","德音流千載，功名重山嶽。"]', '["大道夷且长，窘路狹且促。","脩翼無卑棲，远趾不步局。","舒吾凌霄羽，奮此千里足。","超邁絕塵驱，倐忽誰能逐？","賢愚豈常類，稟性在清濁。","富貴有人籍，貧賤無天錄。","通塞苟由己，志士不相卜。","陳平敖里社，韓信釣河曲。","終居天下宰，食此万鍾祿。","德音流千載，功名重山嶽。"]', '诗', 'shi', '', NULL, '缺題五古詩 一 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d60b01-fe90-4fad-8d95-ca6bf2cd7e74', '缺題五古詩 二', '缺題五古诗 二', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["靈芝生河洲，動搖因洪波。","蘭榮一何晚，嚴霜瘁其柯。","哀哉二芳草，不植泰山阿。","文質道所貴，遭時用有嘉。","絳灌臨衡宰，謂誼崇浮華。","賢才抑不用，遠投荆南沙。","抱玉乘龍驥，不逢樂与和。","安得孔仲尼，爲世陳四科。","（見上海大衆書局《古今碑帖集成》。","）（按：詩帖爲大楷，云出靜木齋藏。","末署：「貞觀三年。","」原連作一首，詳詩意及押韻，當爲二詩。","此帖前代未見著錄，靜木齋亦不詳爲誰，是否魏徵所作，甚爲可疑。","今姑錄出，以俟考詳。","）。"]', '["靈芝生河洲，动搖因洪波。","蘭榮一何晚，嚴霜瘁其柯。","哀哉二芳草，不植泰山阿。","文質道所貴，遭时用有嘉。","絳灌臨衡宰，謂誼崇浮华。","賢才抑不用，远投荆南沙。","抱玉乘龙驥，不逢乐与和。","安得孔仲尼，爲世陳四科。","（见上海大衆书局《古今碑帖集成》。","）（按：诗帖爲大楷，云出静木斋藏。","末署：「貞观三年。","」原連作一首，詳诗意及押韻，當爲二诗。","此帖前代未见著錄，静木斋亦不詳爲誰，是否魏徵所作，甚爲可疑。","今姑錄出，以俟考詳。","）。"]', '诗', 'shi', '', NULL, '缺題五古詩 二 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aadb1784-4224-4979-9c6f-522b7418eb6e', '元正賦附歌', '元正賦附歌', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["獻歲風光早，芳春節會多。","徑潘三月內，恣意飽相（五卷本作「經」）過。","（伯二八一九卷，又五卷本《王無功文集》卷一。","）。"]', '["獻歲风光早，芳春節會多。","徑潘三月內，恣意飽相（五卷本作「經」）過。","（伯二八一九卷，又五卷本《王無功文集》卷一。","）。"]', '诗', 'shi', '', NULL, '元正賦附歌 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9873f6-a81a-4536-8c82-49eac8fcd0b6', '靈龜（幷序）', '靈龟（幷序）', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["彼靈龜兮，潛伏平坻。","文列八卦，色合四時。","出遊芳蓮，入負神蓍。","吐故吸新，何慮何思？","赫赫王會，峨峨天府，謀猷所資，吉凶所聚。","爾有前鑒，爾既余（李抄本作「餘」）將，爾有嘉識，爾既余（李抄本作「餘」）輔。","爰施長網，載沈密羅，於沼於沚，於江於沱。","既剔既剝，是鑽是灼，姑取供用，焉知其佗。","嗚呼靈龜，孰謂爾哲？本緣末喪，命爲才絕。","山木自寇，膏火自滅，敢陳明辭，以告來裔。","（按：序文十六字，原與正文連寫。","今據文意析出。","）。"]', '["彼靈龟兮，潛伏平坻。","文列八卦，色合四时。","出游芳蓮，入負神蓍。","吐故吸新，何慮何思？","赫赫王會，峨峨天府，謀猷所資，吉凶所聚。","爾有前鑒，爾既余（李抄本作「餘」）將，爾有嘉識，爾既余（李抄本作「餘」）輔。","爰施长網，載沈密羅，於沼於沚，於江於沱。","既剔既剝，是鑽是灼，姑取供用，焉知其佗。","嗚呼靈龟，孰謂爾哲？本緣末喪，命爲才絕。","山木自寇，膏火自滅，敢陳明辞，以告来裔。","（按：序文十六字，原與正文連寫。","今據文意析出。","）。"]', '诗', 'shi', '', NULL, '靈龜（幷序） 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d339cd7f-8012-4e71-a23e-001bfe36f2c7', '郊園', '郊园', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["汾川勝地，姑射名辰。","月照山客，風吹俗人。","琴聲送冷，酒氣迎春。","閉門常樂，何須四隣。","。"]', '["汾川勝地，姑射名辰。","月照山客，风吹俗人。","琴声送冷，酒氣迎春。","閉门常乐，何須四隣。","。"]', '诗', 'shi', '', NULL, '郊園 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60bfe6c7-bf3c-4e08-8e58-bf14cab4ab14', '被徵謝病', '被徵謝病', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["漢朝徵隱士，唐年訪逸人。","還言北山曲，更坐東河濱。","枌榆三晉地，煙火四家隣。","白豕祠鄉社，青羊祭宅神。","拓畦侵院角，蹙水上渠漘。","臥病劉公幹，躬耕鄭子真。","橫裁桑節杖，豎翦竹皮巾。","鶴警琴亭夜，鶯啼酒甕春。","顏回惟樂道，原憲豈傷貧？","藉草邀新友，班荆接故人。","市門逢賣藥，山圃值肩薪。","相將共無事，何處犯囂塵！（按：《韻語陽秋》卷十一錄「巾」、「春」、「貧」三韻，題作《被召謝病》。","《全唐詩》卷三七收入，注出《西清詩話》，係沿《增修詩話總龜後集》卷四五之誤。","）。"]', '["漢朝徵隐士，唐年訪逸人。","還言北山曲，更坐东河濱。","枌榆三晉地，煙火四家隣。","白豕祠乡社，青羊祭宅神。","拓畦侵院角，蹙水上渠漘。","臥病劉公幹，躬耕鄭子真。","橫裁桑節杖，豎翦竹皮巾。","鹤警琴亭夜，鶯啼酒甕春。","顏回惟乐道，原憲豈傷貧？","藉草邀新友，班荆接故人。","市门逢賣藥，山圃值肩薪。","相將共無事，何处犯囂塵！（按：《韻語陽秋》卷十一錄「巾」、「春」、「貧」三韻，題作《被召謝病》。","《全唐诗》卷三七收入，注出《西清诗話》，係沿《增修诗話總龟後集》卷四五之誤。","）。"]', '诗', 'shi', '', NULL, '被徵謝病 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b940eb-6b6c-40fd-9907-41ea3cdbaab2', '春日山莊言志', '春日山莊言志', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["平子試歸田，風光溢眼前。","野樓全跨迥，山閣半臨煙。","入屋敧生樹，當堦逆涌泉。","翦茅通磵底，移柳向河邊。","崩砂猶有處，臥石不知年。","入谷開斜道，橫溪渡小船。","鄭玄唯解義，王烈鎮尋仙。","去去人間遠，誰知心自然。"]', '["平子試归田，风光溢眼前。","野楼全跨迥，山閣半臨煙。","入屋敧生樹，當堦逆涌泉。","翦茅通磵底，移柳向河邊。","崩砂猶有处，臥石不知年。","入谷开斜道，橫溪渡小船。","鄭玄唯解義，王烈鎮尋仙。","去去人间远，誰知心自然。"]', '诗', 'shi', '', NULL, '春日山莊言志 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e0e08d-5fad-43c9-a578-efea1cd79009', '獨坐', '独坐', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["託身千載下，聊思（《韻語陽秋》作「遊」）萬物初。","欲令無作有，翻覺實成虛。","周文方定策，秦帝即焚書。","寄語無爲者，知君悟有餘。","（按：《韻語陽秋》卷十一、《文獻通考》卷二三一、《經籍考》引《周氏涉筆》收前四句，《全唐詩》卷三七收入。","）。"]', '["託身千載下，聊思（《韻語陽秋》作「游」）万物初。","欲令無作有，翻覺實成虛。","周文方定策，秦帝即焚书。","寄語無爲者，知君悟有餘。","（按：《韻語陽秋》卷十一、《文獻通考》卷二三一、《經籍考》引《周氏涉笔》收前四句，《全唐诗》卷三七收入。","）。"]', '诗', 'shi', '', NULL, '獨坐 王績 shi');
